L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "desbloqueado -- se podrá arrastrar cuando termine este combate; mientras tanto no hay nada preparado. Después, |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "desbloqueado -- arrastra el aviso y luego usa |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "desbloqueado, pero el accesorio está |cffff8080desactivado|r, así que no hay aviso que arrastrar -- primero usa |cffffd100/manners on|r."
L["locked."] = "bloqueado."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "recuperar tu objetivo después de dar un beneficio: |cff00ff00activado|r -- se aplica cuando termine este combate; hasta entonces, una pulsación ejecuta la macro que ya está en el botón."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "recuperar tu objetivo después de dar un beneficio: |cffff0000desactivado|r -- se aplica cuando termine este combate; hasta entonces, una pulsación ejecuta la macro que ya está en el botón."
L["hand your target back after buffing: |cff00ff00on|r"] = "recuperar tu objetivo después de dar un beneficio: |cff00ff00activado|r"
L["hand your target back after buffing: |cffff0000off|r"] = "recuperar tu objetivo después de dar un beneficio: |cffff0000desactivado|r"
L["click logging: |cff00ff00on|r"] = "registro de clics: |cff00ff00activado|r"
L["click logging: |cffff0000off|r"] = "registro de clics: |cffff0000desactivado|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "modo detallado: |cff00ff00activado|r -- una línea en tu propio chat cuando alguien te da un beneficio, cuando un favor se da por devuelto, y cuando un clic falla, se salta a alguien o deja un favor pendiente"
L["verbose: |cffff0000off|r"] = "modo detallado: |cffff0000desactivado|r"
L["enabled."] = "activado."
L["disabled."] = "desactivado."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "no hay nadie en tu lista de excluidos. Haz Mayús + clic derecho en el aviso para añadir a quien esté mostrando."
L["never offered anything unless they buff you: %s"] = "nunca se les ofrece nada salvo que te den un beneficio: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "di a quién: |cffffd100/manners allow Name|r. |cffffd100/manners never|r muestra a todos los de la lista."
L["|cffffffff%s|r can be offered again."] = "A |cffffffff%s|r se le puede volver a ofrecer algo."
L["nobody called %s is on your never-offer list."] = "no hay nadie con el nombre %s en tu lista de excluidos."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "la pausa admite un número de minutos de 1 a %d, u off -- por ejemplo |cffffd100/manners snooze 15|r o |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "tu configuración está en el cuadro de |cffffd100Compartir como texto|r, en la pestaña Perfiles de las opciones -- haz clic en él, selecciona todo y cópialo."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "este texto es demasiado largo para volver a importarlo -- suele deberse a un cuadro de frases muy largo en la pestaña Qué digo. Acórtalo si quieres compartir esta configuración."
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "pega el texto de configuración en el cuadro de |cffffd100Compartir como texto|r, en la pestaña Perfiles, o escribe |cffffd100/manners import|r seguido del texto."
L["type |cffffd100/manners import|r followed by a settings string."] = "escribe |cffffd100/manners import|r seguido de un texto de configuración."
L["the self-test did not load -- reinstalling Manners should bring it back."] = "la autoprueba no se cargó -- reinstalar Manners debería recuperarla."
L["Tools for testing Manners on this client:"] = "Herramientas para probar Manners en este cliente:"
L["nothing has broken this session."] = "nada falló en esta sesión."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100los últimos %d de %d|r |cff808080(%d guardados)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100los últimos %d de %d|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua no se cargó -- revisa la lista de archivos del toc"
L["your own buff: not offered -- %s is switched off."] = "tu propio beneficio: no se ofrece -- %s está desactivado."
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "está DESACTIVADO en este perfil -- no se registra ni se ofrece nada; /manners on"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040este cliente no conoce %s|r -- Manners tiene mal los ID de hechizo de %s en %s. Por favor, reporta esta línea."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "favor pendiente: |cffffffff%s|r (quedan %d s, te dio un beneficio hace %d s)"
L["not watching for favours -- Manners is switched off."] = "no se vigilan los favores -- Manners está desactivado."
L["Favours are not recorded while \"People who buff me\" is off, on the Who to buff tab."] = "No se registran favores mientras \"Quienes me dan un beneficio\" esté desactivado, en la pestaña A quién ofrecer."
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "no se vigilan los favores -- |cffffd100Quienes me dan un beneficio|r está desactivado."
L["nobody has buffed you recently."] = "nadie te dio un beneficio últimamente."
L["your own buff: offered to you when you are missing it."] = "tu propio beneficio: se te ofrece cuando te falta."
L["your own buff: nothing you cast goes on yourself alone."] = "tu propio beneficio: nada de lo que lanzas va solo sobre ti."
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "el aviso está DESBLOQUEADO -- no dará ningún beneficio a nadie hasta que uses /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100en pausa hasta las %s|r -- sin aviso hasta entonces; /manners snooze off la termina"
L["|cffffd100mounted|r -- \"Hide the prompt while I'm mounted\" keeps it away until you get off"] = "|cffffd100sobre una montura|r -- la opción Ocultar el aviso al ir montado mantiene el aviso oculto hasta que desmontes"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100ahorrando maná|r -- hasta que vuelvas al %d%% de maná, solo se ofrece a ti y a quienes te dieron un beneficio o lo pidieron"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100ahorrando maná|r -- hasta que vuelvas al %d%% de maná, solo se ofrece a quienes te dieron un beneficio o lo pidieron"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100comprobación de disponibilidad|r -- tu grupo o banda va primero hasta que empiece el combate"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100grupos de banda|r -- en una banda, sin que lo pidan, solo se ofrece a los grupos %s"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100grupos de banda|r -- todos los grupos están desmarcados, así que en una banda no se ofrece a nadie sin que lo pida"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080prueba de /manners try preparada:|r %s -- bórrala con /manners try sin nada más"
L["queue now: %d"] = "cola ahora: %d"
L["queue if switched on: %d"] = "cola si estuviera activado: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "no existe |cffffd100/manners %s|r -- ¿quisiste decir |cffffd100/manners %s|r? |cffffd100/manners help|r los muestra todos."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "no existe |cffffd100/manners %s|r -- ¿quisiste decir |cffffd100/manners %s|r? |cffffd100/manners dev|r muestra las herramientas de prueba."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "¡Gracias de corazón, {name}! La primera ronda la pago yo en la forja."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Te debo una, {name}. Ya tienes amigos en la montaña."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "¡Gracias, {name}! Me las habría arreglado sin esto, ojo. Pero gracias."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "¡Bendiciones, {name}! Te abrazaría, pero luego te haría falta un sanador."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Deuda saldada, {name}. Jamás pagué una cuenta de taberna tan rápido."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "En la Cebatruenos diré que me salvaste la vida, {name}. ¡Gracias!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "¡Genial, {name}! Te tallaría una estatua, pero esto es más rápido."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "Los titanes nos tallaron en piedra, {name}, pero esto me ablandó. Gracias."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "Gracias, {name}. Te lo devuelvo antes de que se entere mi orgullo."
L["Thank ye, {name}. Muradin said a debt left unpaid rusts. Here, before it does."] = "Gracias, {name}. Muradin decía que las deudas se oxidan. Toma, antes de que pase."
L["Thank ye, {name}. Even me ram looked impressed, and he hates everybody."] = "Gracias, {name}. Hasta mi carnero quedó impresionado, y odia a todos."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "La Liga de Expedicionarios querrá saber dónde desenterraste esos modales, {name}."
L["Thank ye, {name}. Warmed me right down to me boots, that did."] = "Gracias, {name}. Eso me calentó hasta las botas."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "Excavé media Khaz Modan, {name}, y nunca di con una veta tan rica. Tu parte."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "Como la lumbre de Kharanos en una ventisca de Dun Morogh, {name}. Gracias."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "De vuelta, como el martillo de un Martillo Salvaje, {name}. Pero sin chichón."
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "Ven a Forjaz, {name}. Mi madre te dará de comer hasta reventar. ¡Gracias!"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "Le busqué pólvora por costumbre, {name}. Ni un grano. ¡Ahí va lo tuyo!"
L["Thank ye, {name}. Ye'll be the talk o' the Great Forge tonight."] = "Gracias, {name}. Esta noche no se hablará de otra cosa en la Gran Fundición."
L["Not even Magni could've done that kinder, {name}. Louder, aye. Thank ye."] = "Ni Magni lo habría hecho con más cariño, {name}. Con más ruido, sí. Gracias."
L["Thank ye, {name}. I'd offer me beard as surety, but I'm terrible fond of it."] = "Gracias, {name}. Te dejaría mi barba en prenda, pero le tengo mucho cariño."
L["Back at ye, {name}, quick as a ram goin' downhill. Stoppin' is the hard part."] = "Te lo devuelvo, {name}, rápido como un carnero cuesta abajo. Lo difícil es frenar."
L["Ye'd make a fine honorary dwarf, {name}. We'll work on yer singin'."] = "Serías un buen enano honorario, {name}. Lo de cantar ya lo iremos puliendo."
L["Thank ye, {name}. If ye ever need a tunnel dug, I'm yer dwarf."] = "Gracias, {name}. Si hay que cavar un túnel, aquí tienes a tu enano."
L["Keep yer powder dry and yer friends closer, me da said. Here, {name}."] = "Pólvora seca y amigos cerca, decía mi padre. Toma, {name}."
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "¡Claro, {name}, bastaba con pedirlo! Firme como un buen yunque."
L["Say no more, {name}. Stone and steel, here it comes."] = "Ni una palabra más, {name}. Piedra y acero, ¡ahí va!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Pídele ayuda a un enano, {name}, y la tendrás. A gritos."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "A ver, {name}. Agárrate, que yo todo lo hago a martillazos."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Claro, {name}, y de regalo una historia que no pediste. Pues verás..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff} de barril, con su espuma y todo, {name}."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "Hecho, {name}. Trabajo enano: macizo, barato y con garantía."
L["Easy, {name}. Last time I helped a gnome, it cost me both eyebrows."] = "Fácil, {name}. La última vez que ayudé a un gnomo, perdí las dos cejas."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "Claro, {name}. Un rey de la montaña nunca se niega. Soy más bien colina, pero cuenta."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "Forjado y templado, {name}. Ojo, que aún quema."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "Hecho antes de que acabaras, {name}. Un enano oye 'por favor' a través de la roca."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "Claro, {name}. En Dun Morogh se ayuda rápido o acabamos como dos témpanos."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "Claro, {name}. Primero lo notarás en las botas. Así sabes que es cosa de enanos."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "Claro, {name}. Si me niego, se lo pedirías a un gnomo, y la culpa sería mía."
L["Course, {name}. A dwarf who won't help is no dwarf. Just a short, grumpy rock."] = "Claro, {name}. Un enano que no ayuda no es un enano. Es una roca bajita y gruñona."
L["Mountaineer's promise, {name}: done right, done once. Mostly."] = "Palabra de montañero, {name}: bien hecho y a la primera. Casi siempre."
L["Fer you, {name}? Easy as findin' ale in Ironforge."] = "¿Para ti, {name}? Más fácil que encontrar cerveza en Forjaz."
L["Ask a Bronzebeard, {name}, and ye get it with both hands. Here."] = "Pídeselo a un Barbabronce, {name}, y te lo da con las dos manos. Toma."
L["Aye, {name}. Stand on that rock there. Good rock, that. Granite."] = "Claro, {name}. Súbete a esa roca de ahí. Buena roca, esa. Granito."
L["Aye, {name}. In the mines, ye shout and somebody comes runnin'. Here I am."] = "Claro, {name}. En las minas, gritas y alguien viene corriendo. Aquí estoy."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "Toma, {name}, un detallito para que no flaquees. Chiquito, como yo."
L["Off ye go, {name}, steady as the mountain."] = "Andando, {name}, firme como la montaña."
L["Here, {name}. Ale's for after; this is for before."] = "Toma, {name}. La cerveza, para después; esto, para antes."
L["Magni'd melt down his crown fer a friend, {name}. This is the cheaper option."] = "Magni fundiría su corona por un amigo, {name}. Esto sale más barato."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Un enano te cubre la espalda, {name}. Bueno, las rodillas. Casi."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Si un trogg te molesta, {name}, dile que te manda un enano. Y luego corre."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Si se pasa el efecto, {name}, dale un buen golpe. Así lo arreglamos todo."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Toma, {name}. También te daría algo de terquedad, pero la uso toda yo."
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "Ojo con los wendigos, {name}: peludos y gruñones. Como yo, pero con más hambre."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "Toma, {name}. Mi abuelo luchó en tres guerras con un pico y esto."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "Hecho por enanos, {name}: aguanta una caída del Puente Thandol. No lo pruebes."
L["Stonewrought Dam holds back a whole loch, {name}. This'll hold ye together."] = "La presa de Loch Modan contiene un lago entero, {name}. Esto te mantendrá de una pieza."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "No te secará las botas en Los Humedales, {name}. Nada lo hace. Lo demás, sí."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "Regla de minero, {name}: no bajes a un agujero sin lámpara, compañía y esto."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "Brann Barbabronce salió a explorar con menos, {name}, y escribió tres libros."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "Los montañeros lo juran, {name}. No escalarás mejor, pero caerás más blando."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "Las puertas de Forjaz jamás cayeron, {name}. Tú tampoco deberías. Toma."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "Mis primos de Roca Negra le habrían prendido fuego antes, {name}. Para dar suerte."
L["Off to Uldaman, {name}? Touch nothin' with runes on it. Trust a dwarf on that."] = "¿Vas a Uldaman, {name}? No toques nada que tenga runas. Hazle caso a un enano."
L["Fer the road, {name}. It's no keg o' Thunderbrew, but it travels better."] = "Para el camino, {name}. No es un barril de Cebatruenos, pero viaja mejor."
L["A gift from under the mountain, {name}. Mind yer head on the way out."] = "Un regalo de debajo de la montaña, {name}. Cuidado con la cabeza al salir."
L["A rifleman needs dry powder and a good mate, {name}. I'm the mate. Here."] = "Un fusilero necesita pólvora seca y un buen compañero, {name}. El compañero soy yo."
L["If yer road passes Grim Batol, {name}, keep walkin'. And take this."] = "Si tu camino pasa por Grim Batol, {name}, no te pares. Y llévate esto."
L["From one explorer to another, {name}. The League'll want yer notes after."] = "De explorador a explorador, {name}. Luego la Liga querrá ver tus notas."
L["If ye ride a gryphon, {name}, hold on with yer knees and yer prayers. Here."] = "Si montas en grifo, {name}, agárrate con las rodillas y con tus plegarias. Toma."
L["A dwarf never lets a friend walk into the dark unready, {name}. Take this."] = "Un enano nunca deja que un amigo baje a la oscuridad sin preparar, {name}. Toma."
L["Stone and hammer keep ye, cousin {name}!"] = "¡Piedra y martillo te guarden, pariente {name}!"
L["Three Hammers, one round, cousin {name}!"] = "¡Tres Martillos, una ronda, pariente {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "Apuesto a que somos primos de primos, {name}. La montaña es un pañuelo."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Dos enanos juntos, {name}. Pobre del que se nos ponga delante."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "Barbabronce, Martillo Salvaje, Hierro Negro, terráneos, {name}: una familia, cero acuerdos."
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "Entre tú y yo, {name}, le ganamos en terquedad a una montaña."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "Mi abuela saldría de la tumba si hiciera menos por los míos, {name}."
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "Los titanes nos tallaron en la misma roca, {name}. De ahí la cabeza dura."
L["Kin's kin, {name}, far from the mountain or under it."] = "Parientes somos, {name}, lejos de la montaña o bajo ella."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Ponte detrás de mí, {name}. Ya, ya lo sé. Agáchate un poco."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Bien, {name}: yo voy delante, tú te llevas el botín y luego discutimos."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Si empiezo a cantar, {name}, es que el combate fue bien. O muy mal."
L["Dwarves never leave a mate behind, {name}. Nor a keg, come to that."] = "Un enano no abandona a un compañero, {name}. Ni a un barril, ya puestos."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "¡Barbas al viento, {name}! Sin barba, pon cara feroz. Casi sirve igual."
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "Toco roca, {name}: maciza. Hoy no habrá derrumbes."
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "Nada de fuego cerca de mi mochila, {name}: casi todo es pólvora. Y un sándwich."
L["Dwarves don't retreat, {name}. Our legs aren't built fer it."] = "Los enanos no nos retiramos, {name}. Estas piernas no están hechas para eso."
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "No te alejes, {name}. Si todo se oscurece, sigue las palabrotas. Seré yo."
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "Un enano siempre sabe dónde es abajo, {name}. Arriba es cosa tuya."
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "Si algo es de piedra, {name}, déjame hablarle primero. Podría ser un primo."
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "Si cruje el techo, {name}, te aviso. Si me callo, corre."
L["Shields up, {name}. I'll hold the line. Mountains don't move, and neither do I."] = "Escudos arriba, {name}. Yo aguanto la línea. Las montañas no se mueven, y yo tampoco."
L["Watch fer troggs, {name}. Ugly, angry, and they go fer the ankles. My ankles."] = "Ojo con los troggs, {name}. Feos, rabiosos y van a por los tobillos. Los míos."
L["Mind the low beams, {name}. Says the only one here who never has to."] = "Cuidado con las vigas bajas, {name}. Lo dice el único que nunca se agacha."
L["I've a hammer, a grudge and a good breakfast in me, {name}. We'll be fine."] = "Llevo un martillo, un rencor y un buen desayuno en la tripa, {name}. Saldremos bien."
L["Ironforge was carved by folk who never quit halfway, {name}. Neither do we."] = "Forjaz la tallaron quienes nunca dejan nada a medias, {name}. Nosotros tampoco."
L["Keep up, {name}! Short legs, but we never stop movin'. That's the secret."] = "¡No te quedes atrás, {name}! Piernas cortas, pero nunca paramos. Ese es el secreto."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "¡Buenos días, {name}! Muy temprano para la cerveza. Casi. Toma esto antes."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "¡En pie con las forjas, {name}! El día de un enano empieza con un martillo y esto."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "¿Temprano, {name}? Qué va. La mina abrió hace dos horas. Toma."
L["Mornin', {name}. Me eyes are still abed. The rest o' me's ready."] = "Buenos días, {name}. Los ojos siguen en la cama; el resto de mí ya está listo."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "Buenos días, {name}. Gachas, pipa y esto. Las dos primeras son mías."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "Los carneros me sacaron de la cama al alba, {name}. A cabezazos contra la puerta. Toma."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "Buenos días, {name}. Aún me zumban los oídos de tanto cantar anoche. Toma."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Gracias, {name}. Deja que te lo devuelva antes de que un bardo lo cuente mal."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Muy amable, {name}. Que nadie diga que olvidamos a un amigo."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Gracias, {name}. Te daría un título, pero dicen que 'necesito permiso'."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Pagado al instante, {name}. En Ventormenta pedirían tres formularios y un sello."
L["Thanks, {name}. Prompter than Stormwind ever paid its stonemasons."] = "Gracias, {name}. Más puntual que Ventormenta pagando a sus canteros."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Mil gracias, {name}. Mi madre decía: devuelve siempre los favores. Y el plato."
L["Thank you, {name}. In Elwynn, no kindness goes home unanswered."] = "Gracias, {name}. En Elwynn, ningún favor vuelve a casa sin respuesta."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Me dejas en evidencia, {name}; debí pensarlo yo primero. Permíteme."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "Más reconfortante que el estofado de Poniente, {name}, y ese me hizo llorar. Gracias."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "Gracias, {name}. Se lo diré al alguacil Dughan. Le dará igual, pero se lo diré."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "¡Trabajo terminado, {name}! Así levantó mi abuelo media Ventormenta. Gracias."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "Villa del Lago acabará su puente antes de que olvide esto, {name}. O sea, nunca."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "En Kul Tiras dicen que un favor vuelve con la siguiente marea, {name}. Ahí va."
L["Thank you, {name}. Northshire's brothers would call that the Light at work."] = "Gracias, {name}. Los hermanos de Villanorte dirían que es obra de la Luz."
L["Not since Mum packed my lunches, {name}, have I felt so looked after. Thanks."] = "Desde que mamá me preparaba el almuerzo, {name}, nadie me cuidaba tanto. Gracias."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "A mis memorias, {name}. Capítulo nueve: 'Qué gente tan encantadora'. Gracias."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "Brindo por ti en El Cerdo y el Silbato, {name}. Luego por el cerdo. Y por el silbato."
L["Thanks, {name}. My next horse gets your name. He'll be a very good horse."] = "Gracias, {name}. Mi próximo caballo llevará tu nombre. Será un caballo estupendo."
L["I owe you a pint at the Lion's Pride, {name}. This will tide you over."] = "Te debo una jarra en el Orgullo de León, {name}. Con esto vas tirando."
L["Much obliged, {name}. In Elwynn that's neighbourly. Out here, it's heroic."] = "Mil gracias, {name}. En Elwynn, eso es ser buen vecino. Aquí fuera, es heroico."
L["Thanks, {name}. We humans don't live long enough to leave a kindness waiting."] = "Gracias, {name}. Los humanos no vivimos tanto como para dejar un favor esperando."
L["Thanks, {name}. If the Stockade held folk for kindness, you'd be in for life."] = "Gracias, {name}. Si en Las Mazmorras encerraran por bondad, te caería la perpetua."
L["By the Light, {name}, that was good of you. Uther would have liked you."] = "Por la Luz, {name}, qué detalle. A Uther le habrías caído bien."
L["Darkshire could use folk like you, {name}. Darkshire could use anyone, mind."] = "A Villa Oscura le vendría bien gente como tú, {name}. Bueno, le vendría bien cualquiera."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Claro, {name}. No te muevas y pon pose heroica; ayuda a los bardos."
L["Right away, {name}. Keep your shield high."] = "Enseguida, {name}. Mantén el escudo en alto."
L["More work? Gladly, {name}. It beats the lumber mill."] = "¿Más trabajo? Con gusto, {name}. Mejor que el aserradero."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Claro, {name}. Los humanos ayudamos mucho y prometemos más. Esto es ayudar."
L["Certainly, {name}. Westfall farm manners: you help first and ask why later."] = "Claro, {name}. En las granjas de Poniente se ayuda primero y se pregunta después."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "No te muevas, {name}, como una estatua del Valle de los Héroes. Encajarías."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "Enseguida, {name}. La Luz ayuda a quien se lo pide. Yo también, y más rápido."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "Regla de marinero, {name}: si alguien pide auxilio, remas. Toma."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "Claro, {name}. Espalda recta: mi viejo sargento nos vigila desde alguna parte."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "Claro, {name}. La cortesía es más rara que una noche en paz en el Bosque del Ocaso."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "Enseguida, {name}. Yo hago de arzobispo; tú haz como que te impresiona."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "Ventormenta renació de sus escombros, {name}. {buff} es pan comido."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "Claro, {name}. Antes que tú, un espantapájaros de Poniente. Larga historia."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "A la orden, {name}. Trato kultirense: apretón de manos, y te ahorro la canción."
L["Right away, {name}. Bolvar says the realm runs on small kindnesses."] = "Enseguida, {name}. Bolvar dice que el reino funciona a base de pequeños favores."
L["Gladly, {name}. Elwynn folk never turn away a neighbour, armour and all."] = "Con gusto, {name}. En Elwynn no se rechaza a un vecino, ni aunque venga con armadura."
L["Of course, {name}. The Light provides. Today it's using me as the courier."] = "Claro, {name}. La Luz provee. Hoy me usa a mí de mensajero."
L["Of course, {name}. Stormwind raised me on the Light, porridge and saying yes."] = "Claro, {name}. En Ventormenta me criaron con la Luz, gachas y decir que sí."
L["Right away, {name}. At Northshire we answered before the second bell."] = "Enseguida, {name}. En Villanorte respondíamos antes de la segunda campanada."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "Te espera un largo camino, {name}. Esto no lo acorta, pero ayuda."
L["Fair winds and following seas, {name}."] = "Buen viento y buena mar, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Toma, {name}. Los elfos tienen siglos para ser generosos; yo, cincuenta años."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Un detallito, {name}. Que no se enteren los guardias, que todos querrán uno."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Toma, {name}. Si un kóbold pregunta, tú no tienes ninguna vela."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Para ti, {name}. Un regalo humano: con cariño, con prisa y duro de pelar."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Ojo con los múrlocs, {name}. Toma; sé lo que le hacen a un pícnic."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Todo camino necesita un héroe, {name}. Hoy me toca a mí, por lo visto. Toma."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "No vayas al Bosque del Ocaso de noche, {name}. Siempre es de noche. Toma."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "Los gnolls de Crestagrana roban lo que no esté clavado, {name}. Esto va clavado."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "Si te topas con Hogger, {name}, lleva esto y un amigo. Sobre todo el amigo."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "La Luz y un buen par de botas, {name}. Ya tienes una de las dos cosas."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "Todo héroe de Ventormenta empezó con un favor y una espada prestada, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "Toma, {name}. Esto los Defias no pueden robarlo. Ya probaron con todo lo demás."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "Uther bendecía a desconocidos por el camino, {name}. Menos martillo, misma idea."
L["Take this, {name}. Goldshire custom: no traveller leaves empty-handed."] = "Toma, {name}. Costumbre de Villadorada: ningún viajero se va con las manos vacías."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "Los lobos de Elwynn parecen simpáticos, {name}. No lo son. Toma."
L["Lothar held the line with less, {name}. Granted, he had a very big sword."] = "Lothar resistió con menos, {name}. Claro que él tenía una espada enorme."
L["Westfall farmers share even in a bad year, {name}. They're all bad years now."] = "Los granjeros de Poniente comparten hasta en los años malos, {name}. Ahora todos lo son."
L["Redridge, Duskwood, Westfall, {name}: every road out of Elwynn gets worse."] = "Crestagrana, el Bosque del Ocaso, Poniente, {name}: cada camino que sale de Elwynn es peor."
L["Take this, {name}. The guards can't be everywhere. Out here, they're nowhere."] = "Toma, {name}. La guardia no puede estar en todas partes. Aquí fuera, no está en ninguna."
L["Bound for Hillsbrad, {name}? Southshore's still ours. Barely. Take this."] = "¿Vas a Trabalomas, {name}? Costasur sigue siendo nuestra. Por los pelos. Toma."
L["Stromgarde still stands, {name}, mostly out of stubbornness. So will you. Here."] = "Stromgarde sigue en pie, {name}, sobre todo por terquedad. Tú también aguantarás. Toma."
L["A Stormwind welcome, {name}: a smile, a blessing and the way to the inn."] = "La bienvenida de Ventormenta, {name}: una sonrisa, una bendición y el camino a la posada."
L["The Argent Dawn says the Light is for all who'll carry it, {name}. Carry some."] = "El Alba Argenta dice que la Luz es de quien quiera llevarla, {name}. Lleva un poco."
L["Arathor's children stand together, {name}."] = "Los hijos de Arathor, siempre unidos, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "¡Sangre humana, {name}! Rápido, fundemos un reino antes de comer."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Ventormenta o Boralus, {name}: da igual, nos quejaremos del tiempo."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "De humano a humano, {name}: no, yo tampoco sé por qué todo nos pasa a nosotros."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "Vida corta y mil tareas, {name}. Los humanos tenemos que ayudarnos."
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "Piedra de Ventormenta o roble kultirense, {name}: duramos más de lo esperado."
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "Los humanos, unidos, {name}. Los demás son más altos, viejos o peludos."
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "Los nuestros levantaron medio mundo con pan, terquedad y mala suerte, {name}."
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "No se lo digas a los enanos, {name}, pero la taberna la inventamos los humanos."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "No te alejes, {name}. Los humanos siempre ganamos por ser más."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Mantén la formación, {name}. No tenemos ninguna, pero mantenla igual."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Haré un plan, {name}, y luego lo ignoramos todos juntos."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "Todo héroe de las canciones tenía amigos, {name}. Nadie les canta. Yo sí."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Escudos arriba, {name}. Ventormenta me enseñó a marchar; a parar, nadie."
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "Si esto sale mal, {name}, nos reagrupamos en la posada. Táctica humana."
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "Nos hice una bandera, {name}. Es un pañuelo en un palo, pero es nuestra."
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "Lleva antorcha, {name}. Los humanos no vemos en la oscuridad, y lo odiamos."
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "Tú me cubres, {name}, y yo a ti. Lo demás, la Luz: tiene mejores vistas."
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "Los humanos siempre estamos a la altura, {name}. Tras tropezar un par de veces."
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "Hagámoslo bien, {name}. Algún elfo lo contará durante mil años."
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "Granjeros, marineros, panaderos, {name}: el ejército de Ventormenta. ¡Adelante!"
L["Form up, {name}. One steady line beats a crowd of brave fools. Lothar said so."] = "En formación, {name}. Una línea firme vence a una turba de valientes insensatos. Lo dijo Lothar."
L["We'll make Stormwind proud, {name}. Or give the town criers something to shout."] = "Ventormenta estará orgullosa, {name}. O los pregoneros tendrán algo que gritar."
L["Light keep us, {name}. And if it's busy, I've packed bandages."] = "Que la Luz nos guarde, {name}. Y si está ocupada, traigo vendas."
L["Everyone goes home, {name}. I promised somebody's mother. Probably yours."] = "Todos volvemos a casa, {name}. Se lo prometí a la madre de alguien. Seguramente a la tuya."
L["We look like a proper Stormwind patrol now, {name}. Shinier, even."] = "Ya parecemos una patrulla de Ventormenta, {name}. Y más relucientes."
L["Stay sharp, {name}. Lordaeron learned the hard way: never trust the bread."] = "No te despistes, {name}. Lordaeron lo aprendió por las malas: no te fíes del pan."
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. Te lo devuelvo hoy mismo, que para un kaldorei es correr."
L["Thank you, {name}. Elune smiles on the generous."] = "Gracias, {name}. Elune sonríe a los generosos."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Gracias, {name}. Hasta los fuegos fatuos brillan más, y mira que cuesta."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Elune lo vio, {name}. Lo ve todo, así que mejor te lo devuelvo."
L["Thank you, {name}. Kindness planted, kindness grown. Here."] = "Gracias, {name}. Bondad sembrada, bondad cosechada. Toma."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Gracias, {name}. Los Ancestros se enterarán. Son unos chismosos terribles."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Gracias, {name}. Les diré a las Centinelas que dejen de apuntarte."
L["My people never hurry, {name}. For you, an exception."] = "Mi pueblo nunca se apresura, {name}. Contigo, una excepción."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil, {name}. Que tus penas mengüen, como las mías ahora mismo."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "Renunciamos a la inmortalidad en Hyjal, {name}. Desde entonces, la bondad vale el doble."
L["My ears have gone a shade darker, {name}. Kaldorei blush there first."] = "Las orejas se me pusieron más oscuras, {name}. Los kaldorei nos sonrojamos por ahí."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "La corte de Azshara jamás regaló nada, {name}. Superaste a una reina."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "Los búhos giraron la cabeza al verlo, {name}. Una vuelta entera. Gran elogio."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "Vi partirse el mundo, {name}, pero no veré envejecer una deuda contigo. Toma."
L["All those centuries of memories, {name}, and this one goes near the front."] = "Tantos siglos de recuerdos, {name}, y este va a la primera fila."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "Hoy le hablaré de ti a la luna, {name}. Le encantan las buenas historias."
L["In Darnassus they'd sing of that, {name}. Quietly, for about a century."] = "En Darnassus le cantarían a eso, {name}. En voz baja, durante un siglo o así."
L["Thank you, {name}. A Sentinel settles a debt of honour by moonset. So do I."] = "Gracias, {name}. Una Centinela salda sus deudas antes de que se ponga la luna. Yo también."
L["Shan'do Stormrage would approve, {name}. He'll tell you himself, when he wakes."] = "El shan'do Tempestira lo aprobaría, {name}. Ya te lo dirá él cuando despierte."
L["The Cenarion Circle preaches balance, {name}. You've just tipped it my way."] = "El Círculo Cenarion predica el equilibrio, {name}. Acabas de inclinarlo a mi favor."
L["Better than a moonwell, {name}. Don't tell the priestesses I said so."] = "Mejor que una poza de la luna, {name}. No les digas a las sacerdotisas que lo dije."
L["Even Fandral would smile at that, {name}, and his face has forgotten how."] = "Hasta Fandral sonreiría con esto, {name}, y eso que su cara ya olvidó cómo."
L["Thank you, {name}. I'd send a hippogryph with my thanks, but they bite."] = "Gracias, {name}. Te mandaría las gracias con un hipogrifo, pero muerden."
L["That warms me like moonlight, {name}. Not very warm, I admit. Still, thank you."] = "Me reconforta como la luz de la luna, {name}. No calienta mucho, lo admito. Aun así, gracias."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Con gusto, {name}. No te muevas y deja que la luna te encuentre."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Claro, {name}. Las bendiciones de Elune son para compartirlas."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "¡Por fin, {name}! Llevo diez mil años esperando a que alguien lo pidiera."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Sin acertijos ni presagios de Elune, {name}. Un sí y punto, por una vez."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Claro, {name}. Pídelo en darnassiano y te regalo una reverencia."
L["Elune already said yes, {name}. I'm merely catching up."] = "Elune ya dijo que sí, {name}. Yo solo me pongo al día."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Claro, {name}. No te muevas y haz como que eres un árbol. Ayuda."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "Déjate ver, {name}. El último kaldorei que me lo pidió se fundió con las sombras."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "Desde luego, {name}. Pregúntale a un kaldorei lo que sea, menos la edad."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "En Darnassus, {name}, pedirían una poza de la luna y una sacerdotisa. Aquí basto yo."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "El último ejército que me pidió ayuda combatía demonios, {name}. Tú pides mejor."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "Con gusto, {name}. Considéralo un préstamo de Elune. Jamás cobra."
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "Un momento, {name}. Mi melena es más vieja que muchos reinos, y se enreda."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "El darnassiano tiene nueve palabras para decir 'sí', {name}. Te ahorro ocho."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "Claro, {name}. Las Centinelas pedirían una contraseña. Yo acepto 'por favor'."
L["Of course, {name}. I'll be swift. Swift for a kaldorei, that is. Do sit down."] = "Claro, {name}. Iré deprisa. Deprisa para un kaldorei, eso sí. Siéntate, anda."
L["Gladly, {name}. The Sentinels taught me to answer a call before it echoes."] = "Con gusto, {name}. Las Centinelas me enseñaron a acudir antes de que la llamada resuene."
L["Be still, {name}. What's done in haste is undone by nightfall, the druids say."] = "No te muevas, {name}. Lo que se hace con prisa se deshace al anochecer, dicen los druidas."
L["Gladly, {name}. Elune asks little of us: kindness, patience and good aim."] = "Con gusto, {name}. Elune nos pide poco: bondad, paciencia y buena puntería."
L["Of course, {name}. The forest gave me plenty. It would sulk if I didn't share."] = "Claro, {name}. El bosque me dio de sobra. Se enfurruñaría si no lo compartiera."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. Pisa suave: los árboles tienen el sueño ligero."
L["May the forest shelter you, {name}, wherever you roam."] = "Que el bosque te dé cobijo, {name}, allá donde vayas."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Un regalo desde las sombras, {name}. No, no mires. No me encontrarás."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Elune ilumina tu camino, {name}. Yo solo sostengo el farol."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "Los búhos te señalaron, {name}. Tienen opiniones muy firmes. Toma."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Tyrande insistiría, {name}, y nadie le lleva la contraria a Tyrande."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Toma, {name}. El último fue para un hipogrifo. Fue menos agradecido."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Ojo con la fauna, {name}. La mitad son druidas, y toda te vigila."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "Camina con Elune, {name}. Si está ocupada, camina con esto."
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "Ojo con los sátiros, {name}. Antes eran Altonato; aún se les nota el desdén."
L["The trees spoke well of you, {name}. I thought I'd add my word."] = "Los árboles hablaron bien de ti, {name}. Quise sumar mi palabra."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "Casi todos los fúrbolgs son amables, {name}. Esto es para los demás."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "El agua de una poza de la luna sería mejor, {name}, pero viaja mal. Esto no."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "Un regalo de Teldrassil, {name}. Desde allí arriba, casi se me cae."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "Charlaría, {name}, pero una charla kaldorei dura hasta la luna llena. Toma."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas, {name}: prepárate para luchar. Hecho. Ya lo estás."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "De parte de los kaldorei, la luna y un árbol muy viejo, {name}. Sobre todo, mía."
L["Ashenvale remembers every axe, {name}. Carry this, and leave yours sheathed."] = "Vallefresno recuerda cada hacha, {name}. Lleva esto y deja la tuya enfundada."
L["The Sentinels will know you're a friend, {name}. Probably. Wave a lot."] = "Las Centinelas sabrán que vienes en paz, {name}. Seguramente. Tú saluda mucho."
L["May the moon guide you, {name}, and this keep you until it rises."] = "Que la luna te guíe, {name}, y que esto te proteja hasta que salga."
L["Moonglade welcomes all who come in peace, {name}. So does this."] = "El Claro de la Luna acoge a quien llega en paz, {name}. Y esto también."
L["Darkshore is beautiful, {name}, and full of things that bite. Take this."] = "Costa Oscura es preciosa, {name}, y está llena de cosas que muerden. Toma."
L["My people learned the hard way not to hoard magic, {name}. So, here."] = "Mi pueblo aprendió por las malas a no acaparar magia, {name}. Así que toma."
L["Felwood was a forest like any other once, {name}. Stay well; it didn't."] = "Frondavil fue un bosque como cualquier otro, {name}. Cuídate; él no pudo."
L["Bound for Stonetalon, {name}? Mind the goblins' saws. The trees certainly do."] = "¿Vas a Sierra Espolón, {name}? Ojo con las sierras goblin. Los árboles ya lo tienen."
L["If you meet an Ancient, {name}, bow. They notice, and they never forget."] = "Si te cruzas con un Ancestro, {name}, haz una reverencia. Se dan cuenta y nunca olvidan."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Elune protege a sus hijos."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Claro que te vi, {name}. Hace falta un kaldorei para ver a un kaldorei."
L["Kaldorei to kaldorei, {name}: we gave up eternity, not each other."] = "De kaldorei a kaldorei, {name}: renunciamos a la eternidad, no a los nuestros."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Un kaldorei nunca deja a los suyos a oscuras, {name}. Salvo para esconderse."
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "Dos kaldorei, {name}, y ningún yelmo del mundo nos cabe con estas orejas."
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "¿Centinela, druida o cabeza dura, {name}? En una buena noche, yo soy las tres."
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "Entre los dos, {name}, sumamos veinte mil años diciendo 'eso ya lo probamos'."
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "Fundámonos con las sombras un día, {name}, a ver quién lo nota."
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "Nuestro shan'do duerme en el Sueño, {name}. Que su despertar valga la pena."
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "Nuestro pueblo escasea en el suelo, {name}, pero abunda en los árboles."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "¿Algo rápido, {name}? Para un kaldorei, habremos acabado antes de empezar."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Seré la sombra que no ves, {name}. No es un error: es el plan."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Elune vigila a todo el grupo, {name}. Yo solo soy quien la saluda."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "Diez mil años de compañeros, {name}. Este grupo está en lo más alto."
L["Stay close, {name}. We misplaced half a continent once. Not you, though."] = "No te alejes, {name}. Una vez perdimos medio continente. A ti, no."
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "Si caigo, {name}, no sufras: flotaré como fuego fatuo, con aire muy sabio."
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "Luché junto a Neltharion, {name}. Contigo ya salgo ganando."
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "Sígueme, {name}. Conozco estos caminos. Aunque la última vez eran un bosque."
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "Si fracasamos, {name}, te recordaré con cariño unos cuantos miles de años."
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "Llevo milenios viendo héroes cargar a ciegas, {name}. Probemos con los ojos abiertos."
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "Hago yo la primera guardia, {name}. Y la segunda. Un kaldorei apenas nota una noche."
L["Keep your voices low, {name}. The forest listens, and it has a long memory."] = "Baja la voz, {name}. El bosque escucha, y tiene memoria larga."
L["We held back the Legion with fewer than this, {name}. We'll be fine."] = "Contuvimos a la Legión con menos que esto, {name}. Saldremos bien parados."
L["A Sentinel never looses an arrow she'd want back, {name}. Choose your moments."] = "Una Centinela nunca suelta una flecha que quisiera recuperar, {name}. Elige el momento."
L["Dark in there, {name}? Follow me. The night is where my people live."] = "¿Está oscuro ahí dentro, {name}? Sígueme. La noche es el hogar de mi pueblo."
L["Moving out, {name}. Silent as owls if we can, silent as dwarves if we can't."] = "En marcha, {name}. Silenciosos como búhos si podemos; como enanos si no."
L["I'll watch the shadows, {name}. Nothing moves in them without my say."] = "Yo vigilo las sombras, {name}. Nada se mueve en ellas sin mi permiso."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "Salió la luna, {name}. Para un kaldorei, esto es media mañana."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "La gente sensata duerme, {name}. Elune y yo lo preferimos así."
L["Elune's light is on you, {name}. Here's a second layer."] = "La luz de Elune está sobre ti, {name}. Aquí tienes una segunda capa."
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "Por fin, oscuridad, {name}. Yo lo veo todo; el resto va a tientas."
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "Las mismas estrellas que vi hace diez mil años, {name}. Envejecieron mejor que yo."
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "Sale la luna, {name}. Todo kaldorei se despierta un poco y se da aires."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Buenos días, {name}. Mi pueblo durmió las mañanas durante milenios. Me adapto."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "Amanece, {name}. Elune se fue a dormir, así que la cubro yo."
L["The sun's up, {name}, and so, reluctantly, am I."] = "Salió el sol, {name}, y yo también, a regañadientes."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "Qué luz, {name}. Esto va con los ojos entrecerrados; Elune lo perdona."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "Amanece, {name}: la única hora en que se ve a un elfo de la noche. Rápido, toma."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "¿Madrugando, {name}? Yo, trasnochando. Quedemos a medio camino, con esto."
L["The shadows remember kindness, {name}. So do I."] = "Las sombras recuerdan la bondad, {name}. Y yo también."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Te lo agradezco, {name}. Los ren'dorei no olvidan un favor."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Gracias, {name}. Las voces te aprueban, y eso, francamente, me alarma."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Gracias, {name}. Pocos regalan algo a quien brilla de forma tan ominosa."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "En el Vacío la bondad escasea, {name}. Te la devuelvo antes de que lo note."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Lunargenta nos echó, {name}. Con gente como tú, cuesta que me importe."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Devuelto entero, {name}. Puede que salga algo morado. Es normal."
L["The Void only takes, {name}. I, however, give back."] = "El Vacío solo quita, {name}. Yo, en cambio, devuelvo."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "Gracias, {name}. Los susurros se callaron. Así sé que era sincero."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "Gracias, {name}. Sonreiría, pero dicen que inquieta. Así que imagínate una."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "Devuelto, {name}. Manos frías, corazón caliente: así somos los ren'dorei."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "Devuelto, {name}. Devuelto. Ahora mis hechizos tienen eco."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "El Vacío me ofreció saber prohibido, {name}. Tu regalo fue más bonito."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "Alleria dice que el Vacío se domina, {name}. La bondad, por lo visto, cuesta menos."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "Te lo agradezco, {name}. Casi todos nos dan de lado. Tú me diste esto."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "Gracias, {name}. Hasta mi sombra se inclinó, y nunca lo hace. La impresionaste."
L["As you wish, {name}. The shadows answer kindly today."] = "Como desees, {name}. Hoy las sombras están de buenas."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Dalo por hecho, {name}. El Vacío nos obedece a nosotros, no al revés."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Claro, {name}. Los susurros dijeron que no, así que sí."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Claro, {name}. Marchando {buff}, con una pizca de Vacío."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Claro, {name}. No te muevas, que las sombras son tímidas con los extraños."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Con gusto, {name}. Modales ren'dorei: el Vacío espera su turno."
L["Asked so nicely, {name}? Then you'll have my best."] = "¿Con tanta educación, {name}? Entonces tendrás lo mejor de mí."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "Claro, {name}. Mejor aquí, a la luz: en los rincones el Vacío se hace ideas."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "Claro, {name}. El Vacío preguntó por qué. Le dije 'modales'. Sigue sin entenderlo."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "Con gusto, {name}. Nadie nos pide nada salvo 'deja de susurrar, por favor'."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "Con gusto, {name}. Deja que termine de discutir conmigo. Ya está. Gané."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "Desde luego, {name}. Podría abrir una grieta hasta ahí, pero sería presumir."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "Hacer preguntas nos costó el exilio, {name}. Responder una, dicen, es bastante seguro."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "Claro, {name}. Un ligero escalofrío y un coro lejano son de lo más normal."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Un toque de sombra para ti, {name}. Es seguro. Casi siempre."
L["Walk carefully in the dark places, {name}."] = "Camina con cuidado en la oscuridad, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Un detalle de Telogrus, {name}. Está más limpio de lo que suena."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Toma, {name}. Si ves algún tentáculo, es puramente decorativo."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "Las sombras preguntaron por ti, {name}. Les dije que tuvieran modales."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Toma, {name}. Entramos en el Vacío para que tú no tuvieras que hacerlo."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "Revisé tu sombra, {name}. Nada acechando. Toma esto de todos modos."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Umbric te manda saludos, {name}. No es verdad, pero lo haría."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "Toma, {name}. Puede que te susurre un piropo. Haz como que no lo oíste."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "Toma, {name}. Aspecto siniestro, funciona de maravilla. Como yo."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "Toma, {name}. El Vacío tenía planes peores para ti. Los intercepté."
L["If the dark whispers at you today, {name}, pay it no mind. Take this."] = "Si hoy la oscuridad te susurra, {name}, no le hagas caso. Toma."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "Toma, {name}. Los ren'dorei no solemos ser la sorpresa agradable."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "Salí de Quel'Thalas solo con buena mano para lo oscuro, {name}. Te echo una."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "Toma, {name}. No agradezcas a las sombras, que luego piden algo. A mí, sí."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "Debo un favor por cada mirada siniestra que eché, {name}. Voy con mucho retraso."
L["We ren'dorei look after our own, {name}."] = "Los ren'dorei cuidamos de los nuestros, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Lunargenta se lo pierde, {name}. Sin ella nos va de maravilla."
L["Your whispers and mine should really meet sometime, {name}."] = "Tus susurros y los míos deberían conocerse algún día, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Dos ren'dorei juntos, {name}. Rápido, cara sombría. Es lo esperado."
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "Nadie más entiende lo del pelo, {name}. Antes era rubio. Creo."
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "Al final, Telogrus fue un hogar, {name}. Muy oscuro y con muchas corrientes."
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "De ren'dorei a ren'dorei, {name}: ¿qué te susurra tu Vacío? El mío no para de hablar de sopa."
L["Stay close, {name}. The whispers are much quieter in company."] = "No te alejes, {name}. Los susurros callan mucho más en compañía."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Si las sombras empiezan a dar órdenes, {name}, ignóralas. Yo suelo hacerlo."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "Vigila mi sombra, {name}. Se escapa cuando hay pelea."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Si me pongo a brillar en morado, {name}, tú sigue. Es que tengo ganas."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "Los ren'dorei somos buena compañía, {name}. Traemos la oscuridad de casa."
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "Si le hablo a la nada, {name}, tranquilidad. Si la nada contesta, preocúpate."
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "Si sale mal, abro una grieta, {name}. Solo cabe uno, pero te diré adiós."
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "Intenta disfrutarlo, {name}. A los ren'dorei rara vez nos invitan dos veces."
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "No apagues los faroles, {name}. No son para mí: así las sombras se portan mejor."
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "Tú vigila los rincones, {name}. Yo vigilaré lo que hay en ellos."
L["The Void promised me power, {name}. It never mentioned company this good."] = "El Vacío me prometió poder, {name}. Nunca mencionó tan buena compañía."
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "Si oyes susurros en plena pelea, {name}, son ánimos. Para nosotros, creo."
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "Si aparece algo de otro mundo, {name}, déjame a mí. Hablo un poco su idioma."
L["Night suits the ren'dorei, {name}. We match the decor."] = "La noche nos sienta bien, {name}. Vamos a juego con el decorado."
L["The shadows are longest now, {name}, and in a very generous mood."] = "Ahora las sombras son más largas, {name}, y están muy generosas."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "¿Tarde, {name}? Los susurros son de trasnochar. Últimamente, yo también."
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "Medianoche, {name}. La única hora en que mi sombra y yo coincidimos."
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "Hay estrellas, {name}. Vi lo que hay entre ellas, y me quedo con las estrellas."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "¡Gracias, {name}! Favor recibido, catalogado y devuelto."
L["Reciprocity engaged! Much obliged, {name}."] = "¡Reciprocidad activada! Mil gracias, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "Según mis cálculos, {name}, te debo exactamente una dosis de {buff}."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "¡Gracias, {name}! Te haría una máquina agradecedora, pero explotaría."
L["Thank you, {name}! Gnomeregan's finest couldn't have timed that better."] = "¡Gracias, {name}! Ni los mejores de Gnomeregan lo habrían cronometrado mejor."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "¡Qué amable, {name}! Devolverte el favor solo me costó cuatro esquemas."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "¡Rayos, {name}! Iba a inventar la gratitud, pero te me adelantaste."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "¡Ay, {name}, qué detalle! Mi corazón hace otra vez ese zumbidito."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "Anotado en mi diario de laboratorio, {name}, pág. 400: 'la gente es un encanto'."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "¡Espléndido, {name}! Te lo devuelvo ya, antes de que me dé por mejorarlo."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "¡Gracias, {name}! La bondad es una reacción reversible. Lo comprobé. Aquí tienes."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "Mi mecazancudo te saludaría, {name}, pero solo sabe caerse."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "Mi transportador lo habría mandado a Gadgetzan, {name}. ¡Mejor en mano!"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "¡Ay, gracias, {name}! No me sentía tan bien desde antes de los troggs."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "¡Mi próximo invento llevará tu nombre, {name}! Es un cañón muy pequeñito."
L["Thanks, {name}! Ironforge has been good to us gnomes, and so have you."] = "¡Gracias, {name}! Forjaz se portó bien con los gnomos, y tú también."
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "¡Estás en mi lista de gente favorita, {name}! Es corta. Casi todos son de cuerda."
L["Thanks, {name}! A gift with no gears in it. I didn't know they made those."] = "¡Gracias, {name}! Un regalo sin engranajes. No sabía que existieran."
L["Thank you, {name}! I'd pay you back with interest, but my abacus is in pieces."] = "¡Gracias, {name}! Te lo devolvería con intereses, pero mi ábaco está hecho pedazos."
L["When we retake Gnomeregan, {name}, you get a window seat. We'll add windows."] = "Cuando recuperemos Gnomeregan, {name}, tendrás asiento de ventanilla. Ya pondremos ventanas."
L["Exactly what I needed, {name}, and I didn't even have to build it. Thanks!"] = "Justo lo que necesitaba, {name}, y ni siquiera tuve que fabricarlo. ¡Gracias!"
L["The tall folk rarely notice us gnomes, {name}. You did. Thank you!"] = "La gente alta rara vez se fija en los gnomos, {name}. Tú sí. ¡Gracias!"
L["Tinker Town will hear all about you, {name}. Loudly, over the machinery."] = "Ciudad Manitas sabrá todo de ti, {name}. A gritos, por encima de la maquinaria."
L["It worked first time, {name}! Nothing I make works first time. Marvellous!"] = "¡Funcionó a la primera, {name}! Nada de lo que hago funciona a la primera. ¡Maravilloso!"
L["Request received, {name}! Processing... done!"] = "¡Solicitud recibida, {name}! Procesando... ¡hecho!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "¡Una mejora marchando, {name}! No te muevas, que calibro."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "¡Claro, {name}! Tengo una máquina para esto. Está en piezas, así que a mano."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "¡Por supuesto, {name}! Ponte sobre la X. No hay X. Ponte donde sea."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "¡Enseguida, {name}! Gafas puestas. No es por ti, es que me gustan."
L["{buff}, {name}? Simple in theory and practice. Suspicious!"] = "¿{buff}, {name}? Fácil en teoría y en la práctica. ¡Sospechoso!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "¡Con mucho gusto, {name}! Aparta bien manos, pies y cejas."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "¡Enseguida, {name}! Tres pasos atrás. Cuatro. Cinco. Ahí, perfecto."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "¡Con gusto, {name}! Mejor que ordenar muelles por tamaño. Aunque eso también tiene su gracia."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "¡Buena petición, {name}! Sin piezas móviles. La próxima vez le pongo alguna."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "¿Modelo estándar o de lujo, {name}? Son iguales. 'De lujo' suena mejor."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "¡Marchando, {name}! Recién salido del taller: calentito y apenas humeando."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "¡Aprobado, {name}! Sellado, firmado y archivado en 'faltaría más'."
L["Of course, {name}! A twist of the gyromatic micro-adjustor... there!"] = "¡Claro, {name}! Un giro al microajustador giromático... ¡listo!"
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "Un gnomo no rechaza un problema, {name}. A veces hasta los fabrica. ¡Toma!"
L["Right away, {name}! Tested on three volunteers and one very brave squirrel."] = "¡Enseguida, {name}! Probado con tres voluntarios y una ardilla muy valiente."
L["Happy to, {name}! Measure twice, zap once. Gnome proverb. Well, my proverb."] = "¡Con mucho gusto, {name}! Mide dos veces y electrocuta una. Proverbio gnomo. Bueno, mío."
L["Of course, {name}! The High Tinker says help where you can. I can, so here!"] = "¡Claro, {name}! El Manitas Mayor dice que hay que ayudar donde se pueda. Yo puedo, ¡toma!"
L["On it, {name}! I'll need a ladder. No? Just this, then."] = "¡Marchando, {name}! Necesitaré una escalera. ¿No? Pues solo esto."
L["Delighted, {name}! It's nice to fix something that doesn't fight back."] = "¡Qué alegría, {name}! Da gusto arreglar algo que no se defiende."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "No te muevas, {name}, es totalmente seguro. ¡Seguramente!"
L["Science says you need this, {name}. Who am I to argue?"] = "La ciencia lo exige, {name}. ¿Quién soy yo para discutir?"
L["A small upgrade for you, {name}. No cogs required."] = "Una pequeña mejora para ti, {name}. Sin engranajes."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Tómalo, {name}, tengo repuesto. Tengo tres repuestos de todo."
L["Try this, {name}! Version one had legs. Version two is much better."] = "¡Prueba esto, {name}! La versión uno tenía patas. La dos es mucho mejor."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "El Manitas Mayor manda compartir nuestro genio, {name}. ¡Muestra gratis!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "¡Gnomeregan para siempre, {name}! Esto dura bastante menos, pero es gratis."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Mido poco, {name}, pero regalo a lo grande. ¡Toma!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "¡No te preocupes, {name}! Funcionó con la gallina, y está encantada."
L["Field notes say it works on everyone, {name}. Let's make it unanimous!"] = "Las notas de campo dicen que funciona con todos, {name}. ¡Que sea unánime!"
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "Talla única, {name}, de gnomo a tauren. Lo medí. El tauren tuvo paciencia."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "¡Toma, {name}! Mi lanzarredes siempre me atrapa a mí. Esto no."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "La navaja multiusos gnómica hace doce cosas mal, {name}. Esto hace una bien."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "La garantía no cubre troggs, fuego de dragón ni entusiasmo, {name}. ¡Disfruta!"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "¡Nada en la manga, {name}! Bueno, una llave inglesa y dos fusibles. Nada raro."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "¡Toma, {name}! Es pequeño, pero la piedra angular también, y mira lo que sostiene."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "Te explicaría cómo funciona, {name}, pero hacen falta tres días y una pizarra."
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "Si oyes un tictac, {name}, es mi reloj de bolsillo. Casi seguro."
L["A dash of arcane, a pinch of science, {name}, and no troggs involved. Here!"] = "Una pizca de arcano, otra de ciencia, {name}, y ningún trogg de por medio. ¡Toma!"
L["Ironforge took us gnomes in when we needed it, {name}. I'm passing it along."] = "Forjaz acogió a los gnomos cuando lo necesitábamos, {name}. Yo hago lo mismo contigo."
L["Here, {name}! It doesn't whistle, spin or catch fire. I'm working on all three."] = "¡Toma, {name}! No silba, no gira ni se incendia. Estoy trabajando en las tres cosas."
L["Here, {name}! Unwrapped, sorry. The wrapping machine wrapped itself again."] = "¡Toma, {name}! Sin envolver, perdona. La máquina de envolver se ha vuelto a envolver sola."
L["My mechanostrider wanted to give you something, {name}. It lacks the hands."] = "Mi mecazancudo quería darte algo, {name}. Le faltan las manos."
L["Off on an adventure, {name}? Take this, and bring me back anything that ticks."] = "¿Te vas de aventura, {name}? Llévate esto y tráeme cualquier cosa que haga tictac."
L["Reliable as the Deeprun Tram, {name}. That's a compliment, I promise. Here!"] = "Fiable como el Tranvía Subterráneo, {name}. Es un cumplido, te lo prometo. ¡Toma!"
L["For you, {name}! One part magic to two parts confidence. Mostly confidence."] = "¡Para ti, {name}! Una parte de magia por dos de confianza. Sobre todo confianza."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "¡Por Gnomeregan, {name}! Da gusto hablar con alguien de mi altura."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "¡Entre gnomos, {name}! Yo sujeto el plano; tú, el extintor."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Carne o engranajes, {name}, somos gnomos. Unos solo piden más aceite."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "De gnomo a gnomo, {name}: apagaste el reactor, ¿verdad?"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "¡Dos gnomos, {name}! Apilados, somos casi un elfo de la noche."
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "Tú revisas mis cuentas, {name}, yo las tuyas, y nos ofendemos en silencio."
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "Aún me debes un piñón, {name}. Todos los gnomos me deben un piñón."
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "Un día, {name}, volveremos a Gnomeregan codo con codo. Con la luz encendida."
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "Entre gnomos, {name}: sabemos que va a explotar y nos morimos por verlo."
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "¿Construimos algo enorme, {name}? ¿Solo por ver la cara que ponen los altos?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "¡Calibración del grupo completada, {name}! Que nadie toque nada brillante."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "Hice los cálculos, {name}: contigo aquí, ganamos. Redondeé hacia arriba."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Si grito '¡ojo!', {name}, no te toques el ojo. La última vez salió fatal."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Formación, {name}: los altos delante; yo, en la retaguardia estratégica."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "¡Uno por cabeza, {name}! Las piezas estándar son el secreto de una buena máquina."
L["My plan, {name}: step one, survive. Step two is still in development."] = "Mi plan, {name}: paso uno, sobrevivir. El paso dos sigue en desarrollo."
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "Calma, {name}. Si algo sale mal, tendré un aparato para eso. La semana que viene."
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "Si desaparezco, {name}, mira bajo la bota más cercana. Con modales."
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "Cuando acabemos, {name}, quiero muestras. De todo. Del grandote, primero."
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "Hoy todas las explosiones son a propósito, {name}. Ya decidiré cuáles después."
L["Clipboard ready, {name}! Today I'm writing down everyone's heroics."] = "¡Libreta lista, {name}! Hoy apunto las hazañas de todos."
L["If we get separated, {name}, follow the smoke. It'll be me."] = "Si nos separamos, {name}, sigue el humo. Seré yo."
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "Que nadie pierda dedos, {name}. Ya los conté. Luego vuelvo a contarlos."
L["Ready, {name}? Spare gears, spare fuses, spare plan. Possibly two."] = "¿Todo listo, {name}? Engranajes, fusibles y un plan de repuesto. Quizá dos."
L["Leave the traps to me, {name}. I've built most of them. Not these. But similar."] = "Deja las trampas para mí, {name}. Construí casi todas. Estas no. Pero parecidas."
L["Before we go in, {name}: has anyone seen my wrench? It's mildly important."] = "Antes de entrar, {name}: ¿alguien ha visto mi llave inglesa? Es un poquito importante."
L["For Gnomeregan, {name}! And for everywhere else, while we're at it."] = "¡Por Gnomeregan, {name}! Y por todos los demás sitios, ya puestos."
L["If I get carried off, {name}, please retrieve my notes first. Then me."] = "Si algo me lleva a rastras, {name}, recupera primero mis notas. Luego a mí."
L["This is an experiment, {name}. Hypothesis: we win. Let's go and test it."] = "Esto es un experimento, {name}. Hipótesis: ganamos. Vamos a comprobarla."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "¡Buenos días, {name}! En pie desde las tres: la tostadora pedía motor nuevo."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "¡Buenos días, {name}! El café se prepara solo. Aprendió. Preocupante."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "¡Temprano, {name}! Lo mejor llega antes del desayuno: ideas y explosiones."
L["Morning, {name}! Tinker Town's been clanking since dawn, and so have I. Here!"] = "¡Buenos días, {name}! Ciudad Manitas traquetea desde el alba, y yo también. ¡Toma!"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "¿Madrugando, {name}? Soñé con un piñón mejor y no pude esperar. ¡Toma!"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "¡Buenos días, {name}! Hoy el sol está algo flojo. Tengo pendiente arreglarlo."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "La Luz premia la bondad, {name}. Yo solo hago el reparto exprés."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Te devuelvo tu regalo."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Gracias, {name}. Te llevaría en el Exodar, pero ya viste cómo aterriza."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Regalo sincero, {name}: los naaru zumban más fuerte. Te lo devuelvo."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Muy amable, {name}. En Argus lo habríamos tallado en cristal. Toma."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "En doce mundos, {name}, la bondad fue el único idioma que no tuve que aprender."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Qué detalle, {name}. Casi compensa lo de la Legión. Casi."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Gracias, {name}. Te lo diría en draenei, pero se tarda once minutos."
L["Thank you, {name}. My people call that a debt of honour. Here."] = "Gracias, {name}. Mi pueblo lo llama deuda de honor. Toma."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "Sargeras le ofreció regalos a mi pueblo, {name}. Huimos. El tuyo me lo quedo."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "Gracias, {name}. Hui de demonios por las estrellas, pero nunca de una deuda."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "Gracias, {name}. Te incluyo en mis oraciones. La lista empieza en Argus."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "La Legión nos quitó un mundo, {name}. Gente como tú nos lo devuelve a trocitos."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "Diste primero, {name}. Un profeta lo llamaría presagio. Yo lo llamo modales."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "Cortesía de la Luz, {name}. Me pide que añada: 'bien hecho'."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Claro, {name}. Los naaru guían tus pasos; esto les da más brío."
L["Gladly, {name}. The Light answers those who ask."] = "Con gusto, {name}. La Luz responde a quien la llama."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Velen previó que lo pedirías, {name}. Yo preví que diría que sí."
L["The Light is not rationed, {name}. Take as much as you like."] = "La Luz no está racionada, {name}. Toma toda la que quieras."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Claro, {name}. Dejé atrás a la Legión Ardiente; esto no es nada."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Al instante, {name}. Pezuñas firmes, cristales zumbando, ¡ahí va!"
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Con gusto, {name}. Seguí a un cristal parlante por las estrellas. Esto es fácil."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "Claro, {name}. Velen nos enseñó paciencia. Por suerte, aquí no hace falta."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "Con gusto, {name}. Los naaru nunca dicen que no. Dicen 'mmm', pero significa sí."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "En el Exodar esto requería tres cristales y una oración, {name}. Toma: la oración."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "Claro, {name}. Solo rechazo a demonios, y casi nunca piden por favor."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "Con gusto, {name}. Tras tanto exilio, sé lo que cuesta pedir."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "Claro, {name}. Mi pueblo cruzó las estrellas buscando amistad. Misión cumplida."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "Pide a un draenei, {name}: un sí, una bendición y tal vez clase de historia."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "La Luz está contigo, {name}. Ve en paz. O, por lo menos, con esto."
L["Walk in the Light, {name}. May it shelter you always."] = "Camina en la Luz, {name}. Que siempre te proteja."
L["Take this, {name}. My people always travel Light."] = "Toma, {name}. Mi pueblo viaja con poco equipaje y mucha Luz."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Toma, {name}. La Legión siempre está al llegar. Lo sé bien."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Hoy se me acabaron los milagros, {name}. ¿Te sirve {buff}?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "Para el camino, {name}. El mío ya dura veinticinco mil años."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Bendición de naaru, {name}. Bueno, estuve cerca de uno. Cuenta igual."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Toma, {name}. Brilla un poco. Todo lo nuestro brilla."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "Toma, {name}. Los draenei hacemos la maleta para el fin del mundo. Práctica no falta."
L["Take this, {name}. The crystals only hum like that for friends."] = "Toma, {name}. Los cristales solo zumban así con los amigos."
L["The naaru shine on all, {name}. Here is your share."] = "Los naaru brillan para todos, {name}. Aquí tienes tu parte."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "Un desconocido me dio pan en Bruma Azur, {name}. Aún se lo estoy devolviendo."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "Velen ve mil futuros, {name}. Yo solo veo uno: tú, más a salvo. Toma."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "No bebas de los arroyos de Bruma de Sangre, {name}. Esto sí, tómalo."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "Magia eredar de antes de la caída, {name}. Solo nos quedamos con la buena. Toma."
L["Archenon poros, {name}! The children of Argus look after one another."] = "¡Archenon poros, {name}! Los hijos de Argus se cuidan entre sí."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "El hogar está donde se encuentran dos draenei, {name}. Hoy, aquí."
L["We crossed the stars on the same ship, {name}. That still means something."] = "Cruzamos las estrellas en la misma nave, {name}. Eso aún significa algo."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Cola en alto, {name}. Argus se enorgullecería de nuestro exilio."
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "Dos draenei, {name}: sumamos casi cincuenta mil años de preocupaciones."
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "Cuernos, cascos y confianza, {name}. La Legión nunca les encontró cura."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "Pueblo de Velen, {name}: exiliado, esperanzado y educadísimo."
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "A la tercera va la vencida, {name}. Nos toca un mundo que se quede quieto."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "No te alejes, {name}. Ya perdí un mundo; este grupo no lo suelto."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Veinticinco mil años huyendo, {name}. Con amigos se camina mejor."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "Los naaru lo llamarían comunión, {name}. Yo lo llamo buena suerte."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "Vi acabarse mundos, {name}. Lo que nos espera apenas me preocupa."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "No nos separemos, {name}. A la Luz le cuesta menos encontrarnos si estamos juntos."
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "No te alejes, {name}. Los draenei tenemos mucha práctica en irnos a toda prisa."
L["We draenei take the long view, {name}. This fight will be a footnote."] = "Los draenei miramos lejos, {name}. Este combate será una nota al pie."
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "Yo voy delante, {name}. Quien nos aceche verá dos metros y medio de optimismo."
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "Los draenei seguimos a profetas, {name}. Hoy me conformo con seguirte a ti."
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "El Exodar llevaba a miles, {name}, y este grupito me da más seguridad."
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "Hombro con hombro, {name}. El mío está algo más alto, pero la idea es la misma."
L["A short prayer for the party, {name}. The long one would take an age."] = "Una oración corta por el grupo, {name}. La larga duraría una era."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Mil gracias, {name}. Gilneas nunca olvida un favor, y mi hocico tampoco."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Gracias, {name}. Tienes mi gratitud, y mi mejor aullido."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Gracias, {name}. Si los huargen tuviéramos cola, estaría meneándola."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Tienes mi amistad de por vida, {name}. La lealtad es lo nuestro."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "Mi bestia quiere gruñir, {name}. Mi lado gilneano insiste en dar las gracias."
L["Thank you, {name}. I'd offer a hand, but mine have claws now."] = "Gracias, {name}. Te daría la mano, pero ahora tengo garras."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Pasamos años tras una muralla, {name}. Tú haces que parezca una tontería."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Gracias, {name}. Te ganaste un sitio junto al fuego. El bueno."
L["Thank you, {name}. Gilneas had a word for folk like you: neighbour."] = "Gracias, {name}. En Gilneas teníamos una palabra para gente como tú: vecino."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "Te lo devuelvo con flema gilneana, {name}. Los colmillos van por su cuenta; ni caso."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "Gracias, {name}. Me quitaría el sombrero, pero ya no me cabe con estas orejas."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "Gracias, {name}. Los demás me rascan las orejas y cruzan los dedos."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "Devuelto, {name}. Un gilneano paga sus deudas; un huargen, a la carrera."
L["My mother would have had you round for tea, {name}. Thank you."] = "Mi madre te habría invitado a tomar el té, {name}. Gracias."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Desde luego, {name}. No te muevas, que no muerdo. Mucho."
L["Right you are, {name}. Stand steady now."] = "Entendido, {name}. Aguanta firme."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "Enseguida, {name}. ¡Sin moverse! Por una vez, lo digo yo."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Con gusto, {name}. Llueva o haga sol, y en Gilneas, llueve."
L["Certainly, {name}. Mind the claws."] = "Claro, {name}. Cuidado con las garras."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "No digas más, {name}. Estas orejas te oyeron antes de que lo pensaras."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Claro, {name}. Lo pediste mejor que el último que me tiró un palo."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "Con gusto, {name}. Poca gente pide favores a un lobo de dos metros. Me encanta."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "Desde luego, {name}. Me quedo en esta forma. La otra arma un escándalo."
L["Straight to business without tea, {name}? How un-Gilnean."] = "¿Directo al grano sin un té, {name}? Qué poco gilneano."
L["Of course, {name}. In Gilneas, nobody had to ask twice."] = "Claro, {name}. En Gilneas nadie tenía que pedir dos veces."
L["Of course, {name}. It would be rude to keep you waiting."] = "Claro, {name}. Sería de mala educación hacerte esperar."
L["Of course, {name}. Anything but a bath."] = "Claro, {name}. Lo que sea menos un baño."
L["Stay off the moors after dark, {name}. Take this."] = "No salgas a los páramos de noche, {name}. Toma esto."
L["Keep your wits about you, {name}. Something is always hunting."] = "Mantén los ojos abiertos, {name}. Siempre hay algo cazando."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Te lo habría traído antes, {name}, pero me paré a perseguir algo."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Para ti, {name}. No, no quiero premio. Bueno. Quizá uno pequeñito."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Los gilneanos siempre ofrecen, {name}. Las garras son parte del atuendo."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Remedio gilneano, {name}. Cura resfriados, penas y maldiciones. La mía, no."
L["Run with this, {name}. Trust me, I know about running."] = "Corre con esto, {name}. Hazme caso, de correr sé mucho."
L["Brought you this, {name}. Don't make a fuss over it."] = "Te traje esto, {name}. No le des importancia."
L["Here, {name}. Gilnean roads were never safe alone, and nor are these."] = "Toma, {name}. Los caminos de Gilneas nunca fueron seguros a solas, y estos tampoco."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "Para ti, {name}. No todo lo que merodea tuvo mi buena crianza."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "De buena familia gilneana, {name}. El pelaje es nuevo; los modales, de siempre."
L["Someone did this for me in Duskhaven once, {name}. I never forgot."] = "Una vez, en Gilneas, alguien hizo esto por mí, {name}. Nunca lo olvidé."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "Liam habría gritado '¡Por Gilneas!', {name}. Yo solo diré: por ti."
L["Tal'doren's druids taught me to leash the beast, {name}. It lets me do this."] = "Los druidas de Tal'doren me enseñaron a dominar a la bestia, {name}. Por eso puedo hacer esto."
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "Ten cuidado por ahí, {name}. Te lo dice alguien a quien mordieron una vez."
L["Here, {name}. In Gilneas we'd have sent it with a jar of preserves."] = "Toma, {name}. En Gilneas lo habríamos enviado con un tarro de mermelada."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "Toma, {name}. Te dejaría mi abrigo, pero no se quita."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "Toma, {name}. Barbilla alta, pelo sin erizar. Mi lema."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "La maldición nos une, {name}, pero Gilneas nos une más."
L["No need to explain the ears to you, {name}."] = "A ti no tengo que explicarte las orejas, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Pelaje, niebla y lluvia, {name}. Solo en Gilneas se entienden las tres."
L["Pack looks after pack, {name}. Always has."] = "La manada cuida de los suyos, {name}. Siempre."
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "¿Tú también sueltas tanto pelo, {name}? Con lo nuestro tejemos un tercer huargen."
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "Dos huargen, {name}. Algún gato está pasando un mal día."
L["Honestly, {name}, do you ever forget which form you left home in?"] = "En serio, {name}, ¿nunca se te olvida con qué forma saliste de casa?"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "Entre gilneanos, {name}: los lobos más educados de todo Azeroth."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Normas de la manada, {name}: nadie se aleja y nadie menciona las pulgas."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Otra vez en manada, {name}. No sabía cuánto lo echaba de menos."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "Oleré los problemas antes que nadie, {name}. La única ventaja de la maldición."
L["If I howl, {name}, it's a battle cry. Howl back if you like."] = "Si aúllo, {name}, es un grito de guerra. Aúlla tú también si quieres."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Adelante, {name}. Yo voy al trote: poco digno, pero rapidísimo."
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "Si me paro a mirar una pared, {name}, hay algo detrás. O es solo una pared."
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "Tras años en la Muralla de Cringris, {name}, esto contigo son vacaciones."
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "Después, {name}, una buena taza de té. Antes, una buena paliza."
L["If I limp back, {name}, don't fuss. Worgen mend quickly."] = "Si vuelvo cojeando, {name}, ni caso. Los huargen sanamos rápido."
L["When we rest, {name}, I'll take first watch. I hear everything anyway."] = "Cuando descansemos, {name}, hago yo la primera guardia. Total, lo oigo todo."
L["Stay together, {name}. Being a lone wolf is overrated."] = "No nos separemos, {name}. Lo de lobo solitario está sobrevalorado."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "De noche otra vez, {name}. Saco lo mejor y lo peor de mí. Esto es lo mejor."
L["Look at that moon, {name}. Gilneas taught us not to trust it."] = "Mira qué luna, {name}. Gilneas nos enseñó a no fiarnos de ella."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Gilneas de noche era niebla y pasos, {name}. Hoy los pasos soy yo."
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "En Gilneas había toque de queda al anochecer, {name}. Ya se vio por qué."
L["Something out there keeps rustling, {name}. Stay close; I'll look."] = "Algo no deja de moverse ahí fuera, {name}. No te alejes; voy a mirar."
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "De noche, {name}: orejas alerta, hocico atento, modales puestos. Dos de tres bastan."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Buenos días, {name}. Habría madrugado, pero la alfombra del hogar calentaba tanto..."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Huele a lluvia esta mañana, {name}. En Gilneas todo olía a lluvia."
L["Up already, {name}? I've been prowling since first light."] = "¿Ya en pie, {name}? Yo llevo merodeando desde el alba."
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "Buenos días, {name}. Té, tostadas y afeitado. Ahora afeitarme lleva su rato."
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "Buenos días, {name}. Los pájaros me despertaron y yo a ellos. Era lo justo."
L["Morning, {name}. The fog's lifting, which it never did in Gilneas."] = "Buenos días, {name}. La niebla se levanta; en Gilneas nunca lo hacía."
L["Throm-ka, {name}! Honour is repaid."] = "¡Throm-ka, {name}! El honor queda saldado."
L["You give freely, {name}. I return the favour."] = "Das sin pedir nada, {name}. Te devuelvo el favor."
L["Orcs keep their thanks short, {name}. Thanks."] = "Los orcos somos de pocas palabras, {name}. Gracias."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Un orco lo devuelve todo por duplicado, {name}. Golpes y favores."
L["You helped me, I help you, {name}. That is the old way."] = "Tú me ayudaste, yo te ayudo, {name}. Es la vieja usanza."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "Antes te lo habría pagado con un jabalí, {name}. Esto se conserva mejor."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Deber algo pica más que la arena de Durotar, {name}. Listo. Ya no pica."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Esto es fuerte, {name}. Ahora podría tumbar a un kodo. Y tú también."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "Emboscada de bondad, {name}. Ningún orco se entrena para eso. Contraataco."
L["Honour is a debt, {name}, and orcs pay on the spot."] = "El honor es una deuda, {name}, y los orcos pagamos al momento."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "Un orco recuerda un favor como una cicatriz, {name}: con cariño y siempre."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "Te daría mi hacha, {name}, pero aún no tenemos tanta confianza. Toma esto."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "Gracias, {name}. Mi lobo te gruñó. Así es como él da las gracias."
L["I've had gifts from shamans and chieftains, {name}. None came so freely."] = "Recibí regalos de chamanes y jefes de clan, {name}. Ninguno tan desinteresado."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "Antes tomamos fuerza de demonios, {name}. Tus condiciones son mucho mejores."
L["The spirits saw that, {name}. They'll remember it, and so will I."] = "Los espíritus lo vieron, {name}. Lo recordarán, y yo también."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "Lo grabaré en el mango de mi hacha, {name}. Junto a las muescas. Gracias."
L["Kindness unasked is rare as rain in Durotar, {name}. Returned."] = "Un favor sin pedirlo es tan raro como la lluvia en Durotar, {name}. Devuelto."
L["In my clan, {name}, a gift is answered with a bigger one. Here."] = "En mi clan, {name}, un regalo se responde con otro mayor. Toma."
L["A Frostwolf never counts what a friend gives, {name}. Only what he gives back."] = "Un Lobo Gélido nunca cuenta lo que da un amigo, {name}. Solo lo que devuelve."
L["The camps taught us who our friends are, {name}. You're one. Here."] = "Los campos nos enseñaron quién es amigo, {name}. Tú lo eres. Toma."
L["Thanks, {name}. Thrall says the Horde's strength is its friends. You count."] = "Gracias, {name}. Thrall dice que la fuerza de la Horda son sus amigos. Tú cuentas."
L["Good. Strong. Kind. Three things I respect, {name}. Have this."] = "Bondad. Fuerza. Amabilidad. Tres cosas que respeto, {name}. Toma."
L["Grom would have roared his thanks, {name}. I'll spare your ears and send this."] = "Grom te habría rugido las gracias, {name}. Yo te ahorro los oídos y te mando esto."
L["Dabu, {name}. It is done."] = "Dabu, {name}. Hecho."
L["Hold still, {name}. Strength for the fight ahead."] = "No te muevas, {name}. Fuerza para la batalla que viene."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Pide ayuda a un orco y la tendrás, {name}. Pide sutileza y ya puedes esperar."
L["Help, yes. Hugging, no. Hold still, {name}."] = "Ayuda, sí. Abrazos, no. No te muevas, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "¿Quieres {buff}? Tienes {buff}, {name}. Siguiente."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "No te encojas, {name}. Mi cara de ayudar es igual que mi cara de pelear."
L["Short question, short answer, {name}: yes."] = "Pregunta corta, respuesta corta, {name}: sí."
L["Done, {name}. I was a peon once; I never refuse honest work."] = "Hecho, {name}. Fui peón; nunca rechazo un trabajo honrado."
L["A challenge, {name}? Ah, a request. I accept either way."] = "¿Un desafío, {name}? Ah, una petición. Acepto igual."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "Sí, {name}. Estaba afilando el hacha, pero puede esperar. Siempre espera."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "En el Valle del Honor esto costaría un duelo, {name}. Para ti, basta un gesto."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "¿Ahora, {name}? Ahora. Un orco no conoce la palabra 'luego'."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "Ahí va {buff}, {name}. Estilo orco: rápido, directo y algo bruto."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "No te muevas, {name}. Lo lanzo como un hacha arrojadiza. Rara vez fallo."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar, {name}. Significa 'victoria'. Hoy también significa 'sí'."
L["Done, {name}. If you need anything carried, hit or shouted at, ask again."] = "Hecho, {name}. Si hay que cargar, golpear o gritarle a algo, vuelve a pedirlo."
L["You ask straight, {name}. I answer straight. Here."] = "Pides sin rodeos, {name}. Respondo sin rodeos. Toma."
L["The shamans say the spirits help those who stand still, {name}. Stand still."] = "Los chamanes dicen que los espíritus ayudan a quien no se mueve, {name}. No te muevas."
L["A good request, {name}: clear, brave and short. Like a good battle plan."] = "Buena petición, {name}: clara, valiente y corta. Como un buen plan de batalla."
L["Done, {name}. Thrall says help freely. I say help quickly. Both right."] = "Hecho, {name}. Thrall dice: ayuda gratis. Yo digo: ayuda rápido. Los dos acertamos."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "¡Lok'tar ogar, {name}! Para la batalla. Una pelea de taberna también cuenta."
L["Blood and thunder, {name}! Go and earn your glory."] = "¡Sangre y trueno, {name}! Ve a ganarte la gloria."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "Entre orcos, {name}, hacerte más fuerte es decir 'me caes bien'."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "¿Un orco regalando cosas? Ni una palabra, {name}. Arruina la imagen."
L["The Warchief wants us diplomatic, {name}. This is my diplomacy."] = "El Jefe de Guerra nos quiere diplomáticos, {name}. Esta es mi diplomacia."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Pégale a algo por mí, {name}. O quémalo. A los orcos nos da igual."
L["Don't thank me, {name}. Just win, and do it loudly."] = "No me des las gracias, {name}. Gana, y que se oiga."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Daría un discurso, {name}, pero son casi todo gritos. Tómalo y ya."
L["An orc at your back, {name}, even when I'm not there. Take this."] = "Un orco a tu espalda, {name}, aunque yo no esté. Toma."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "'Golpea primero', decía Grom, {name}. Así que toma, antes de que lo pidas."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "Toma, {name}. El bruto que ignora a un camarada se gana un sermón. Mío."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "Los Lobo Gélido comparten la caza, {name}. Hoy no cacé nada: comparto esto."
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "Camina a lo Durotar, {name}: cabeza alta, sol en la nuca, escórpido bajo el pie."
L["Here, {name}. The spirits favour the generous."] = "Toma, {name}. Los espíritus favorecen a los generosos."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "Un orco regala dos cosas, {name}: consejos y esto. Sáltate los consejos."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "Los Baldíos no tienen fin, {name}. Solo más y más zhevras. Toma."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "Fuerza para tu brazo, {name}. El honor, ya veo, lo traes de casa."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "Mi lobo quería darte su hueso, {name}. Lo convencí de cambiarlo por esto."
L["Any grunt in Razor Hill would do the same, {name}. Most would shout first."] = "Cualquier bruto de Cerrotajo haría lo mismo, {name}. Casi todos gritarían antes."
L["For the fight ahead, {name}. There's always one. Orcs plan for it."] = "Para la pelea que viene, {name}. Siempre hay una. Los orcos cuentan con ello."
L["We were slaves once, {name}. Now we choose whom we help. Today, it's you."] = "Una vez fuimos esclavos, {name}. Ahora elegimos a quién ayudar. Hoy, a ti."
L["Go, {name}, and let your enemies hear you coming. Or don't. Surprise works too."] = "Ve, {name}, y que tus enemigos te oigan llegar. O no. La sorpresa también funciona."
L["A gift from Durotar, {name}. Like the land: rough, warm and short on shade."] = "Un regalo de Durotar, {name}. Como la tierra: áspero, cálido y con poca sombra."
L["The elements are fickle, {name}. I am not. Take this."] = "Los elementos son caprichosos, {name}. Yo no. Toma."
L["Strength, {name}. Not the kind you lift. The kind you keep."] = "Fuerza, {name}. No la que levanta peso. La que se conserva."
L["Nobody crosses the Barrens alone if an orc can help it, {name}. Here."] = "Nadie cruza los Baldíos solo si un orco puede evitarlo, {name}. Toma."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "¡Throm-ka, {name}! La sangre de los clanes corre fuerte en ti."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "¡Sangre orca, {name}! Por fin alguien que grita a mi volumen."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Lobo Gélido, Grito de Guerra o Roca Negra, {name}: reñimos como familia."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Entre orcos sobran las palabras, {name}. Mejor. Se me acabaron."
L["Grunt or shaman, {name}, it's the same stubborn blood."] = "Bruto o chamán, {name}, la misma sangre terca."
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "Dos orcos, {name}, y nadie gritó todavía. Los chamanes lo llamarán presagio."
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "Nuestros clanes seguro que se pelearon, {name}. Como todos. Asunto zanjado."
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "Entre orcos, {name}, 'victoria o muerte' es nuestra forma de decir 'hasta luego'."
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "Tus colmillos y los míos vieron días peores, {name}. Hoy es uno mejor."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "El plan, {name}: le pegamos. ¿Preguntas? ¿No? Buen plan."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Partida de guerra de verdad, {name}: gritos, rabia y, por fin, un solo bando."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "No te separes de la partida, {name}. La unión hace la fuerza. Y las hachas."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Si caes, {name}, te saco a cuestas. Quejándome todo el camino, pero te saco."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Pelea bien, {name}, y esta noche hay hoguera para ti. Y fanfarronadas."
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "Nadie huye, {name}. Irse a paso ligero se permite. Apenas."
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "Voy yo primero, {name}. Tengo el cráneo más duro de aquí, y a mucha honra."
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "Cuando suenen los tambores, {name}, carga. No hay tambores. Tarareo yo."
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "Cúbreme la espalda, {name}. El frente lo veo: es lo que golpeo."
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "Hoy somos un clan, {name}: el Clan de Los Que Vinieron. El mejor que hay."
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "Si entra algo grande por esa puerta, {name}, es mío. Si es más grande, nuestro."
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "Las cicatrices son historias, {name}. Que hoy salgan cortas."
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "Antes había consejos de guerra, {name}. Ahora, yo señalando cosas."
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "Si cargo antes de tiempo, {name}, no es impaciencia. Es tradición."
L["Form up, {name}! Shamans in the middle, fools at the front. I'm at the front."] = "¡En formación, {name}! Chamanes en medio, insensatos delante. Yo voy delante."
L["Tonight we feast, {name}. First, we earn it."] = "Esta noche, festín, {name}. Pero antes hay que ganárselo."
L["If I fall, {name}, sing about it loudly in Orgrimmar. Lie a little."] = "Si caigo, {name}, cántalo bien alto en Orgrimmar. Exagera un poco."
L["Strength and honour, {name}. And if we run low on honour, more strength."] = "Fuerza y honor, {name}. Y si nos falta honor, más fuerza."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Gracias, {name}. Me alegraría el corazón, si aún latiera."
L["Such warmth, for one so cold? Returned in full, {name}."] = "¿Tanto calor para un cuerpo frío? Te lo devuelvo, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Gracias, {name}. Me sonrojaría, pero la sangre ya no me llega a la cara."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Mi gratitud eterna, {name}. En mi caso, va al pie de la letra."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Muy amable, {name}. Pasé de 'cadáver' a 'cadáver algo animado'."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "Eso lo sentí, {name}, y ya siento muy poco. Toma, siente esto."
L["Thank you, {name}. That's the first colour I've seen all week."] = "Gracias, {name}. Es el primer color que veo en toda la semana."
L["Thank you, {name}. Kindness above ground; I'd almost forgotten it happens."] = "Gracias, {name}. Bondad en la superficie; casi había olvidado que existía."
L["Too kind, {name}. Returned, with a little grave chill on it."] = "Qué amable, {name}. Te lo devuelvo, con un poco de frío de tumba."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "El último regalo que recibí fue la peste, {name}. El tuyo es mucho mejor."
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "Gracias, {name}. No me tocaba nada tan fresco desde que cayó Lordaeron."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "Sylvanas dice que saldamos toda deuda, {name}. Rara vez habla de las buenas."
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "Mi postura mejoró, {name}. Venía torcida desde la Tercera Guerra. Gracias."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "Pagado ya, {name}. Los Renegados no guardamos deudas. Se pudren."
L["Thank you, {name}. I've an eternity to remember this, and I intend to."] = "Gracias, {name}. Tengo una eternidad para recordarlo, y pienso hacerlo."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "Gracias, {name}. Lo guardo a buen recaudo. Entre mis costillas hay hueco."
L["Thank you, {name}. Once I'd have baked you a pie for that."] = "Gracias, {name}. Antes te habría horneado un pastel por esto."
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "Le hablaré de ti a la Dama Oscura, {name}. A ella le dará igual; a mí, no."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "Favor devuelto, {name}. Hasta mis moscas están impresionadas."
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "En todos mis años con la Plaga, nadie me dijo esto nunca, {name}. Gracias."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "Brindaré por ti esta noche, {name}. Se sale todo, pero cuenta la intención."
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "La Dama Oscura desconfía de todo regalo, {name}. Yo me arriesgo y te mando otro."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "Gracias, {name}. Entras en mi lista de motivos para seguir. Es corta."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "Gracias, {name}. Sin contrato ni letra pequeña. Varimathras debería tomar nota."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "Tierra de tumba y gratitud, {name}: todo lo que tengo. Mejor la gratitud."
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "Gracias, {name}. La eternidad se hace larga; esto fue lo mejor de la década."
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "Faranell querría apuntes sobre esa reacción, {name}. Yo solo te la devuelvo."
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "Gracias, {name}. Lordaeron tuvo modales. Qué bien que alguien los guardó."
L["Even the Deathguard would nod at that, {name}, and they nod at nothing."] = "Hasta los de la Guardia de la Muerte asentirían, {name}, y ellos no asienten a nada."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "Por ti tocaría las campanas de Lordaeron, {name}, pero ya solo tocan a difunto."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "Gracias, {name}. Cuando vuelva a Rémol, le pondré tu nombre a una calabaza."
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "Gracias, {name}. Mi más allá estaba muy dejado. Le diste un buen repaso."
L["Most of the living wouldn't have bothered, {name}. I'll resent them, not you."] = "La mayoría de los vivos ni se habría molestado, {name}. El rencor, para ellos; no para ti."
L["Better than anything I've pulled out of Undercity's sewers, {name}. Thanks."] = "Mejor que nada de lo que he sacado de las cloacas de Entrañas, {name}. Gracias."
L["Thank you, {name}. One tip in return: never drink what an apothecary hands you."] = "Gracias, {name}. Un consejo a cambio: nunca bebas lo que te dé un boticario."
L["Arthas took everything I had, {name}. You've given a little back. Thank you."] = "Arthas me lo quitó todo, {name}. Tú me has devuelto un poco. Gracias."
L["Thank you, {name}. Catching kindness beats catching the plague. I've done both."] = "Gracias, {name}. Mejor contagiarse de bondad que de la peste. He probado las dos."
L["Certainly, {name}. Try not to die. It's overrated."] = "Desde luego, {name}. Intenta no morir. Está sobrevalorado."
L["You need only ask, {name}. The dead are patient."] = "Basta con pedirlo, {name}. Los muertos somos pacientes."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Pídele un favor a un muerto, {name}. Rara vez tenemos otros planes."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Claro, {name}. Apártate un poco, que a veces se me cae algo."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Un momento, {name}. El rigor mortis no perdona la mano de lanzar."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Da gusto que me pidan algo, {name}, aparte del camino al cementerio."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "Con gusto, {name}. Así me distraigo del olor. Del mío, digo."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "Claro, {name}. No te muevas: mi puntería se va cuando se me va el ojo."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "En Entrañas nadie dice 'por favor', {name}. Casi todos gorgotean. Aquí tienes."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "¿Solo {buff}, {name}? Los boticarios siempre piden también una muestra."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "Me levanto en cuanto me llaman, {name}. Viejo trauma. Aquí tienes."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "Lo que sea, {name}. Dentro de lo razonable, y de la razón que me queda."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "Claro, {name}. Diría 'sobre mi cadáver', pero eso ya se probó."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "Ya voy, {name}. Un muerto no se entretiene. Se arrastra con decisión."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "Claro, {name}. El libre albedrío es un regalo. Yo lo gasto en cosas así."
L["At once, {name}. I've had far worse requests from the Apothecarium."] = "Enseguida, {name}. Los boticarios me han pedido cosas mucho peores."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "Claro, {name}. Tras un invierno en las Tierras de la Peste, esto son vacaciones."
L["{buff}, {name}? With the Dark Lady's compliments."] = "¿{buff}, {name}? Con los saludos de la Dama Oscura."
L["Of course, {name}. I don't sleep or eat, so I may as well be useful."] = "Claro, {name}. No duermo ni como, así que al menos seré útil."
L["Glad to, {name}. The Scourge used my hands for worse."] = "Con gusto, {name}. La Plaga usó mis manos para cosas peores."
L["Certainly, {name}. The apothecaries taught me a steady hand. Mostly on rats."] = "Desde luego, {name}. Los boticarios me enseñaron a tener buen pulso. Sobre todo con ratas."
L["The Dark Lady said serve the Horde, {name}. She never said sulk about it."] = "La Dama Oscura nos mandó servir a la Horda, {name}. Nunca dijo que de mala gana."
L["Right away, {name}. In Deathknell they woke me with far ruder requests."] = "Enseguida, {name}. En Camposanto me despertaron con peticiones mucho más groseras."
L["Silverpine's worgen never ask this nicely, {name}. You're a pleasant change."] = "Los huargen de Argénteos nunca piden con tanta educación, {name}. Qué cambio tan agradable."
L["Stay among the living a little longer, {name}."] = "Quédate entre los vivos un poco más, {name}."
L["Take this, {name}. The grave can wait."] = "Toma, {name}. La tumba puede esperar."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "Sanaba en Lordaeron, {name}. Morí yo, pero la costumbre no."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Gratis, {name}. Los boticarios te habrían hecho firmar algo."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Un regalo de ultratumba, {name}. No te preocupes, lo lavé."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "Sé dónde acaban los héroes, {name}. Vivo allí. Toma esto."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Toma, {name}. Aprendí por las malas que al otro lado no te llevas nada."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "Toma, {name}. Es lo único que tengo que no está un poco húmedo."
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "No te desmorones, {name}. Créeme: luego cuesta encontrar los trozos."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "Toma, {name}. Las Tierras de la Peste están llenas de quien no lo hizo."
L["A small kindness, {name}. Tirisfal could use more of them."] = "Un pequeño detalle, {name}. A Tirisfal le hacen falta más."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "La niebla de Tirisfal se mete en todo, {name}. Esto también, pero se agradece."
L["Here, {name}. Kept cool for you, like everything I carry."] = "Toma, {name}. Te lo guardé fresquito, como todo lo que llevo."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "Sobreviví a todos mis conocidos, {name}. Prefiero no sobrevivirte. Toma."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "Perdona, {name}. Dicen que acecho. Intento acechar para bien."
L["Out of my own pocket, {name}. The dead don't need much."] = "De mi propio bolsillo, {name}. Los muertos no necesitamos mucho."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "Yo ya tuve el peor día posible, {name}. Evitemos el tuyo."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "Sopla viento de las Tierras de la Peste, {name}. Toma, y respira por la boca."
L["The crows have been watching you, {name}. Let's disappoint them."] = "Los cuervos no te quitan ojo, {name}. Vamos a decepcionarlos."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "Toma, {name}. Tirisfal solo da calabazas y rencores. Yo te doy esto."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "Toma, {name}. Lo único en Entrañas que no hay que hervir antes."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "La eternidad es larga, {name}, y pasé buena parte ensayando esto."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "Para el camino, {name}. Hecho en Entrañas: mantenlo lejos del fuego."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "Toma, {name}. No huele a nada, y dicen que es lo mejor que tengo."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "Los Renegados somos pacientes, {name}, pero esto no podía esperar."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "Sin ataduras, {name}. Rompí las mías cuando el Rey Exánime perdió el control."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "Fresco de Tirisfal, {name}. Bueno, fresco para Tirisfal."
L["Take this, {name}. The Bulwark taught me to look out for the living."] = "Toma, {name}. El Baluarte me enseñó a cuidar de los vivos."
L["Passing Pyrewood, {name}? Take this. The village has a bad habit after dark."] = "¿Pasas por Aldea Piroleña, {name}? Toma. El pueblo tiene una mala costumbre al anochecer."
L["The Scarlets would call this unholy, {name}. From me, they'd say it of bread."] = "La Cruzada Escarlata lo llamaría impío, {name}. Viniendo de mí, lo diría hasta del pan."
L["We Forsaken must look after each other, {name}."] = "Los Renegados tenemos que cuidarnos, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Entre cadáveres, {name}, te conservas de maravilla."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "¿Pierdes un dedo, {name}? Te presto uno. Hoy por ti, mañana por mí."
L["Is your jaw clicking too, {name}, or is that just me?"] = "¿A ti también te cruje la mandíbula, {name}, o solo a mí?"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "Victoria para Sylvanas, {name}. Pequeñita esta vez, pero nuestra."
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "¿Rémol o Camposanto, {name}? Todos despertamos en algún sitio. A mí, cripta húmeda."
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "Si la Plaga viene a buscarnos, {name}, no estaremos en casa. Nunca más."
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "El Baluarte aguanta, {name}, y nosotros también. Cosidos, pero aguantamos."
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "Lordaeron nos vio nacer dos veces, {name}: de niños y de Renegados."
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "En Rasganorte, {name}, el Rey Exánime sigue rabiando por nuestra culpa. Bien."
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "La Dama Oscura nos quiere de una pieza, {name}. O casi."
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "Hueles a Tirisfal, {name}. Entre Renegados, eso es un cumplido."
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "Tenemos toda la eternidad, {name}. No la pasemos esperando el ascensor."
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "Entre Renegados, {name}: el atajo de las cloacas no es ningún atajo."
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "Si pregunta la Guardia de la Muerte, {name}, estamos de patrulla. Muy, muy lenta."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "Los nuestros reciben pocas gentilezas, {name}. Que queden en familia."
L["Same grave dirt, same Dark Lady, {name}. That's family."] = "La misma tierra de tumba, la misma Dama Oscura, {name}. Eso es familia."
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "No pierdas la fe, {name}. En nosotros, digo. Contesta más que la Luz."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "Los muertos cuidan de los muertos, {name}. Los vivos podrían aprender algo."
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "Los dos conocemos una tumba por dentro, {name}. Pésimo servicio. Sin vistas."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "Sigue con vida, {name}. La lista de espera de Entrañas ya es larguísima."
L["If I fall down, {name}, give it a minute. Old habit."] = "Si caigo, {name}, espera un minuto. Es la costumbre."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Voy delante, {name}. ¿Qué es lo peor que puede pasar? ¿Otra vez?"
L["Keep upwind of me, {name}. It's better for morale."] = "Que el viento no te lleve mi olor, {name}. Es por la moral."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "En el último grupo en que estuve, {name}, desperté en una cripta. Mejoremos eso."
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "Si algo muerde, {name}, mándamelo. Ya no me queda nada apetecible."
L["Heal the others first, {name}. I run on spite and embalming fluid."] = "Cura primero a los demás, {name}. Yo funciono a rencor y líquido de embalsamar."
L["If this goes badly, {name}, don't worry. I've died before; it passes."] = "Si esto sale mal, {name}, tranquilidad. Ya me morí una vez; se pasa."
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "Estuve en la Plaga y contra ella, {name}. Este lado tiene mejor compañía."
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "No te alejes, {name}. Yo no grito al ver necrófagos. Fuimos vecinos."
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "Crucé las Tierras de la Peste de noche, {name}. Esto es un paseo."
L["The corpse at the back is me, {name}. Please don't bury it."] = "El cadáver del fondo soy yo, {name}. Por favor, no lo entierres."
L["Stay together, {name}. It's easier than putting somebody back together."] = "No nos separemos, {name}. Es más fácil que volver a coser a alguien."
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "No me esperes, {name}. Me arrastro, pero me arrastro para siempre. Ya llegaré."
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "Aparta de mí las antorchas, {name}. Soy leña seca desde hace años."
L["Don't check me for a pulse after, {name}. It only worries people."] = "Después no me busques el pulso, {name}. Solo asusta a la gente."
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "Cuidado con los charcos verdes, {name}. Sé lo que hacen. Soy lo que hacen."
L["Lordaeron fell with me in it, {name}. This won't be worse."] = "Lordaeron cayó conmigo dentro, {name}. Esto no será peor."
L["Stick together, {name}. The apothecaries pay well for strays."] = "No te separes, {name}. Los boticarios pagan bien por los extraviados."
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "Si esto acaba bajo el agua, {name}, tranquilidad. Respirar ya es opcional."
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "La Dama Oscura no confía en nadie, {name}. Yo hago una excepción con este grupo."
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "Cuando ganemos, {name}, bebidas en la taberna de Rémol. Invito yo. El riesgo es tuyo."
L["Don't mind the flies, {name}. They're with me."] = "No hagas caso a las moscas, {name}. Vienen conmigo."
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "Yo vigilo la retaguardia, {name}. Nada sorprende a quien no puede parpadear."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "Los muertos tenemos horarios terribles, {name}. Da gusto tener compañía."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Medianoche, {name}: la mejor hora para andar por ahí cuando no se debe."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "Los vivos duermen, {name}. Los Renegados lo llamamos el turno tranquilo."
L["Late, {name}? In Undercity, this is lunchtime."] = "¿Tarde, {name}? En Entrañas es la hora de comer."
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "A esta hora rondaba la Plaga, {name}. Ahora es nuestra."
L["Night, {name}. The one time nobody can tell I'm pale."] = "Noche, {name}: la única hora en que nadie nota mi palidez."
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "Oscuro como Entrañas, {name}. Por fin, una iluminación decente."
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "Niebla, luna y un toque de moho, {name}. Tiempo de Tirisfal como debe ser."
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "Las almas en pena empiezan a cantar a esta hora, {name}. Tranquilidad. Solo ensayan."
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "Estrellas sobre Tirisfal, {name}. Lo único ahí arriba que nunca se pudrió."
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "Pasada la medianoche, {name}. Los cementerios, en calma. Los buenos, al menos."
L["An owl just saw me and left, {name}. They're sensible birds."] = "Un búho me vio y se fue, {name}. Son aves sensatas."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "¿Ya es de día, {name}? Llevo toda la noche en pie. Y toda la última década."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "Salió el sol, {name}. Me quedo a la sombra, si no te importa. Se me pela todo."
L["Early start, {name}. Of all things, I miss yawning."] = "Qué temprano, {name}. Quién lo diría: echo de menos bostezar."
L["Sunrise, {name}. My least favourite colour."] = "Amanece, {name}. Mi color menos favorito."
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "Amanecer en Tirisfal, {name}: gris, y luego algo menos gris. Glorioso."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "Buenos días, {name}. Las gachas de la taberna se movieron otra vez. Toma esto."
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "Los gallos de Rémol aún cantan, {name}. Nadie tiene corazón para decírselo."
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "Cambio de guardia, {name}. La Guardia de la Muerte solo se da la vuelta."
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "Sube al ascensor con calma, {name}. El último que se precipitó aún está bajando."
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "Entrañas lo tiene todo, {name}: banco, posada y opiniones en las cloacas."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "Aquí hasta las ratas se inclinan ante la Dama Oscura, {name}. Toma, antes de que te lo pida una."
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "Cuidado con el canal, {name}. Es verde por algo, y ese algo no es el musgo."
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "Entrañas está preciosa en esta época, {name}. Siempre es esta época."
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "Nos mudamos al sótano de Lordaeron, {name}, y nos quedamos la plata buena."
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "El Barrio Real, por ahí, {name}. Inclínate bien: las almas en pena puntúan."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "El cuidador de murciélagos jura que son mansos, {name}. Toma, antes de comprobarlo."
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "El Barrio de la Magia, por ahí, {name}. Los charcos que brillan no se beben."
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "El trono está justo arriba, {name}. Nadie se sienta en él. Malos recuerdos."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "La mayoría recibe a un Renegado con agua bendita, {name}. Qué cambio tan agradable."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "Pocos se paran por un Renegado, {name}. Tú lo hiciste, y me fijé. Gracias."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "Digan lo que digan, {name}, no todo lo que reparte un Renegado es una peste."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "Dicen que nadie encanta a un Renegado, {name}. Pedir con educación, sí."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "Toma esto en lugar de charla, {name}. La mía suele inquietar a la gente."
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "Dicen que los Renegados no tienen amigos, {name}. Estoy reclutando."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "Toma, {name}. Si alguien pregunta, los Renegados fueron un encanto."
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Sigue con vida, {name}. Probé la alternativa y no la recomiendo."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "La Madre Tierra vio tu bondad, {name}. Me dio un codazo. Bien fuerte."
L["Thank you, {name}. May the winds guide you."] = "Gracias, {name}. Que los vientos te guíen."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Gracias, {name}. Me conmueves, y mover a un tauren no es fácil."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "El corazón de un tauren queda muy arriba, {name}. Tú llegaste."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "Lo sentí de cuernos a pezuñas, {name}. Devuelto, de pezuñas a cuernos."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Regalo dado es semilla plantada, {name}. Aquí está la cosecha."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Esto merece un festín, {name}. El festín puede esperar; {buff}, no."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Gracias, {name}. Si te hace falta un muro para esconderte, estoy libre."
L["Thank you, {name}. My grandmother said kindness comes back on the wind."] = "Gracias, {name}. Mi abuela decía que la bondad vuelve con el viento."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "Devuelto más rápido que un jinete del viento, {name}, y con menos chillidos."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "Devuelto, {name}. Los jabaespines nunca aprendieron a devolver, y mira cómo están."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "Gracias, {name}. Todos mis ancestros asienten. Son muchísimas cabezas."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "En Mulgore, un regalo se devuelve antes de que rebrote la hierba, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "Gracias, {name}. Mi próxima cría de kodo llevará tu nombre. Son preciosas."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "Hay menos bondad que sombra en los Baldíos, {name}. Te devuelvo un poco."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "Lo tallaré en un tótem, {name}. Los tauren tallamos despacio: para primavera estará."
L["Bloodhoof Village will hear of this at supper, {name}. Thank you."] = "El Poblado Pezuña de Sangre sabrá de esto en la cena, {name}. Gracias."
L["Cairne taught us to honour every kindness, {name}, and so I do."] = "Cairne nos enseñó a honrar cada gesto amable, {name}, y así lo hago."
L["Thank you, {name}. Hamuul says the land repays those who tend it. So do I."] = "Gracias, {name}. Hamuul dice que la tierra recompensa a quien la cuida. Yo también."
L["In Thunder Bluff we'd beat a drum for that, {name}. Imagine it. Thank you."] = "En Cima del Trueno tocaríamos un tambor por esto, {name}. Imagínatelo. Gracias."
L["The Earth Mother gives without counting, {name}. You've been listening to her."] = "La Madre Tierra da sin contar, {name}. Se nota que la has escuchado."
L["Thank you, {name}. My heart's as full as a kodo after the spring grass."] = "Gracias, {name}. Tengo el corazón tan lleno como un kodo tras la hierba de primavera."
L["The elders on Elder Rise would approve, {name}. Slowly, after a long talk."] = "Los ancianos de Cima del Trueno lo aprobarían, {name}. Despacio, tras una larga charla."
L["If you pass through Mulgore, {name}, ask for me. Everyone knows the big one."] = "Si pasas por Mulgore, {name}, pregunta por mí. Cuesta no verme."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Claro, {name}. Alza la cabeza y ten paz. De la altura me encargo yo."
L["Ask and it is given, {name}. The herd shares what it has."] = "Pide y se te dará, {name}. La manada comparte lo que tiene."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Claro, {name}. Échate un paso atrás; esto lo hago con todo el cuerpo."
L["Gladly, {name}. Mind the tail."] = "Con gusto, {name}. Cuidado con la cola."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "La Madre Tierra da sin pedir nada, {name}, y sus hijos más grandes también."
L["Gladly, {name}. Tauren are slow to anger and quick to help."] = "Con gusto, {name}. Los tauren somos lentos para la ira y rápidos para ayudar."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "¿Negarme, {name}? Mis ancestros no me dejarían en paz jamás."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "Claro, {name}. Un tauren dice que sí como la llanura da hierba: sin esfuerzo."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "Claro, {name}. Un momento: mis manos son grandes y el hechizo, pequeño."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "Tras una temporada arreando kodos, {name}, una petición amable son vacaciones."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "La Madre Tierra dice 'comparte', {name}. Mi estómago, 'almuerzo'. Ella manda más."
L["Of course, {name}. Stand still as a totem; this won't take long."] = "Claro, {name}. No te muevas, como un tótem; no tardo nada."
L["Spirits of the plains, lend me your strength. Here, {name}."] = "Que los espíritus de las llanuras me presten su fuerza. Toma, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "Magatha pediría un favor a cambio, {name}. Baine diría que sí. Así que: sí."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "No te muevas, {name}. Practiqué con kodos, y son mucho menos educados."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "Claro, {name}. Un shu'halo nunca rechaza a un viajero. Ni una segunda ración."
L["Of course, {name}. The plains taught me patience; the kodo taught me to share."] = "Claro, {name}. Las llanuras me enseñaron paciencia; los kodos, a compartir."
L["Gladly, {name}. Ancestors, steady my hand. Not my hooves; they're fine."] = "Con gusto, {name}. Ancestros, dadme buen pulso. A las pezuñas no; están bien."
L["Always, {name}. Cairne never refuses a friend, and he's taller than me."] = "Siempre, {name}. Cairne nunca le dice que no a un amigo, y es más alto que yo."
L["Ask anything, {name}. A tauren has strength to spare and time to listen."] = "Pide lo que quieras, {name}. Un tauren tiene fuerza de sobra y tiempo para escuchar."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Camina con la Madre Tierra, {name}. Está en todas partes: no puedes perderte."
L["May An'she light your path, {name}."] = "Que An'she ilumine tu camino, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Parecías necesitar un apoyo, {name}. Yo soy uno enorme."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Toma, {name}. La Madre Tierra me regañaría si pasara de largo."
L["Tread lightly, {name}. Take it from someone who never has."] = "Pisa con suavidad, {name}. Te lo dice alguien que nunca lo hizo."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "El viento me dijo que pasarías por aquí, {name}. Es un chismoso terrible."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Toma, {name}. Te prestaría mi kodo, pero es menos generoso que yo."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Los shu'halo dicen: carga lo que puedas por los demás, {name}. Yo puedo mucho."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "Toma, {name}. Si te molestan los centauros, diles: 'Saludos de Cima del Trueno'."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "Toma, {name}. Los zancudos de las llanuras huyen de mí sin motivo. Tú no huyas."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "Para ti, {name}. Ven a Mulgore algún día. La hierba es suave y nadie tiene prisa."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "Toma, {name}. Mi abuela bendecía y alimentaba a los viajeros. Me quedé sin pan."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "Los espíritus me pidieron cuidarte, {name}. Dije que sí antes de que acabaran."
L["Here, {name}. Kodo share the watering hole; I can share this."] = "Toma, {name}. Los kodos comparten el abrevadero; yo puedo compartir esto."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "Toma, {name}. Los tauren dejamos el mundo un poco mejor, y un poco pisoteado."
L["The Earth Mother would offer you a nap, {name}. I offer this."] = "La Madre Tierra te ofrecería una siesta, {name}. Yo te ofrezco esto."
L["Druids call it a blessing, hunters luck, {name}. Tauren call it manners."] = "Los druidas lo llaman bendición; los cazadores, suerte, {name}. Los tauren, modales."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "Toma, {name}. Si una arpía te chilla, chíllale tú. Lo odian."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "Toma, {name}. Una bendición tauren: robusta, duradera y con un leve olor a salvia."
L["Here, {name}. The Venture Company would charge you for this. I won't."] = "Toma, {name}. Ventura y Cía. te cobraría por esto. Yo no."
L["From the high mesas of Thunder Bluff, {name}, where even the wind is friendly."] = "Desde las altas mesetas de Cima del Trueno, {name}, donde hasta el viento es amable."
L["The ancestors watch the roads, {name}. I just help them out a little."] = "Los ancestros vigilan los caminos, {name}. Yo solo les echo una mano."
L["A gift should be heavy with meaning and light to carry, {name}. This is both."] = "Un regalo debe pesar en significado y ser ligero de llevar, {name}. Este es ambas cosas."
L["The Earth Mother made the world wide so we'd meet people like you, {name}."] = "La Madre Tierra hizo el mundo tan grande para que conociéramos a gente como tú, {name}."
L["Hunt with respect and the land feeds you, {name}. That's my wisdom. Here."] = "Caza con respeto y la tierra te alimentará, {name}. Esa es mi sabiduría. Toma."
L["Here, {name}. Not every tauren would share. The Grimtotem certainly wouldn't."] = "Toma, {name}. No todos los tauren compartirían. Los Tótem Siniestro, desde luego, no."
L["The Earth Mother watches over us both, {name}."] = "La Madre Tierra vela por los dos, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Que alguien avise a las puertas, {name}. Ahora somos dos."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Llanura o montaña, {name}, un corazón shu'halo es grande."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Cuernos y yelmos, {name}. Solo otro tauren entiende ese dolor."
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "El pelaje mojado tarda una semana en secarse, {name}. Solo otro tauren me cree."
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "Entre tauren, {name}: los ascensores de Cima del Trueno los hizo alguien más bajito."
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "Nuestros ancestros nos observan, {name}. Démosles algo bonito que ver."
L["From Mulgore to Feralas, {name}, the herd always finds itself."] = "De Mulgore a Feralas, {name}, la manada siempre se reencuentra."
L["Get behind me, {name}. There's room back there for the whole party."] = "Ponte detrás de mí, {name}. Ahí cabe todo el grupo."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "La manada va unida, {name}. Ojo con mis pezuñas: la manada ya aprendió."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "¿Techos bajos más adelante, {name}? Lo sabré antes que nadie. Toma."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "Me cuesta perder la calma, {name}, pero guardo rencor por todo el grupo."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "¿Te hace falta un muro, {name}? Soy casi uno. Vamos."
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "Si uso Pisotón de guerra, {name}, todo el mundo sentado. Así nadie se cae."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "¿Comida? ¿Bendición? Bien, {name}. Un tauren nunca guía una manada hambrienta."
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "Los tauren no nadamos, {name}, vadeamos. Si cubre, te llevo a cuestas."
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "No te alejes, {name}. Mis ancestros nos acompañan. Hacen menos ruido que el grupo."
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "Si caigo, {name}, no intentes cargarme. Arrástrame. Con cariño."
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "Avanzamos como una estampida, {name}: en bloque, y perdón por las flores."
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "Nadie va solo en la retaguardia, {name}. Ahí estaré yo, haciendo sombra con cariño."
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "Dime cuándo cargar, {name}. A un tauren le cuesta arrancar, y más aún frenar."
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "Que nadie se desvíe, {name}. El último grupo que lo hizo en los Baldíos aún camina."
L["Stand close, {name}. A herd is strongest when nobody wanders off to graze."] = "No te alejes, {name}. La manada es más fuerte cuando nadie se aparta a pastar."
L["Watch the ground, {name}. Quilboar dig traps, and I find them all hoof first."] = "Mira dónde pisas, {name}. Los jabaespines cavan trampas, y yo las encuentro todas con la pezuña."
L["Into the fight with a calm heart, {name}. The rage can come later, if it must."] = "Al combate con el corazón en calma, {name}. La furia puede esperar, si hace falta."
L["May the Earth Mother keep this herd, {name}, every last stubborn calf of it."] = "Que la Madre Tierra guarde a esta manada, {name}, hasta el último ternero testarudo."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "An'she se alza, {name}, y nosotros también. Yo, más despacio."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "El sol es el ojo de An'she, {name}. Nos mira: hagamos como que trabajamos."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Buenos días, {name}. Los kodos en pie, la hierba mojada, y esto es para ti."
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "Buenos días, {name}. Ya saludé al sol, al viento y a dos zancudos. Ahora a ti."
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "Buenos días, {name}. Rocío en la hierba y en mi pelaje. No me seco hasta mediodía."
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "Qué temprano, {name}. ¿La bruma de Mulgore? Casi todo es aliento de kodo."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Mu'sha hace la guardia nocturna, {name}. Le diré que no te pierda de vista."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "Salió la luna, {name}. Mu'sha te ve y le parece bien. Se lo pregunté."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "Es tarde, {name}. Los kodos duermen y roncan como truenos. Toma."
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "Estrellas, {name}. Dicen que cada una es un ancestro. Aquella te está guiñando."
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "Tarde, {name}. De noche Mulgore calla tanto que se oye discutir a la hierba."
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "Silencio, {name}. A estas horas, hasta mis pezuñas van de puntillas."
L["Ya too kind, {name}! This one's from me."] = "¡Qué amable eres, {name}! Esto va de mi parte."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "¡Gracias, mon! Los espíritus te sonríen, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "Me diste buen mojo, {name}. Ahora te lo devuelvo, extra picante, mon."
L["Death's gonna be real disappointed, {name}. Thanks, mon."] = "La muerte se va a llevar un buen chasco, {name}. Gracias, mon."
L["Fine work, {name}. Almost as fine as me. Almost."] = "Buen trabajo, {name}. Casi tan fino como yo. Casi."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "A un trol le vuelve a crecer una mano, {name}. El honor no. Toma."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Hiciste sonreír a un trol, {name}, y tenemos muchos dientes."
L["Da loa keep a tally, {name}. You're on the good side of it."] = "Los loa llevan la cuenta, {name}. Tú estás en el lado bueno."
L["Beat me to it, {name}! Darkspear hate bein' second. Now we're even."] = "¡Me ganaste, {name}! Un Lanza Negra odia llegar segundo. Ya estamos en paz."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "Te debía una, {name}, y un trol solo les debe a los loa. Saldada."
L["I'll tell all of Sen'jin 'bout ya, {name}. Makes a change from crabs."] = "Le contaré a todo Sen'jin lo tuyo, {name}. Así dejan de hablar de cangrejos."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "Se me erizó aún más la cresta, {name}. No sabía que podía. Gracias, mon."
L["The spirits say give it back, {name}. They nag, but they're right."] = "Los espíritus dicen que lo devuelva, {name}. Son pesados, pero tienen razón."
L["Mojo for mojo, {name}: oldest trade in the jungle."] = "Mojo por mojo, {name}: el trueque más viejo de la selva."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "Vol'jin decía: la bondad se paga rápido, {name}. Decía mucho. Eso se me quedó."
L["That deserves a dance, {name}. Lucky ya: {buff} instead."] = "Eso merece un baile, {name}. Suerte la tuya: mejor {buff}."
L["Jungle rule, {name}: what ya give comes back, often with teeth. Not this one."] = "Ley de la selva, {name}: lo que das vuelve, a menudo con dientes. Este no."
L["A gift for a troll, {name}? We never forget a kindness."] = "¿Un regalo para un trol, {name}? Nunca olvidamos un favor."
L["Old Sen'jin said a gift is a promise, {name}. I keep mine. Here."] = "El viejo Sen'jin decía: un regalo es una promesa, {name}. Yo cumplo. Toma."
L["Back on the Echo Isles that earned a feast, {name}. Here's the short version."] = "En las Islas del Eco eso se ganaba un festín, {name}. Aquí tienes la versión corta."
L["That one's goin' in the stories by the fire, {name}. Ya get a good part."] = "Esto va para las historias junto al fuego, {name}. A ti te toca un buen papel."
L["Nice, {name}. Darkspear pay back quick. We got places to be. Mostly the beach."] = "Bien, {name}. Un Lanza Negra paga rápido. Tenemos sitios adonde ir. Casi siempre, la playa."
L["Stranglethorn gives nothin' for free, {name}. Nice to see somebody does."] = "Tuercespina no regala nada, {name}. Qué bueno ver que alguien sí."
L["Zalazane would've kept that for himself, {name}. Good thing ya ain't him."] = "Zalazane se lo habría quedado para él, {name}. Menos mal que no eres él."
L["Sure thing, {name}. Hold still; mojo hates a movin' target."] = "Seguro, {name}. No te muevas: el mojo odia lo que se mueve."
L["No trouble, {name}. Da loa like ya."] = "Sin problema, {name}. Los loa te quieren."
L["Stay away from da voodoo, {name}. Except this one. This one's fine."] = "Aléjate del vudú, {name}. Menos de este. Este está bien."
L["Close ya eyes, {name}. Mojo gets shy when people watch."] = "Cierra los ojos, {name}. El mojo se pone tímido si lo miran."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "No tienes que pedirlo dos veces, {name}. Casi ni una."
L["Sure, {name}. A troll is mostly swagger. The rest is this."] = "Claro, {name}. Un trol es casi todo actitud. Lo demás es esto."
L["Ya asked polite, {name}. Polite gets the good stuff."] = "Lo pediste con modales, {name}. Los modales se llevan lo bueno."
L["Ya came to the right troll, {name}. The wrong one's over there, fishin'."] = "Diste con el trol correcto, {name}. El equivocado está allá, pescando."
L["Yes, {name}. The loa owe me a favour, and I'm spendin' it on you."] = "Sí, {name}. Los loa me deben un favor, y lo gasto en ti."
L["Got a pouch full of mojo, {name}. Don't touch the other pouch."] = "Tengo una bolsa llena de mojo, {name}. La otra bolsa no la toques."
L["Anything for ya, {name}. Not my hair, though. Hair is sacred."] = "Lo que sea para ti, {name}. El pelo no, eso sí. El pelo es sagrado."
L["Troll magic, {name}, served hot. Blow on it first."] = "Magia trol, {name}, servida caliente. Sóplale primero."
L["Right away, {name}. A Zandalari priest would make a week of this."] = "Ya mismo, {name}. Un sacerdote zandalari tardaría una semana."
L["Easy one, {name}. Hard one's gettin' a raptor to sit still."] = "Esto es fácil, {name}. Lo difícil es que un raptor se esté quieto."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "Regla trol, {name}: ni hacer rogar a un amigo ni esperar a un raptor. Toma."
L["Don't wiggle, {name}. Last one who did got the spell and a new haircut."] = "No te menees, {name}. El último que lo hizo se llevó hechizo y corte de pelo."
L["No problem, {name}. Darkspear always got time for a friend. And a nap."] = "Sin problema, {name}. Un Lanza Negra siempre tiene tiempo para un amigo. Y para la siesta."
L["Sure, {name}. Hold still, like a fisherman at Sen'jin waitin' on a bite."] = "Claro, {name}. No te muevas, como un pescador de Sen'jin esperando que piquen."
L["Yes, {name}. Vol'jin says never turn away a friend, and he's usually right."] = "Sí, {name}. Vol'jin dice que nunca se le da la espalda a un amigo, y casi siempre acierta."
L["Sure thing, {name}. I'll hum a little. Witch doctors say it helps."] = "Claro que sí, {name}. Tarareo un poquito. Los médicos brujos dicen que ayuda."
L["Da loa watch over ya, {name}. They're real nosy that way."] = "Los loa te cuidan, {name}. Son muy curiosos."
L["Stay sharp, {name}. Take this with ya."] = "Ojo avizor, {name}. Llévate esto."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Pareces alguien que aprecia la calidad, {name}. Toma: calidad."
L["Here, {name}. Walk like ya own the jungle. I do."] = "Toma, {name}. Camina como si la selva fuera tuya. Yo lo hago."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "Todo el mundo necesita mojo, {name}. Yo hago tanto que tengo que regalarlo."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "Un detallito para ti, {name}. No preguntes de dónde lo sacaron los loa."
L["Go on, {name}. Whatever tries to eat ya now gets indigestion."] = "Anda, {name}. Lo que intente comerte ahora se va a indigestar."
L["Ya look dangerous now, {name}. Almost as dangerous as a troll."] = "Ahora impones, {name}. Casi tanto como un trol."
L["No charge, {name}. Ya don't owe the loa a thing. Probably."] = "Gratis, {name}. No les debes nada a los loa. Creo."
L["Raptors got bigger teeth than me, {name}. Now they got a problem."] = "Los raptores tienen más dientes que yo, {name}. Ahora el problema es suyo."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "Hospitalidad trol, {name}: te llevas mojo, te llevas sonrisa, mi pescado no."
L["Walk with mojo, {name}. Everybody else is just walkin'."] = "Camina con mojo, {name}. Los demás solo caminan."
L["Free mojo, {name}! Quick, before the witch doctor finds out."] = "¡Mojo gratis, {name}! Rápido, antes de que se entere el médico brujo."
L["The loa said give this to the next good soul, {name}. That's you."] = "Los loa dijeron: para la próxima alma buena, {name}. Y esa eres tú."
L["Here, {name}. Hakkar never shared. Look what happened to him."] = "Toma, {name}. Hakkar nunca compartía. Mira cómo acabó."
L["Jungle's got two kinds of folk, {name}: ready, and lunch. You're ready."] = "La selva tiene dos tipos de gente, {name}: listos y almuerzo. Tú no eres almuerzo."
L["Easy, {name}. This one tickles. Don't laugh; it gets offended."] = "Tranqui, {name}. Este hace cosquillas. No te rías; se ofende."
L["Take this, {name}. Darkspear never send a friend off empty-handed."] = "Toma, {name}. Un Lanza Negra nunca despide a un amigo con las manos vacías."
L["Darkspear know what it is to need a friend far from home, {name}. Here."] = "Los Lanza Negra sabemos lo que es necesitar un amigo lejos de casa, {name}. Toma."
L["Watch for the Bloodscalps, {name}. Same tusks as me, worse manners. Take this."] = "Ojo con los Cabellera Sangrienta, {name}. Mismos colmillos que yo, peores modales. Toma."
L["Walk easy, {name}. Life's long if ya don't rush it, and short if ya do."] = "Camina tranqui, {name}. La vida es larga si no la apuras, y corta si la apuras."
L["My granny was a witch doctor, {name}. Share, she said, and look scary doin' it."] = "Mi abuela era médica bruja, {name}. Comparte, decía, y da miedo mientras lo haces."
L["From Sen'jin Village, {name}. Smells a bit like fish. Works fine, though."] = "Del Poblado Sen'jin, {name}. Huele un poco a pescado. Pero funciona bien."
L["Stay loose, {name}. Tense folk trip on roots. Take this, and relax."] = "Relaja el cuerpo, {name}. Quien va tenso tropieza con las raíces. Toma, y tranqui."
L["The spirits whisper ya name, {name}. Well, somebody's. Close enough."] = "Los espíritus susurran tu nombre, {name}. Bueno, el de alguien. Casi."
L["We look after our own, {name}. Always, mon."] = "Cuidamos de los nuestros, {name}. Siempre, mon."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "El resto de Azeroth anda derecho, {name}. Nosotros tenemos más estilo."
L["Ya tusks look sharp, {name}. Mine too, obviously."] = "Qué colmillos tan afilados, {name}. Los míos también, claro."
L["Every troll's family, {name}. Even the ones who still owe me gold."] = "Todo trol es familia, {name}. Hasta los que aún me deben oro."
L["One day we take the Echo Isles back from Zalazane, {name}. Together."] = "Un día le quitaremos las Islas del Eco a Zalazane, {name}. Juntos."
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "Dos trols, {name}. La altura media acaba de subir. Y la calma también."
L["The loa got their eyes on both of us now, {name}. Behave."] = "Los loa nos tienen echado el ojo, {name}. Pórtate bien."
L["Troll to troll, {name}: only we know how hard it is to buy boots."] = "De trol a trol, {name}: solo nosotros sabemos lo difícil que es comprar botas."
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "Nuestros ancestros tenían imperios, {name}. Nosotros nos tenemos unos a otros. Buen trato, digo yo."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "No te alejes, {name}. Un trol se regenera; los demás, cuidadito."
L["Crew's got style, {name}. Now it's got mojo too."] = "Qué estilo tiene el grupo, {name}. Ahora también tiene mojo."
L["We go in together, {name}, we come out together. That's the plan, mon."] = "Entramos juntos, {name}, y salimos juntos. Ese es el plan, mon."
L["Nobody fallin' today, {name}. Death can wait for the next group."] = "Hoy no cae nadie, {name}. La muerte que espere al próximo grupo."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Agacha la cabeza, {name}. Yo la llevo alta. Alguien tiene que lucirse."
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "Formación raptor, {name}: a toda prisa, con escándalo y sin mirar atrás."
L["If a big snake shows up, {name}, don't run. Stand behind me."] = "Si sale una serpiente grande, {name}, no corras. Ponte detrás de mí."
L["Need more mojo, {name}? Just shout. Not too loud; the loa are nappin'."] = "¿Más mojo, {name}? Grita. Pero bajito: los loa duermen la siesta."
L["They'll tell this one at Sen'jin, {name}. Let's give it a happy endin'."] = "Esto lo van a contar en Sen'jin, {name}. Démosle un final feliz."
L["My tusks are sharp, {name}, but they can't be everywhere. Stay near."] = "Mis colmillos cortan, {name}, pero no están en todas partes. No te alejes."
L["Nobody panic, {name}. Panic is bad mojo. Swagger is good mojo."] = "Que nadie se asuste, {name}. El pánico es mal mojo. La actitud es buen mojo."
L["See an idol with glowin' eyes, {name}? Don't touch it. Trust me."] = "¿Ves un ídolo con ojos brillantes, {name}? No lo toques. Hazme caso."
L["Everybody stay loose, {name}. Fights go better when ya smilin'. Mostly."] = "Todo el mundo tranqui, {name}. Las peleas salen mejor sonriendo. Casi siempre."
L["Darkspear fight together or not at all, {name}. Together makes more stories."] = "Los Lanza Negra peleamos juntos o no peleamos, {name}. Juntos salen más historias."
L["Ready, {name}? Any Gurubashi, let me talk first. Then you hit 'em."] = "¿Vamos, {name}? Si sale un Gurubashi, hablo yo primero. Luego le pegas tú."
L["Watch for traps, {name}. Trolls built half the old temples. We love surprises."] = "Ojo con las trampas, {name}. Muchos templos viejos son de trols. Nos encantan las sorpresas."
L["The loa are watchin' this group, {name}. Let's give 'em a good show."] = "Los loa están mirando al grupo, {name}. Démosles un buen espectáculo."
L["I got ya back, {name}. Trolls got long arms for a reason."] = "Te cubro, {name}. Por algo los trols tenemos los brazos tan largos."
L["Night's the best time for mojo, {name}. Nobody sees where it's from."] = "De noche el mojo funciona mejor, {name}. Nadie ve de dónde viene."
L["The jungle wakes at night, {name}. So do I. This one's fresh."] = "La selva despierta de noche, {name}. Yo también. Este está recién hecho."
L["High moon, {name}, restless spirits. This keeps 'em off ya."] = "Luna alta, {name}, espíritus inquietos. Esto te los quita de encima."
L["Hir'eek the bat loa keeps late hours too, {name}. This is from us both."] = "Hir'eek, el loa murciélago, también trasnocha, {name}. Esto es de parte de los dos."
L["This late, {name}, only trolls and trouble are up. I'm the nice one."] = "A estas horas, {name}, solo hay trols y problemas. Yo soy la parte amable."
L["Stars out, {name}. Each one a loa, Granny said. That's a lot of watchers."] = "Salieron las estrellas, {name}. Cada una es un loa, decía la abuela. Mucho mirón."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Tanta cortesía te honra, {name}. Casi tanto como a mí."
L["How gracious, {name}. Allow me to return the favour."] = "Qué gentileza, {name}. Permíteme devolverte el favor."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Gracias, {name}. No me sentía tan radiante desde... bueno, esta mañana."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Qué amable, {name}. Los sin'dorei jamás rechazamos magia gratis. Es sabido."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Exquisito, {name}. Sé de lo que hablo: solo acepto lo exquisito."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Precioso, {name}. Hoy voy a estar insufrible con esto. Más de lo normal."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Gracias, {name}. Hasta combina con mis ribetes dorados. Tienes buen ojo."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Te lo devuelvo igual, {name}. Bueno, más bonito. No lo puedo evitar."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "Gracias, {name}. Te enseñaré Lunargenta entera, salvo la calle de los asesinos."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "Devuelto, {name}. A diferencia de Kael'thas, yo sí devuelvo las cosas."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "Gracias, {name}. Lo sentí hasta la punta de las orejas, y eso es mucho recorrido."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "Gracias, {name}. Fue tan amable que casi me vuelven a cambiar de color los ojos."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "¿Un regalo sin pedirlo? Los Errantes lo llamarían emboscada. Una preciosa, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "Mejor que un cristal de maná, {name}, y eso que ya los dejé. Casi. Gracias."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "Qué rapidez, {name}. Los elfos vivimos siglos y aun así te me adelantaste."
L["Charming, {name}. The sun favours the generous, and so do I."] = "Encantador, {name}. El sol favorece a los generosos, y yo también."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "Gracias, {name}. Te mencionaré en la corte. Bueno, en un pícnic muy exclusivo."
L["Thank you, {name}. Courtesy is rare outside Silvermoon. Yours shines."] = "Gracias, {name}. La cortesía escasea fuera de Lunargenta. La tuya brilla."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "¡Amabilidad sin pedirla, {name}! Que alguien avise a Rommath; querrá estudiarla."
L["Naturally, {name}. Only the finest for you."] = "Naturalmente, {name}. Solo lo mejor para ti."
L["For you, {name}? Of course. The sun gives freely."] = "¿Para ti, {name}? Por supuesto. El sol da sin reservas."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Paciencia, {name}. El esplendor no se apresura: se admira."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Por supuesto, {name}. {buff}, con una postura impecable."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Lo pediste con elegancia, {name}. En Lunargenta, eso lo es todo."
L["One moment, {name}. I never cast anything without checking my hair."] = "Un momento, {name}. Nunca lanzo nada sin mirarme el pelo."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Al instante, {name}. Hacer esperar a alguien está tan pasado de moda..."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "Por supuesto, {name}. Retrocede un paso: mis mangas están encantadas y son muy anchas."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "Un magister te lo cobraría, {name}. Un Caballero de Sangre, un sermón. Yo solo brillo."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "Al instante, {name}. Si sale bien, cuéntaselo a todos. Si no, culpa de la túnica."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "Al instante, {name}. El dracohalcón puede esperar; ya me espera cada vez que me visto."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "Con gusto, {name}. Una vez le arrancamos la Luz a un naaru. Pedir es mucho más bonito."
L["Three centuries of casting, {name}, and you're the first to say please."] = "Tres siglos lanzando, {name}, y eres la primera persona que dice por favor."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "Con gusto, {name}. En Lunargenta las escobas barren solas; tengo las manos libres."
L["Of course, {name}. I keep my other spells for the rude."] = "Por supuesto, {name}. Mis otros hechizos los reservo para los groseros."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. Que el sol te guíe y realce tu mejor perfil."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Lucha con elegancia."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Toma, {name}. Pase lo que pase ahí fuera, no es más que un contratiempo."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Todo el mundo merece brillar, {name}. Un poquito menos que yo, claro."
L["The sun is with you, {name}. I simply held the door for it."] = "El sol está contigo, {name}. Yo solo le abrí la puerta."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Anda, {name}, tómalo. La Fuente del Sol volvió; podemos ser generosos."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Para ti, {name}: {buff}, con aroma de Lunargenta."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Toma, {name}. Hecho a mano en Lunargenta: intenta no rayarlo."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "Un poco de Fuente del Sol para ti, {name}. Pasó por mucho; trátala con cariño."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "Hay que prevenir, {name}. No lo hicimos y ahora tenemos una cicatriz por camino."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "Toma, {name}. Solo doy a quien lo merece. Qué oportuno que pasaras por aquí."
L["Take this, {name}. It's been in my family for moments."] = "Toma, {name}. Reliquia familiar: lleva en mi familia unos segundos."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "Los sin'dorei lo perdimos casi todo, {name}. Nunca la generosidad. Ni los pómulos."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "Toma, {name}. Si te sigue un vermis de maná, es pura envidia."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "Siete mil años para perfeccionar la generosidad, {name}. Empezamos la semana pasada."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "Toma, {name}. Vino por el orbe de Entrañas, así que está un poco mareado."
L["For you, {name}. It matches everything. I checked, obviously."] = "Para ti, {name}. Combina con todo. Lo comprobé, obviamente."
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "Si te para un necrófago, {name}, dile que Lunargenta sigue en pie. Lo odian."
L["The Sunwell shines for us both, {name}."] = "La Fuente del Sol brilla para ambos, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Dos sin'dorei juntos, {name}. El día acaba de ganar el doble de elegancia."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "¿Tú también, {name}? Dos sin'dorei, un espejo. Habrá que turnarse."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Como el fénix, {name}: siempre renacemos, y con estilo."
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "Entre sin'dorei, {name}: sí, la Horda es ruidosa. Sí, ya nos acostumbramos."
L["Sin'dorei to sin'dorei, {name}: we never speak of the green eyes. Agreed?"] = "De sin'dorei a sin'dorei, {name}: de los ojos verdes no se habla. ¿De acuerdo?"
L["Magister or Farstrider, {name}, the sun rises for us all."] = "Magister o Errante, {name}, el sol sale para todos."
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "Tú y yo recordamos Quel'Thalas antes de la Plaga, {name}. Ganémonos el después."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "No te quedes atrás, {name}. Tenemos fama de hacer grandes entradas."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Ponte donde haya buena luz, {name}. Si hay que luchar, que sea con esplendor."
L["A party at last, {name}. I did dress for one."] = "Por fin un grupo, {name}. Y yo que me vestí de fiesta."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "El sol brilla para todos, {name}. Sobre todo para mí, pero comparte."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Uno para ti, {name}, y otro para la imagen del grupo, de la que me encargo yo."
L["If I fall, {name}, arrange me attractively. The rest I leave to the priest."] = "Si caigo, {name}, colócame con gracia. Lo demás se lo dejo al sacerdote."
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "Que nadie toque las reliquias encantadas, {name}. Bueno, yo sí. Tengo formación."
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "Toda expedición necesita un forestal, {name}. Yo no lo soy, pero tengo las botas."
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "Luchamos juntos, {name}, y luego lo contamos con estilo. De contarlo me encargo yo."
L["Whoever mends us is to be thanked, {name}. Me, admired. Carry on."] = "A quien nos cura, se le agradece, {name}. A mí, se me admira. Adelante."
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "Si esto sale mal, {name}, la culpa es de la Plaga. Es tradición."
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "Las pociones de maná son para emergencias, {name}. Hoy llevo once emergencias."
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "Ya salimos una vez de las cenizas, {name}. Saldremos de lo que venga."
L["The sun has risen, {name}, and so have I. We coordinate."] = "Salió el sol, {name}, y yo con él. Nos coordinamos."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "El amanecer en Quel'Thalas es más bello, {name}, pero este sirve. Apenas."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "Luz matinal, {name}. La hora más favorecedora. Para ti y para mí, claro."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "En Canción Eterna se desayuna fruta, té y arcano, {name}. Pasa directo al arcano."
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "Amanece, {name}. Rojo y oro por todo el cielo. Alguien nos está copiando."
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "Buenos días, {name}. Solo los guardianes arcanos de Lunargenta madrugan tanto. Y yo."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Tomo nota de tu generosidad, {name}. Por triplicado. Suramar recuerda a sus amigos."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Muy gentil por tu parte, {name}. Permíteme corresponderte."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Gracias, {name}. Diez mil años bajo una cúpula; aún lo estoy practicando."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "¿Un regalo sin pedir un favor a cambio? La corte se desmayaría. Gracias, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Devuelto, {name}. Llevamos cuenta detallada de la bondad. Y de las ofensas."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Le hablaré de ti a la primera arcanista Thalyssra, {name}. Y bien, incluso."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Muy amable, {name}. En Suramar daríamos un banquete. Dalo por celebrado."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Te escribiría una carta de gratitud, {name}, pero esto es más rápido."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "En la corte de Elisande, cada regalo escondía un puñal, {name}. El tuyo no. Gracias."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "Gracias, {name}. Mi sable de maná te aprueba, y no aprueba a nadie."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "Exquisito, {name}. Antes habría dicho 'aceptable'. El mundo me volvió humilde."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "Alimentaste una mente que una vez pasó hambre, {name}. Nunca olvidamos a quien lo hace."
L["Centuries of court etiquette, {name}, and 'thank you' still says it best."] = "Siglos de etiqueta cortesana, {name}, y un 'gracias' sigue diciéndolo mejor."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "Gracias, {name}. Tienes invitación para la próxima mascarada. Máscara obligatoria."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "Gracias, {name}. Oculeth abriría un portal para decirlo. Yo me limito a lanzar."
L["Of course, {name}. A little arcane polish, just for you."] = "Por supuesto, {name}. Un poco de lustre arcano, solo para ti."
L["A reasonable request, {name}. Granted."] = "Petición razonable, {name}. Concedida."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Por supuesto, {name}. La versión corta; la larga dura un ciclo lunar."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Una petición, qué refrescante. La corte solo exigía. Toma, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Hecho, {name}, y gratis. Elisande te habría cobrado un favor."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Ya está, {name}. No te inclines. Aunque un poquito sería un detalle."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Claro, {name}. Lo pulo desde antes de que existieran las murallas."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "Concedido, {name}. Te pediría un favor a cambio, pero intento ser menos Suramar."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "Claro, {name}. Perdona la floritura. No sabemos lanzar sin adornos; lo intentamos."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "Al instante, {name}. Elisande detuvo el tiempo. Yo solo necesito un segundo."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "Claro, {name}. Aquí las líneas ley son poco profundas, pero me las arreglo."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "Muy bien, {name}. Ponte a la luz de la luna. O junto a esa lámpara. La lámpara sirve."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "Naturalmente, {name}. Suramar tenía un hechizo para todo. Recuerdo varios."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Toma, {name}. Los dones arcanos se desperdician en los ociosos."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Una chispa del saber arcano de Suramar, {name}. Úsala bien."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "Ya pasé una vez sin magia, {name}. No lo recomiendo. Toma."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "El mundo fuera de la cúpula es enorme, {name}. Y tan desencantado. Toma."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Lo tradicional es el vino arcano, {name}, pero {buff} viaja mejor."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Acéptalo, {name}. Es grosero rechazar la hospitalidad de Suramar. Muy grosero."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Toma, {name}. Me dicen que así saludan los de fuera. Encantadora costumbre."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Toma, {name}. Magia acaparada, magia echada a perder: Suramar lo aprendió."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "Antes te habría exigido una reverencia por esto, {name}. Todos maduramos."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "El Kirin Tor también lo hace, {name}, benditos sean. Y bien, para ser novatos."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "Un regalo de la cúpula, {name}. Se conservó fresco muchísimo, muchísimo tiempo."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "Disfrútalo, {name}. Antes lo lanzaba sobre la nobleza. Tú eres una mejora."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "Hice la maleta para el mundo exterior como para una gala, {name}. Cuatro capas. Toma."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "Toma, {name}. Obra de Suramar: sobrediseñada, recargada e impecable."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "Toma, {name}. En Suramar esto venía con cuarteto de cuerda. Tararea algo, anda."
L["Suramar's children shine together again, {name}."] = "Los hijos de Suramar vuelven a brillar juntos, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "¡Shal'dorei, {name}! ¿Trajiste vino arcano? El vino de fuera es solo... uva."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "Sangre de Suramar, {name}. Que el resto del mundo no te impresione mucho."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Sobrevivimos a la Legión y a la abstinencia, {name}. Lo demás son minucias."
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "Nuestros sastres también salieron de Suramar, {name}. Gracias a las estrellas."
L["We both remember going hungry, {name}. Never again, for either of us."] = "Tú y yo sabemos lo que es pasar hambre, {name}. Nunca más, ni para ti ni para mí."
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "Fuera de la cúpula, {name}. ¿A ti también te sigue pareciendo tan grande el cielo?"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "Dos shal'dorei en el mismo sitio, {name}. Los lugareños creerán que hay gala."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "¡Una expedición, {name}! En Suramar harían falta seis permisos y una mascarada."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "La cúpula nos protegía, {name}. Ahora nos cuidamos entre todos. Con gusto."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "Arcano para todos, {name}. La corte lo llamaría derroche. Yo lo llamo compañía."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Sigue mis pasos, {name}. Llevo diez mil años marcando el paso."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "En grupo, uno comparte su magia, {name}. Qué novedad. Me gusta bastante."
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "Una salida es como una mascarada, {name}: sonríe, no te detengas y vigila los puñales."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "Quédate a la luz de mis hechizos, {name}. Es la más favorecedora del grupo."
L["After Elisande's court, {name}, this outing is a holiday. Nobody plots."] = "Tras la corte de Elisande, {name}, esta salida son vacaciones. Nadie conspira."
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "¿Te perdiste? Sigue a quien brilla, {name}. Soy yo. Siempre soy yo."
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "Si empiezo a disertar sobre líneas ley, {name}, interrúmpeme. Con educación."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "Vi a mi pueblo consumirse, {name}. No veré apagarse a mis amigos. Aquí no cae nadie."
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "Avísame si me pongo grandilocuente, {name}. Pierdo la cuenta. Son los milenios."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Por fin de noche, {name}. Unos miles de faroles más y casi es Suramar."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Bajo la cúpula siempre era de noche, {name}. Me siento como en casa."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "Hay estrellas, {name}. Las de Suramar eran mejores. Estas servirán."
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "Nocheterna, {name}, y por fin llega la noche. Al fin mi ropa va con la hora."
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "A estas horas, {name}, Suramar apenas se estaba vistiendo para cenar."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "Luz del día, {name}. Diez mil años bajo una cúpula, y aún me sobresalta."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Qué temprano, {name}. La corte no madrugaba nunca. Me estoy reformando."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Buenos días, {name}. El sol de aquí es tan... poco encantador. Mejor esto."
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "Buenos días, {name}. Protegimos Suramar contra toda amenaza, menos el sol."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "Alba, {name}: cuando el chisme de la corte se acostaba. Ahí va el mío: te veo bien."
L["A favour for a favour, {name}! Pleasure doing business."] = "¡Favor por favor, {name}! Un placer hacer negocios."
L["Thanks, {name}! Consider your account settled in full."] = "¡Gracias, {name}! Tu cuenta queda saldada por completo."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Ay, {name}. Te facturaría, pero estoy sentimental. Ya se me pasará."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "¡Gracias, {name}! Busqué la letra pequeña. No había. ¡Qué raro!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Devuelto con intereses, {name}. Sin los intereses. No te acostumbres."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "¡Mil gracias, {name}! Acabas de ascender a cliente preferente."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Le pondría tu nombre a un cohete, {name}, pero mis cohetes duran poco. ¡Gracias!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "Yo habría cobrado cincuenta de oro, {name}. Quedamos en paz."
L["Thanks, {name}! Quick hands. You'd do well in Booty Bay."] = "¡Gracias, {name}! Qué manos tan rápidas. Te iría bien en Bahía del Botín."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "¡Un trato donde ganan las dos partes, {name}! Había oído hablar de eso. Nunca vi uno."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "Primer regalo gratis desde que explotó Kezan, {name}. Lo devuelvo antes de tasarlo."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "¡Gracias, {name}! Lo tasé: no tiene precio. Toma otro de la misma tasación."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "Bondad que entra, bondad que sale, {name}. Ni la fiebre de la kajamita dio tanto."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "¿Trato justo, {name}? Mi asesor financiero se desmayó. Le pasa mucho con esos."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "¡Gracias, {name}! Te daría la mano, pero luego me cuento los dedos. Manía mía, no tuya."
L["Thanks, {name}! Gadgetzan could use a few more like you."] = "¡Gracias, {name}! A Gadgetzan le vendrían bien unos cuantos como tú."
L["You got it, {name}! Time is money, friend!"] = "¡Marchando, {name}! ¡El tiempo es oro!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "¡Trato hecho, {name}! Te lo cobro luego. ¡Es broma!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "¡Ahora mismo, {name}! Satisfacción garantizada o te devolvemos {buff}."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "¡{buff}, {name}! Propina opcional. Recomendada. Opcional."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "¿Rápido, barato o bueno, {name}? Hoy, las tres cosas. No lo vayas contando."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "¡Claro, {name}! Esta vez sin explosiones, lo prometo. Casi lo prometo."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "¿Para ti, {name}? Gratis. Si lo pones por escrito, lo negaré."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "¡Claro, {name}! Presupuesto: cero de oro. El más bajo de mi vida. Duele un poco."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "¡Marchando, {name}! Garantía total incluida. Válida hasta que se acabe el efecto."
L["Sure, {name}! I'd tinker with it, but you look in a hurry."] = "¡Claro, {name}! Lo retocaría un poco, pero se te ve con prisa."
L["Easy, {name}. Steamwheedle rule: keep customers alive. They pay longer."] = "Fácil, {name}. Norma Bonvapor: los clientes vivos pagan durante más tiempo."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "Gadgetzan tiene el negocio del agua, {name}. Yo tengo esto. Mejores márgenes."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "Estándar de Kezan, {name}: rápido, ruidoso y hecho antes de que leas la letra pequeña."
L["On it, {name}! Goblins never keep a customer waiting. Unless it pays."] = "¡Marchando, {name}! Un goblin nunca hace esperar a un cliente. Salvo si sale a cuenta."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "Invita la casa, {name}. Que no se entere el Príncipe Mercante."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "De primera y sin comisiones, {name}. ¡Solo hoy!"
L["Free sample, {name}! If you like it, you know where to find me."] = "¡Muestra gratis, {name}! Si te gusta, ya sabes dónde encontrarme."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Toma, {name}. Si hoy explota algo cerca de ti, no tiene nada que ver."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "La buena fama cotiza, {name}. Toma {buff}: va al balance."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Toma, {name}. ¡La seguridad es lo primero! O lo tercero. Está en la lista."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "¡Lanzado en tiempo récord, {name}! El récord es mío. Lo acabo de batir."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Kaja'Cola te da ideas, {name}. Esto hace el resto. ¡Tómalo!"
L["Here, {name}. Go make your fortune. I'll want a cut."] = "Toma, {name}. Ve a hacer fortuna. Querré mi parte."
L["Zeppelin's late again, {name}, so I've time to be generous."] = "El zepelín se retrasa otra vez, {name}. Tiempo para un gesto generoso."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "Toma, {name}. Patente en trámite. Pruébalo y cuéntaselo a tus amigos ricos."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "Considéralo una inversión, {name}. En ti. Espero rendimientos heroicos."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "¡Tómalo, {name}! Mi último cargamento se hundió frente a Kezan: liquidación total."
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "Ventura y Cía. cobra por esto, {name}. Yo soy la competencia. Toma."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "Todo goblin tiene su punto débil, {name}. El mío es pequeño y vigilado. Lo encontraste."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "Toma, {name}. Es lo único mío que no está hipotecado."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "Algún día tendrás una fortuna, {name}. Se nota. Acuérdate de quién te dio esto."
L["Anything for a fellow entrepreneur, {name}!"] = "¡Entre emprendedores hay que ayudarse, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "Lo mejorcito de Kezan, reunido otra vez, {name}. Ojo con tu bolsa."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "¿Colega goblin, {name}? Entonces sabes que este descuento es rarísimo."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "Entre goblins nos cuidamos, {name}. Sale más barato que pagar guardias."
L["Kezan's gone, {name}, but the greed made it out. Look at us."] = "Kezan ya no está, {name}, pero la codicia se salvó. Míranos."
L["Between goblins, {name}, this never happened. I have a reputation."] = "Entre goblins, {name}, esto nunca pasó. Tengo una reputación que mantener."
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "Pantoque o Bonvapor, {name}, siempre salimos a flote. Como el aceite."
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "¿Te acuerdas del volcán, {name}? Vendimos entradas. Qué tiempos aquellos."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "¡Tarifa de grupo, {name}! Todos a mitad de precio. De gratis."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "Nadie muere bajo mi contrato, {name}. El papeleo es una pesadilla."
L["We split the take even, {name}. I'll do the maths. Trust me."] = "A partes iguales, {name}. Las cuentas las hago yo. Confía en mí."
L["There, {name}. Everyone's stronger, and everyone owes me. Invoices later."] = "Listo, {name}. Todos más fuertes, y todos en deuda conmigo. Las facturas, luego."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "No te separes, {name}. Los mercenarios cuestan oro; los amigos, solo esto."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "Todos cubiertos, {name}. Asegurados no, ojo. Cubiertos. Otro precio."
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "Leí el informe de riesgos de esta salida, {name}. Lectura corta. Solo dice 'no'."
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "Que nadie toque la gran palanca roja, {name}. Siempre hay una gran palanca roja."
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "Si esto se tuerce, {name}, tengo un cohete. De una plaza. Estoy en ello."
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "Ahora somos una empresa, {name}. La tesorería la llevo yo. Votación unánime: la mía."
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "No te mueras, {name}. Nadie sabe aún cómo vender resurrecciones. Estoy en ello."
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "No te alejes, {name}. Ya vendí la historia de este viaje. Que valga la pena."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "¡A quien madruga, el oro le ayuda, {name}! Invito. Ni una palabra a los dormilones."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "¡Buenos días, {name}! Los mercados abren en una hora. Hasta entonces, invito yo."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "¿Madrugas, {name}? Bien. El tiempo es oro, y a primera hora sale más barato."
L["Dawn, {name}. Rich goblins sleep in. I'm not rich yet."] = "Amanece, {name}. Los goblins ricos duermen hasta tarde. Yo todavía no."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "Día nuevo, libro nuevo, {name}. Eres la primera entrada. En la columna buena."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "¡Gracias, {name}! La caravana siempre devuelve un favor. Suele ser en cordel."
L["How kind, {name}! You're on the caravan's good list now."] = "¡Qué detalle, {name}! Ya estás en la lista buena de la caravana."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "¡Uy, esto me lo quedo, {name}! Me lo quedo todo. Toma, uno para ti."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "¡Gracias, {name}! Aquí va el tuyo. Bueno, otro. Casi sin usar."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "Mira mis orejas, {name}: tiesas del todo. Eso es alegría pura."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "En la hoguera de esta noche, {name}, la historia tendrá un gusano de arena. ¡Gracias!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "Te lo envolvería, {name}, pero todo mi papel de regalo es un mapa ajeno."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "Las alpacas lo vieron, {name}. Contarán a todos lo buena gente que eres. ¡Gracias!"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "¡Gracias, {name}! Te daría mi mejor botón, pero esto es mejor. Un poquito."
L["Ooh, a present, {name}! I'll trade you one of mine."] = "¡Uy, un regalo, {name}! Te cambio uno de los míos."
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "¡Gracias, {name}! Esto va a la bolsita buena. No a la de piedras. A la buena."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "En Vol'dun esto habría costado un odre entero, {name}. ¡Gracias!"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "¡Gracias, {name}! Tu nombre va en el carro. Entre la alpaca y la abolladura."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "La bondad es lo único que el desierto nunca enterró, {name}. Gracias."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "Rakera dice: devuelve rápido, {name}, antes de olvidar en qué bolsillo está. ¡Toma!"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "Nadie me dio nunca nada que no hubiera desenterrado yo antes, {name}. ¡Gracias!"
L["Of course, {name}! Shake the sand out and hold still."] = "¡Claro, {name}! Sacúdete la arena y no te muevas."
L["Coming right up, {name}! Caravan service, no waiting."] = "¡Ahora mismo, {name}! Servicio de caravana, sin esperas."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "¡Claro, {name}! Déjame buscar... cuerda, piedras, una piedra bonita... ¡aquí está!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "¡Espera, {name}! La cola me estorba, un momento... ¡ya!"
L["One {buff}, {name}! Only slightly sandy."] = "¡{buff}, {name}! Con solo un poquito de arena."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Pide a un vulpera y algo te dará, {name}. Suele ser raro. ¡Hoy no!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "¡Tuyo, {name}! A los vulpera nos encanta regalar. Casi tanto como encontrar."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "¡Toma, {name}! Lo remendé yo. Aguanta mejor de lo que parece."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "¡Claro, {name}! Apártate: hubo tormenta de arena y aún voy soltando dunas."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "¡SÍ! Perdón, {name}, ¿muy alto? El desierto es enorme. Ahí hay que gritar."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "Claro, {name}. Regla de caravana: nadie pide dos veces agua ni ayuda."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "¡Voy, {name}! Hechizo pequeño, vulpera grande, orejas enormes. Espera. Al revés."
L["For you, {name}? Easy! Caravan folk never say no to a neighbour."] = "¿Para ti, {name}? ¡Fácil! En la caravana nunca le decimos que no a un vecino."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Todo viajero necesita algo para el camino, {name}. Lo comprobé: no es una piedra."
L["Keep this, {name}. The desert is long and the water is short."] = "Guarda esto, {name}. El desierto es largo y el agua, escasa."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "Lo encontré por ahí tirado, {name}. ¡Es broma! Es nuevo. ¡Toma!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Toma, {name}. Lo mejor de mi mochila, y mi mochila da para mucho."
L["In the dunes you share your shade and your spells, {name}. Here."] = "En las dunas se comparte la sombra y los hechizos, {name}. Toma."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "Algo de {buff} para ti, {name}. Regatearía, pero se te ve con prisa."
L["A gift from the whole caravan, {name}! They'll never know."] = "¡Un regalo de toda la caravana, {name}! Nunca se enterarán."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "Para el camino, {name}. Los caminos son lo mejor. Eso y picar algo."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "¡Toma, {name}! Cambié un sombrero por una cosa, y la cosa por esto. ¡Buen trato!"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "En las dunas nadie pasa de largo, {name}. Da mala suerte, y es grosero. Toma."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "Mi hocico dice que se te vienen problemas, {name}. Toma. Mi hocico nunca falla."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "Llevo demasiados hechizos en la mochila, {name}. Tintinean. Toma uno, por favor."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "Si luego encuentras algo brillante, {name}, ya sabes dónde están mis orejas. ¡Toma!"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "¡Espera, {name}! Casi te vas sin esto. El desierto se come a quien hace eso."
L["Stew's not ready yet, {name}, so this is the starter."] = "El guiso aún no está listo, {name}; esto es para ir abriendo boca."
L["A fellow wanderer! The caravan is never far, {name}."] = "¡Otro trotamundos! La caravana nunca anda lejos, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "¡Orejas arriba, {name}! Entre zorros da gusto compartir hechizos."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "De vulpera a vulpera, {name}: tengo tres cucharas de sobra, por si acaso."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Vol'dun nos crió, {name}. Arena en el pelaje, suerte en la mochila."
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "De oreja a oreja, {name}: entre tú y yo, oímos todo lo que se dice aquí."
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "¿Te acuerdas de las hogueras de la caravana, {name}? Todos desafinaban. Era perfecto."
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "Vol'dun quedó muy atrás, {name}. La mitad se vino con nosotros en el pelaje."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Leyes de caravana, {name}: ir juntos, compartir el agua, y la alpaca no se vende."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Lo que brille ahí dentro, {name}, lo vi yo primero. Ley de caravana."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "¡Uno para el grupo, {name}! Una caravana va tan rápido como su alpaca más lenta."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Cierra la mochila, {name}. No es que me lleve cosas: me siguen solas."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "En una ciudad me pierdo, {name}; en una cueva, jamás. Son casas sin alquiler."
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "Yo quepo en los túneles pequeños, {name}. Los grandes, para los demás."
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "Grita si necesitas algo, {name}. Seguro que lo tengo. Seguro que abollado."
L["I'll take the back, {name}. Nobody gets left behind in a caravan."] = "Yo cubro la retaguardia, {name}. En una caravana no se deja a nadie atrás."
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "¡Caravana sin carro, {name}! Rápida, ligera y sin lugar para la siesta."
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "Exploré a golpe de hocico, {name}: huele a peligro y a queso rancio."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "¿Todos comieron? ¿Y bebieron? Bien. Ahora esto, {name}. Ley de caravana."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Los vulpera viajamos de noche, {name}. Arena fresca, escórpidos dormidos."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Las noches del desierto hielan, {name}. Toma, algo tibio. Casi."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Hay estrellas, {name}. Cada una es una señal si sabes leerla. Yo no sé."
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "Buena hora para zorros, {name}. Las orejas rinden más cuando todo calla."
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "Anochece y me despierto, {name}. En las dunas, a mediodía se hace la siesta."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "Luego me acurruco en mi cola, {name}. No hay abrigo mejor. Antes, esto."
L["A kindness returned is a kindness doubled, {name}."] = "Bondad devuelta, bondad doblada, {name}."
L["Thank you, {name}. You have restored my balance."] = "Gracias, {name}. Me devolviste el equilibrio."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "En algún lugar, un sha se quedó con hambre. Gracias, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Gracias, {name}. Aysa haría una reverencia; Ji, una fiesta. Yo, las dos, y mal."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Gracias, {name}. Pensaré en ti en mi próxima comida, y en la siguiente."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Chen siempre decía: nunca rechaces un regalo. Ni una copa. Gracias, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "Iba a echarme la siesta, {name}, pero esto es mejor. Un poco. Gracias."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Un hozen te habría tirado algo, {name}. A mí me educaron mejor. Gracias."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "Qué gesto tan pandaren, {name}. Solo le faltó un bollito."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "En Mediacolina eso vale un nabo premiado, {name}. Dejé el mío en casa. Gracias."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "Mi abuela guardaba favores en un tarro, {name}. El tuyo entra; esto sale."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "Gracias, {name}. En el Bosque de Jade mi puerta está abierta. Mi despensa, más."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "Te mueves como un Shadopan, {name}. Ni te vi venir. Gracias."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "Como lluvia en un arrozal, {name}. El arrozal nunca da las gracias. Yo sí."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "Gracias, {name}. Li Li lo apuntaría en su diario de viaje. Con dibujitos."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "Gracias, {name}. Y por los cuatro Augustos Celestiales, que andan ocupados."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "La cerveza de Chen tumba a un pandaren, {name}. Tu gesto, también. Gracias."
L["Now we are even, {name}. A pandaren never lets a kindness go cold."] = "Ahora estamos en paz, {name}. Un pandaren nunca deja que un favor se enfríe."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Claro, {name}. Paciencia y listo. La paciencia es la parte lenta."
L["With pleasure, {name}. A kind deed is never wasted."] = "Un placer, {name}. Hacer el bien nunca es en vano."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Al instante, {name}. Rápido para un pandaren, que no es decir mucho."
L["Master Shang Xi said: help whoever asks, {name}. I listened."] = "El maestro Shang Xi decía: ayuda a quien lo pida, {name}. Le hice caso."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Un maestro Tushui te haría meditar antes, {name}. Esa parte me la salto."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Lo que sea por ti, {name}. Menos el último bollito. No digamos tonterías."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} de la casa, {name}, con cuerpo. La receta es secreta."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "Postura de grulla, {name}: una pierna, cara serena. Con dos también sirve."
L["We never refuse a request, {name}. Or a second helping."] = "Nunca rechazamos una petición, {name}. Ni repetir plato."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "La última en pedirme ayuda, {name}, fue una tortuga-isla. Tú das menos trabajo."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "Ayudo como cocino, {name}: sin prisa, con cariño y para un regimiento."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "Claro, {name}. Deja que suelte el tazón. ...Listo. Eso era lo difícil."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "Sí, {name}. Mi abuelo decía: al invitado no se le hace repetir. Y lo repetía."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "No te muevas, {name}. Calma yo, calma tú, calma el hechizo. Que no cunda el pánico."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Toma, {name}. ¿Y luego quizá una taza de té?"
L["Balance in all things, {name}. Now go with a light heart."] = "Equilibrio en todo, {name}. Ahora ve con el corazón ligero."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Toma, {name}. Un grummel te lo vendería por un amuleto de la suerte."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "Los jinyu dicen que las aguas lo predijeron, {name}. Lo dicen mucho."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Los Huojin dicen: actúa. Los Tushui dicen: piensa. Yo digo: toma, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Un pandaren se levantó para darte esto, {name}. Atesóralo."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Pelea como un monje, {name}: calma, rapidez y después, comida larga."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Ve con calma, {name}. La tortuga llegó a su destino sin correr ni una vez."
L["A hug would be forward, {name}. This is next best, and less furry."] = "Un abrazo sería demasiado, {name}. Esto es lo más parecido, y con menos pelo."
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "Si una pelea te encuentra, {name}, rueda. Rodar está muy subestimado."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "Para ti, {name}. Es cálido, redondo y lleno de buenas intenciones. Como yo."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "Toma, {name}. Mi cometa se enganchó en un árbol y tengo tiempo para buenas obras."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "Traje esto desde Pandaria, {name}. Y un barril. El barril es mío."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "Los virmen se llevaron mis zanahorias, {name}. Esto, jamás. Toma."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "En la Isla Errante, al forastero se le da sopa, {name}. Esto viaja mejor."
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "Parecemos blanditos, {name}. Un saco de arroz también, hasta que te cae encima."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "Chi-Ji dice que siempre hay esperanza, {name}. Yo, que siempre sobra uno. Toma."
L["We must share a brew when the road allows, {name}!"] = "¡Cuando el camino lo permita, una cerveza juntos, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Shen-zin Su estaría orgulloso de nosotros, {name}. O dormido. Cuesta saberlo."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Dos pandaren juntos, {name}. Algún posadero acaba de sentir un escalofrío."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Liu Lang lo aprobaría, {name}: dos de los nuestros, muy lejos de casa."
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "Tushui o Huojin, {name}: los dos dejamos la tortuga y los dos añoramos su comida."
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "De pandaren a pandaren, {name}: aquí las cervezas son agua. Luego compartimos la mía."
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "Olemos a vino de arroz y polvo del camino, {name}. Huele a hogar."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "Entre pandaren nos cuidamos, {name}. Sobre todo, a base de comida. Esto, de entrante."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Primero la pelea y luego la comida, {name}. Ese es el orden. Nunca al revés."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "No nos separemos, {name}, como bollitos en la vaporera. Calentitos y a punto."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "Nos movemos como uno, {name}. Despacio, quizá, pero como uno."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Equilibrio, {name}: uno lucha, otro cura y otro lleva la merienda. Yo."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Si caemos, {name}, caemos juntos, y luego una siesta. Mejor que no."
L["Stay behind me, {name}. I am soft, but I am very wide."] = "Detrás de mí, {name}. Mi barriga es blanda, pero ancha."
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "Si ganamos, {name}, cocino yo. Si perdemos, también cocino, pero triste."
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "Respiremos, {name}. Dentro, fuera. Y ahora, a pegar con calma."
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "No te quedes atrás, {name}. Tengo prisa. A un pandaren le pasa una vez por década."
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "Un grupo es como una cerveza, {name}: mezcla rara, resultado genial. Casi siempre."
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "Si caigo, {name}, llévame rodando a salvo. Cargarme no es una opción."
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "Luchamos como el agua, {name}: calma, paciencia y, de pronto, por todas partes."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "¿En pie antes del té, {name}? Qué valor. Toma, en lugar del té."
L["Morning, {name}. First this, then breakfast, then more breakfast."] = "Buenos días, {name}. Primero esto, luego el desayuno, y luego más desayuno."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Un nuevo día, {name}, y nadie derramó nada todavía. Empecemos con suavidad."
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "Los granjeros de Mediacolina llevan horas en pie, {name}. Yo, minutos."
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "Niebla matinal, {name}. Parecía mi tierra. Luego pasó un kóbold."
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "Buenos días, {name}. Mi estómago se despertó primero y desde entonces da órdenes."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Entre mi primera siesta y la segunda, {name}. Rápido, antes de que me duerma."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "Es tarde, {name}. Los maestros cerveceros duermen. Las cervezas, sospecho, no."
L["Midnight snack time, {name}. This is the appetiser."] = "Hora de asaltar la despensa, {name}. Esto es el aperitivo."
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "¿Ya de noche, {name}? En casa, ahora empezarían las historias del abuelo."
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "La luna está redonda y llena esta noche, {name}. Tenemos mucho en común."
L["Your kindness is noted, {name}. Dragons do not forget."] = "No olvidaré tu bondad, {name}. Los dragones nunca olvidan."
L["Thank you, {name}. Returned on swift wings."] = "Gracias, {name}. Te lo devuelvo con alas veloces."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Alas, fuego y escamas, {name}, y aun así pensaste que necesitaba ayuda. Qué detalle."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Me inclinaría, {name}, pero la última vez mis alas barrieron una mesa. Gracias."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Esto va directo a mi tesoro, {name}. Las buenas obras son el único oro que guardo."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "Me crearon para ser un arma, {name}. Prefiero mucho más esta parte. Gracias."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Gracias, {name}. Wrathion habría soltado un discurso. Yo no."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Te lo devuelvo con un poco de fuego, {name}. Solo un poco. Estoy practicando."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "Regalo de mortal, {name}: pequeño, breve y amable. Me van gustando las tres cosas."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "Gracias, {name}. Aún no domino las costumbres mortales. ¿Te pago? ¿No? Pues toma."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "Gracias, {name}. Tengo escamas donde otros tienen sentimientos. Y me llegó."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "Estás en mi lista de mortales favoritos, {name}. Estaba vacía hasta hoy."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "Mi parte roja te lo agradece, {name}. La negra sospecha. Gana la roja."
L["Thank you, {name}. Dragons are not used to receiving. I find I like it."] = "Gracias, {name}. Los dragones no estamos acostumbrados a recibir. Descubro que me gusta."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "Un dragón da las gracias con un rugido, {name}. Por los vecinos, me lo ahorro."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Muy bien, {name}. No te muevas, no quisiera chamuscarte."
L["Granted, {name}. A dragon keeps its word."] = "Concedido, {name}. Un dragón cumple su palabra."
L["Certainly, {name}. Stand clear of the tail."] = "Desde luego, {name}. Aléjate de la cola."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Por supuesto, {name}. ¿Esto aún se hace así? Dormí un ratito."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "Con gusto, {name}. Llevo dentro los cinco vuelos, y los cinco dicen que sí."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "Enseguida, {name}. Ayuda de tamaño dragón, en formato de bolsillo."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Claro, {name}. Neltharion solo daba órdenes. Una petición se agradece más."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "Enseguida, {name}. Apártate un poco: aún no controlo bien mi tamaño."
L["Certainly, {name}. Claws are not ideal for spellwork, but I manage."] = "Desde luego, {name}. Las garras no son ideales para los hechizos, pero me apaño."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "Claro, {name}. Los dragones suelen exigir tributo. Por esta vez, te lo perdono."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "Claro, {name}. Y no grites. Los mortales suelen gritar. Serán los cuernos."
L["My breath is fire, {name}, so we will do this the other way."] = "Echo fuego por la boca, {name}, así que lo haremos de otra manera."
L["Gladly, {name}. Mortals so rarely ask a dragon for anything but mercy."] = "Con gusto, {name}. Los mortales rara vez piden a un dragón otra cosa que clemencia."
L["A small magic, {name}, but I cast it with enormous dignity."] = "Una magia pequeña, {name}, pero la lanzo con enorme dignidad."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Toma, {name}. Hasta un dragón necesita aliados. Y más uno de este tamaño."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Un regalo de las Islas Dragón, {name}. Buen vuelo."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Alexstrasza dice que toda vida es valiosa, {name}. Empiezo por la tuya."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "Me perdí diez mil años de buenas obras, {name}. Ahora me pongo al día."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Cuenta que fue obra de un dragón, {name}. Suena más épico de lo que fue."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Orden del comandante de escamas, {name}. O mía, pero suena mejor."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Toma, {name}. Magia dracónica ancestral, apenas algo caducada."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Un dragón que da en vez de saquear, {name}. Pruebo algo nuevo."
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "Esta forma no asusta, {name}. La de Lady Prestor, tampoco. La mía es de fiar."
L["A gift from above, {name}. I landed specially. It took two tries."] = "Regalo caído del cielo, {name}. Aterricé adrede. Al segundo intento."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "Toma, {name}. Todo dragón debe custodiar algo. Te elegí a ti, de momento."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "Toma, {name}. Es de cinco vuelos a la vez, así que no pega con nada."
L["I'd fly you there myself, {name}, but dracthyr carry no riders. Take this."] = "Te llevaría volando, {name}, pero los dracthyr no llevamos jinetes. Toma esto."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "Los dragones dotaron al mundo naciente, {name}. Lo mío es menor y llega tarde."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "Un poco de esencia para ti, {name}. Es mi materia prima, trátala con cuidado."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "Toma, {name}. Lo notarás calentito: todo lo que toco se calienta."
L["The Forbidden Reach feels far behind us now, {name}."] = "Nuestro largo letargo ya queda muy atrás, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Dos dracthyr juntos, {name}. Cuidado con las alas: aquí no caben cuatro."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "¿Recuerdas cuando el mundo entero nos era nuevo, {name}? Casi todo aún lo es."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "En forma humanoide nadie lo nota, {name}. Entre tú y yo: con escamas lucimos más."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "Hechos para la guerra, {name}, y compartiendo. A alguien le falló el plan."
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "Con escamas o sin ellas, {name}, a los nuestros los reconozco. Por la postura."
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "Los mortales siempre nos piden ir a lomos, {name}. Y sigue siendo que no."
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "Entre dracthyr, {name}: los cuernos y los sombreros nunca se llevan bien."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Avísame cuándo echar fuego, {name}. Y, por favor, cuándo no."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "Desperté en una cueva llena de extraños, {name}. Esta compañía es mejor."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Neltharion nos diseñó para luchar a solas, {name}. Mejoramos el diseño."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "No te acerques a mi cola, {name}. Aún no sabe de qué bando está."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Un vuelo propio, {name}. Así que a esto se referían los dragones."
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "Si grito '¡a cubierto!', {name}, es detrás de mis alas. Para eso sirven."
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "Ponte a mi lado, {name}, nunca delante. Mi aliento no tiene modales."
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "Los grandes, para mí, {name}. Bueno, los más pequeños que yo. Casi todos."
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "No te alejes, {name}. Bajar planeando, desde donde sea. Subir ya es cosa tuya."
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "No te pares, {name}. Un dragón con prisa impone. Uno esperando solo estorba."
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "Cuéntame el plan despacio, {name}. Yo solo sé planear en el aire."
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "Los mortales viven tan poco, {name}. No acortemos más el día de hoy."
L["Thank you, {name}. Where I come from, a kindness is tended like a root."] = "Gracias, {name}. De donde vengo, la bondad se cuida como una raíz."
L["Hagar sent me to see the goddess's work, {name}. You're some of her best."] = "Hagar me envió a ver la obra de la diosa, {name}. Tú eres de lo mejor."
L["Kindness echoes, {name}, and I grew up in a cavern. Here it comes back to you."] = "La bondad hace eco, {name}, y me crie en una caverna. Aquí vuelve a ti."
L["My Legacy Stone showed who I'd stand beside, {name}. It forgot you. Thank you."] = "Mi Piedra de legado me mostró a quién tendría al lado, {name}. Se olvidó de ti. Gracias."
L["We read lives in a root's rings, {name}. Yours just grew a kind one."] = "En los anillos de una raíz se lee una vida, {name}. La tuya suma uno amable."
L["The Shul'ka gave up everything to guard us, {name}. I can give this much."] = "Los Shul'ka lo dejaron todo por protegernos, {name}. Yo puedo dar esto."
L["The world is more than Harandar, the Song said, {name}. Thanks for proving it."] = "El mundo es más que Harandar, dijo la Canción, {name}. Gracias por demostrarlo."
L["Thank you, {name}. Orweyna said outsiders had much to teach us. I'm learning."] = "Gracias, {name}. Según Orweyna, los forasteros pueden enseñarnos mucho. Voy aprendiendo."
L["Our oaths forbid speaking to outsiders, {name}. I'll risk a thank you."] = "Nuestros votos prohíben hablar con forasteros, {name}. Me arriesgo: gracias."
L["My people lived up here once, {name}. Thanks to you, I can see why."] = "Mi pueblo vivió aquí arriba antaño, {name}. Gracias a ti, entiendo por qué."
L["We're raised on dedication and humility, {name}, so I'll just say thank you."] = "Nos crían en la entrega y la humildad, {name}, así que solo diré gracias."
L["Back home I'd dance for that, {name}. Up here people stare, so: thank you."] = "En casa bailaría por esto, {name}. Aquí la gente se queda mirando, así que: gracias."
L["Thank you, {name}. You've left me glowing like a moth back in Harandar."] = "Gracias, {name}. Me has dejado brillando como una polilla de Harandar."
L["Har'mara is the Village of Balance, {name}. I'd hate to go home lopsided."] = "Har'mara es la Aldea del Equilibrio, {name}. No volveré con la balanza torcida."
L["If Aln'hara can hear anything where she is, {name}, I hope she heard that."] = "Si Aln'hara oye algo desde donde está, {name}, ojalá haya oído esto."
L["Of course, {name}. Protect, tend and serve, my people say. This is the serving."] = "Claro, {name}. Proteger, cuidar y servir, dice mi pueblo. Esto es lo de servir."
L["Of course, {name}. I answered the goddess's call. Yours is far easier to hear."] = "Claro, {name}. Respondí a la llamada de la diosa. La tuya se oye mucho mejor."
L["Of course, {name}. Dalnir would call this a distraction. Dalnir isn't here."] = "Claro, {name}. Dalnir diría que esto es una distracción. Dalnir no está."
L["Of course, {name}. The roots never ask for anything. It's nice to be asked."] = "Claro, {name}. Las raíces nunca piden nada. Da gusto que te pidan algo."
L["Gladly, {name}. Back home I'd have had to pretend I never saw you."] = "Con gusto, {name}. En casa habría tenido que fingir que no te vi."
L["Of course, {name}. Mind the quills; they're friendlier than they look."] = "Claro, {name}. Cuidado con las púas: son más simpáticas de lo que parecen."
L["Gladly, {name}. Don't stand still too long; in Harandar you'd sprout mushrooms."] = "Con gusto, {name}. No pases mucho rato sin moverte: en Harandar te saldrían setas."
L["Of course, {name}. I was raised to do exactly as I was told. For once, I will."] = "Claro, {name}. Me criaron para hacer justo lo que me dijeran. Por una vez, lo haré."
L["No alndust in this one, {name}. Nothing will come to life and bite you."] = "Esto no lleva polvo de Aln, {name}. Nada cobrará vida para morderte."
L["Of course, {name}. Half the names up here are new to me. Yours I'll keep."] = "Claro, {name}. Aquí la mitad de los nombres me son nuevos. El tuyo me lo quedo."
L["{buff}, {name}, grown under the World Trees and picked fresh."] = "{buff}, {name}: cosecha del día, crecida bajo los Árboles del Mundo."
L["Of course, {name}. Hagar is handling things at home; I'll handle them up here."] = "Claro, {name}. En casa se ocupa Hagar; aquí arriba, yo."
L["At my initiation I was asked who I really am, {name}. Someone who says yes."] = "Al iniciarme me preguntaron quién soy de verdad, {name}. Alguien que dice que sí."
L["Take this, {name}, from a long way below. The roots send their regards."] = "Toma, {name}, desde muy abajo. Las raíces te mandan saludos."
L["Take this, {name}, and may Aln'hara be with you."] = "Toma, {name}, y que Aln'hara te acompañe."
L["The sky has no ceiling, {name}. Anything could fall on you. Take this."] = "El cielo no tiene techo, {name}. Podría caerte cualquier cosa. Toma."
L["Follow the visions, Hagar said, {name}. Today they pointed at you. Take this."] = "Sigue las visiones, decía Hagar, {name}. Hoy me señalaron a ti. Toma."
L["My people would have watched you from the brush, {name}. I'd rather do this."] = "Mi pueblo te habría espiado desde la maleza, {name}. Yo prefiero esto."
L["Harandar stayed out of the world's wars, {name}. You weren't so lucky. Here."] = "Harandar se libró de las guerras del mundo, {name}. Tú no tanto. Toma."
L["The Zur'ashar paint every tale worth telling, {name}. Make yours a long one."] = "Los zur'ashar pintan toda historia digna de contarse, {name}. Que la tuya sea larga."
L["Go carefully, {name}. The goddess's world is a garden, and gardens have thorns."] = "Cuidado, {name}. El mundo de la diosa es un jardín, y los jardines tienen espinas."
L["We tend roots in Harandar, {name}. You look as if you could use some tending."] = "En Harandar cuidamos raíces, {name}. Y a ti no te vendrían mal unos cuidados."
L["My ancestors grew restless and sought a purpose, {name}. I've found mine. Here."] = "Mis ancestros, inquietos, buscaron un propósito, {name}. Yo ya tengo el mío. Toma."
L["Har'mara lives at peace with its neighbours, {name}. I'd like that to spread."] = "Har'mara vive en paz con sus vecinos, {name}. Ojalá se contagie."
L["The first outsiders I met were fighting off a saptor, {name}. Best take this."] = "Los primeros forasteros que vi luchaban contra una fiera, {name}. Mejor toma esto."
L["My people have kept hope alive for ages on very little, {name}. Have some."] = "Mi pueblo ha mantenido la esperanza siglos con casi nada, {name}. Toma un poco."
L["I'm still learning what to say to strangers, {name}. This seemed safest."] = "Aún aprendo qué decirles a los desconocidos, {name}. Esto parecía lo más seguro."
L["My people live beside a wound that never heals, {name}. Come back without one."] = "Mi pueblo vive junto a una herida que nunca sana, {name}. Tú vuelve sin ninguna."
L["Two haranir out in the world, {name}. No wonder the elders are up in arms."] = "Dos haranir por el mundo, {name}. Los ancianos pondrán el grito en el cielo."
L["Did the Song call you up as well, {name}? It never says where it's going."] = "¿A ti también te hizo subir la Canción, {name}? Nunca dice adónde lleva."
L["Keep to the brush, they told us, {name}. We are both very bad at it."] = "Quedaos en la maleza, nos decían, {name}. A los dos se nos da fatal."
L["Harandar's roots run under all of this, {name}. We're never far from home."] = "Las raíces de Harandar corren bajo todo esto, {name}. Nunca estamos lejos de casa."
L["We're both out here looking for the goddess, {name}. Two pairs of eyes, then."] = "Los dos andamos buscando a la diosa, {name}. Cuatro ojos ven más que dos."
L["We were both told to give up childish adventures, {name}. Look at us now."] = "A los dos nos dijeron que dejáramos las aventuras de críos, {name}. Míranos ahora."
L["Nobody up here speaks Hara'ni, {name}. We could say anything."] = "Aquí nadie habla hara'ni, {name}. Podríamos decir cualquier cosa."
L["The outsiders keep asking where we're from, {name}. I just point down."] = "Los forasteros siempre preguntan de dónde somos, {name}. Yo señalo abajo."
L["Stay close, {name}. A haranir needs something to guard, and today it's you."] = "No te alejes, {name}. Un haranir necesita algo que proteger, y hoy eres tú."
L["We once mastered every beast on our mountain, {name}. These won't take long."] = "Antaño domamos cada bestia de nuestra montaña, {name}. Con estas acabamos enseguida."
L["Word from Harandar, {name}: the haranir are ready to join the fight."] = "Noticias de Harandar, {name}: los haranir están listos para luchar."
L["My people's oldest shame is fighting each other, {name}. Let's fight together."] = "La vergüenza más vieja de mi pueblo es luchar entre hermanos, {name}. Hoy, codo con codo."
L["Mind your step, {name}. Where I'm from, the floor is mostly somebody's roots."] = "Mira dónde pisas, {name}. De donde vengo, el suelo es casi todo raíces de alguien."
L["If anything crawls up from below, {name}, leave it to me. I know the type."] = "Si algo sale reptando de abajo, {name}, déjamelo. Conozco a esa calaña."
L["Dangerous, {name}? My ancestors walked into the deep with no idea what waited."] = "¿Peligroso, {name}? Mis ancestros bajaron a las profundidades a ciegas."
L["Do not fear the dark, {name}. Orweyna's words, and I keep them close."] = "No temas a la oscuridad, {name}. Palabras de Orweyna; las llevo conmigo."
L["I'll take the ledges, {name}. Clawed feet were made for this."] = "Yo voy por las cornisas, {name}. Para eso tengo garras en los pies."
L["The goddess's world is worth fighting for, {name}. Even this bit of it."] = "El mundo de la diosa merece que luchemos por él, {name}. Hasta este rincón."
L["I've cleared weeds, mud skippers and invasive fungi, {name}. Nothing scares me."] = "Malas hierbas, brincadores de barro, hongos invasores: ya nada me asusta, {name}."
L["The Zur'ashar won't paint this fight, {name}. Let's win it anyway."] = "Los zur'ashar no pintarán esta batalla, {name}. Ganémosla igualmente."
L["It is good to see one of our own, {name}."] = "Da gusto ver a alguien de los nuestros, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Somos pocos, {name}. Por eso cada uno cuenta."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Gracias, {name}. La Alianza cuida de los suyos, y hoy me tocó a mí."
L["Kindness answered, {name}. For the Alliance!"] = "Bondad correspondida, {name}. ¡Por la Alianza!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "Ventormenta tiene estatuas para cada héroe, {name}. Propondré la tuya."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "Así es la Alianza, {name}: tú me ayudas, yo te ayudo y un enano invita."
L["Bolvar would bow, Magni would hug, {name}. I'll just return it."] = "Bolvar haría una reverencia y Magni te abrazaría, {name}. Yo solo te lo devuelvo."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Si la Alianza premiara los modales, {name}, necesitarías otro tabardo."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Devuelto con creces, {name}. Quien da primero vale por toda una guarnición."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "Gracias, {name}. Te nombraré en mi carta a casa. Mi madre las lee en voz alta."
L["Thank you, {name}. Even the Stormwind guards would smile at that."] = "Gracias, {name}. Hasta los guardias de Ventormenta sonreirían."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "Lo mejor de la Alianza, {name}: nadie lo pidió y alguien ayudó. Gracias."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "Lo contaré en el Tranvía Subterráneo, {name}. El viaje es largo. Gracias."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "Muy galante, {name}. Si llevara un león en el tabardo, estaría ronroneando."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "Los reyes discuten, {name}; sus pueblos se llevan de maravilla. Gracias."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "La Alianza se forjó con gente de palabra, {name}. Aquí tienes la mía."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Por supuesto, {name}. Los aliados se ayudan. Va en el nombre."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Al instante, {name}. La Alianza no desampara a los suyos."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Claro, {name}. Viene en la carta de la Alianza. Por el final, en letra pequeña."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Por orden de la Alianza, {name}: {buff}, con efecto inmediato."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Lo que sea entre aliados, {name}, dentro de lo razonable. Y esto lo es."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "Enseguida, {name}. El IV:7 sabía que lo pedirías. Yo me acabo de enterar."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "Ahora mismo, {name}. La Alianza marcha a base de peticiones como la tuya. Y de pan."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "Sí, {name}. De Ventormenta a Forjaz, 'por favor' abre todas las puertas."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "Enseguida, {name}. Llevo todo el día de azul esperando que alguien lo pidiera."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "No te muevas, {name}. Esto lo aprendí antes que el himno de la Alianza."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "Claro, {name}. Con ejércitos se ganan guerras; con favores, aliados. Toma uno."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "¡Por la Alianza, {name}! Mantente fuerte ahí fuera. Ahora, más aún."
L["Onward, {name}. The Alliance is with you."] = "Adelante, {name}. La Alianza está contigo."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Toma, {name}. Si lo hubiera hecho un gnomo, traería doce palancas."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Cortesía de la Alianza, {name}. Lo hacemos desde la Segunda Guerra."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Ánimo, {name}. En Ventormenta ya hay un bardo escribiendo esto."
L["Every ally counts, {name}. Today, you count double."] = "Cada aliado cuenta, {name}. Hoy, tú cuentas doble."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Anduin querría que compartiera, {name}, y no me gustaría decepcionarlo."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "Toma, {name}. Las murallas de Ventormenta no pueden seguirte; esto sí."
L["Here, {name}. The gryphons get you there; this gets you back."] = "Toma, {name}. Los grifos te llevan; esto te trae de vuelta."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "Ley aliada, {name}: cuida tu palabra, tus murallas y tus amistades. Por la nuestra."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "Todo aliado merece un león a su espalda, {name}. El más cercano soy yo."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "Un regalo de la Alianza, {name}. Firmado, sellado y entregado en mano."
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "La Alianza nunca olvida a los valientes, {name}. Dale algo que recordar."
L["Together we stand, {name}. For the Alliance!"] = "Unidos resistimos, {name}. ¡Por la Alianza!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Bien, {name}: escudos arriba, cabeza agachada y nadie carga antes que el plan."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "La mejor compañía que jamás reunió la Alianza, {name}. O la que tenía más a mano."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Juntos, {name}, somos casi un regimiento. Uno pequeño y muy bien vestido."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Cubrámonos las espaldas, {name}. Así se construyó la Alianza."
L["Shields together, {name}. The Alliance never won anything in single file."] = "Escudos juntos, {name}. La Alianza nunca ganó nada en fila india."
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "Si esto pasa a la historia, {name}, que sea como capítulo, no como nota al pie."
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "Quien lleve el estandarte, {name}, sale muy noble en el cuadro. ¿Voluntarios?"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "Temple enano, paciencia élfica, terquedad humana, {name}: la receta de la Alianza."
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "Que ruja el león, {name}. Bajito, ¿eh? Vamos a hurtadillas."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Fuerza y honor, {name}. Y bondad, por lo visto. Te lo devuelvo todo."
L["The Horde takes care of its own, {name}."] = "La Horda se ocupa de los suyos, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Fuerza dada, fuerza devuelta, {name}. Esa es toda la diplomacia de la Horda."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Grabaría tu nombre en las puertas de Orgrimmar, {name}, pero no cabe. Gracias."
L["A goblin would've sent you an invoice, {name}. I'm sending this instead."] = "Un goblin te habría mandado la factura, {name}. Yo te mando esto."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "No tenías por qué hacerlo, {name}. Por eso la Horda lo recuerda."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "En la Horda no damos las gracias dos veces, {name}. Así que una, y de corazón."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "En la Horda, una deuda se lleva como un hacha, {name}: a la vista y poco tiempo."
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "Los brutos de la puerta sabrán de ti, {name}. Gruñirán. Es señal de respeto."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "La Horda lleva dos listas, {name}: rencores y favores. Tú estás en la corta."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "El honor manda devolverlo, {name}; los modales, sonreír. Ensayo la sonrisa."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "Más suave que cualquier aterrizaje en zepelín, {name}. Gracias."
L["Thanks, {name}, in Orcish, Taur-ahe, Zandali and Gutterspeak. Pick one."] = "Gracias, {name}, en orco, taur-ahe, zandalí y viscerálico. Elige uno."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "Thrall enseñó honor a la Horda, {name}. A ti no hizo falta enseñártelo. Gracias."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "Diste primero, {name}. En la Horda eso te gana la primera tajada del asado. Toma."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "El Jefe de Guerra no puede dar las gracias a todos, {name}. Me lo delegó a mí."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Considéralo hecho, {name}. Por la Horda, y por quien lo pida con educación."
L["You only had to ask, {name}. The Horde answers."] = "Solo tenías que pedirlo, {name}. La Horda responde."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "La Horda suele ayudar a hachazos, {name}. Hoy, con {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "Hecho, {name}. Sin discursos. La Horda ya tiene de sobra."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Lo pediste, {name}. En Orgrimmar, eso cuenta como tratado formal."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Pedir no es debilidad, {name}. Negarse a un aliado sí lo sería."
L["No need to bang a war drum, {name}. You asked; it's done."] = "Sin tambores de guerra, {name}. Lo pediste y listo."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "Claro, {name}. En la Horda, 'por favor' solo tiene por encima al Jefe de Guerra."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "En Orgrimmar primero lo habríamos discutido, {name}. Tradición. Toma."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "Considéralo requisado, {name}. El intendente no tiene por qué enterarse."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "Hecho, {name}. Si preguntan, lo hice con mala cara. Tengo una fama que cuidar."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "Claro, {name}. Hospitalidad de la Horda: trato tosco, plato lleno."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "La Horda se unió porque alguien siempre dijo que sí, {name}. Sí."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "¡Por la Horda, {name}! Ve con fuerza. Acabo de darte un poco."
L["Go with honour, {name}. Victory awaits."] = "Ve con honor, {name}. La victoria te espera."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Haz algo digno de una canción, {name}. A todo pulmón, como le gusta a la Horda."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Cabeza alta, {name}. La Horda siempre acogió a quien el mundo rechazó."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Toma, {name}, y un consejo de la Horda: pega primero y no pidas perdón nunca."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "Victoria o muerte, {name}. Yo prefiero la victoria, así que toma."
L["Blood and thunder, {name}! Go and be the thunder."] = "¡Sangre y trueno, {name}! Ve y sé el trueno."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "Por la Horda, {name}, y por ti. La Horda es grande; tú estás más cerca."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "Dicen que la unión hace la fuerza, {name}. Yo ya puse mi mitad."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "Llévalo, {name}. Pesa menos que un estandarte de la Horda y ondea igual de alto."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "Toma, {name}. La Horda alimenta a los suyos, los arma y, ahora, los encanta."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "Toma, {name}. Lo que haya ahí fuera está a punto de conocer a la Horda."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "Toma, {name}. Vayas adonde vayas, que se note que te manda la Horda."
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "El Cruce nunca rechazó a un viajero, {name}. A algunos les cobró de más."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "La Horda enseña a aguantar, {name}. Esto es para cuando aguantar no basta."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "Regalo de la Horda, {name}: sin lazo, sin discurso y sin devoluciones."
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "Cabeza alta, {name}. Más. En la Horda hay que estar a la altura de los tauren."
L["Our strength is each other, {name}. For the Horde!"] = "Nuestra fuerza es la unión, {name}. ¡Por la Horda!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "Adelante, {name}. La Horda avanza unida. ¿Retirarse? Oficialmente, nunca."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Juntos, una partida de guerra, {name}. Por separado, solo ruido."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Hombro con hombro, {name}. Quien cargue primero paga el grog."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Aquí no se abandona a nadie, {name}. Nos conté dos veces."
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "Ley de guerra, {name}: aquí nadie come hasta que vuelvan todos."
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "Tambores arriba, {name}. Si no hay sigilo, que haya terror."
L["The Horde never won a thing alone, {name}. Let's not start now."] = "La Horda nunca ganó nada en solitario, {name}. No empecemos ahora."
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "Peleamos como la Horda, {name}: todos a la vez y sin esperar la señal."
L["Right, {name}. Spoils shared, blame shared, glory to the loudest."] = "Bien, {name}: botín a medias, culpa a medias y gloria para quien más grite."
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "Míranos, {name}. El Jefe de Guerra estaría orgulloso. Un poco. De lejos."
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "Colmillos, cuernos, orejotas y huesos, {name}. No hay mejor tropa."
L["The war stories get bigger after, {name}. Let's give them a head start."] = "Las historias de guerra crecen al contarlas, {name}. Démosles ventaja."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Gracias, {name}. Hay buena gente en cada bando, y por lo visto también aquí."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Gracias, {name}. Sin bando ni título, solo bondad. Así empiezan las leyendas."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Gracias, {name}. La bondad no tiene facción, y viene bien, porque yo tampoco."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Gracias, {name}. El bando que te fiche se lleva una ganga."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Acabe en el bando que acabe, {name}, a ti te recordaré primero. Gracias."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Soy estrictamente neutral, {name}, pero la gratitud no cuenta. Gracias."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "Gracias, {name}. Sin estandarte que llevar, tengo las manos libres para esto."
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "Los Bonvapor son neutrales por el oro, {name}. Yo, por momentos como este."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "Aún no aprendí a agradecer como ningún bando, {name}. Toma la versión sencilla."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "Gracias, {name}. Estoy entre dos grandes estandartes, y aun así te fijaste en mí."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "Dos bandos en guerra, {name}, y en medio, nosotros, derrochando encanto. Gracias."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "Con gusto, {name}, sea cual sea tu estandarte. Yo ni tengo estandarte."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Claro, {name}. Ayudo a todos. Es lo único que tengo decidido."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "Todos me preguntan de qué bando soy, {name}. Prefiero que me pidan ayuda."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Claro, {name}. No hay consejo de guerra: solo yo, y digo que sí."
L["Here you are, {name}. No oath, no colours, no fee."] = "Toma, {name}. Sin juramento, sin colores, sin cobrar."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "Aún no puedo elegir bando, {name}, pero sí una buena causa. Esta lo es."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "Al instante, {name}. No tengo bando, así que de momento estoy del tuyo."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "Claro, {name}. Nadie me paga por tomar partido, así que tomo peticiones."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "Ser neutral no es negarse, {name}. Es ayudar primero y no discutir nunca."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "Hay amigos en todos los bandos, {name}. O, como yo, en ninguno en concreto."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Pronto nos darán tabardos, {name}. Mientras tanto, nos cuidamos entre nosotros."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Aún no elegí bando, {name}, así que soy amable con los dos. Toma."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Un regalo sin ataduras, {name}. Ni siquiera tengo facción a la que atarlo."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Vamos, {name}. Dos facciones esperan para pelearse por nosotros."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Aún sin intendente, {name}, nadie lleva la cuenta. Toma de sobra."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "Toma, {name}. El terreno neutral viaja conmigo; estás pisando un poco."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "El Alba Argenta ayuda a quien lo necesite, {name}. Aprendo de los mejores."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "Bahía del Botín prohíbe pelear en los muelles, {name}. Yo, rechazar regalos."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "Lo único en lo que coinciden ambas facciones, {name}. Aunque aún no lo saben."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "Esto pega con cualquier tabardo, {name}. Por eso no le puse ningún color."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "Para ti, {name}. No lo manda Orgrimmar ni Ventormenta. Funciona igual."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "Toma, {name}. Aún no pertenezco a ninguna nación, así que practico con todas."
L["Side by side, {name}, whatever comes."] = "Codo con codo, {name}, pase lo que pase."
L["No flag over this party, {name}, just us. That's plenty."] = "Sin bandera en este grupo, {name}, solo nosotros. Y basta."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Algún día elegiremos bando, {name}. Hoy, a quién pegarle."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "Esté el mundo del bando que esté, {name}, yo estoy del de este grupo."
L["Neutral in the war, {name}, but very partial to this group."] = "Neutral en la guerra, {name}, pero muy parcial con este grupo."
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "Seremos neutrales, {name}, pero nadie dijo nada de ser discretos."
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "Luchemos contra lo que luchemos hoy, {name}: nada personal. Solo muy a fondo."
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "Un bando en este grupo, {name}: el nuestro. La menor facción de Azeroth. La mejor."
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "Ninguna capital nos da órdenes, {name}. Elegimos nuestro camino. Rápido, eso sí."
L["No war to win today, {name}, just this one fight. Much more manageable."] = "Hoy no hay guerra que ganar, {name}, solo este combate. Mucho más manejable."
L["One good turn deserves another, {name}."] = "Favor con favor se paga, {name}."
L["Have some {buff} in return, {name}."] = "Toma algo de {buff} a cambio, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "La amabilidad tiene que ser mutua, {name}. Gracias."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Tú diste el primer paso, {name}; yo doy el segundo. Eso es amistad."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Te escribiría una canción, {name}, pero {buff} desafina menos."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Regalo por regalo, {name}. A este ritmo, para la cena seremos imparables."
L["All square, {name}. Unless you'd like to make it best of three."] = "Estamos en paz, {name}. Salvo que quieras jugarlo al mejor de tres."
L["You started it, {name}. I'm only finishing it."] = "Tú empezaste, {name}. Yo solo lo termino."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "Qué amable, {name}. El día acaba de mejorar bastante. Aquí va mi parte."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "Iba a hacerlo yo, {name}. En serio. Aquí tienes la prueba."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "Gracias, {name}. Esta noche dormiré mejor, y eso que duermo en una zanja."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "Hoy, dos cosas buenas, {name}: tu bondad y poder devolvértela."
L["You had me in your debt for all of three seconds, {name}. There."] = "Estuve en deuda contigo tres segundos enteros, {name}. Listo."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "La gratitud se sirve caliente, {name}. Aquí la tienes, recién hecha."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "Vaya, {name}, ahora me toca ser mejor persona todo el día. Gracias, ¿eh?"
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "Devuelto con una reverencia, {name}. Figurada. Mi espalda ya no es lo que era."
L["Thank you, {name}. Somebody had to go first, and I'm glad it was you."] = "Gracias, {name}. Alguien tenía que empezar, y me alegro de que fueras tú."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "Gracias, {name}. Salvaste un día que di por perdido en el desayuno."
L["You asked, {name}, and here it is."] = "Lo pediste, {name}, y aquí lo tienes."
L["{buff}, coming right up, {name}."] = "{buff} en camino, {name}."
L["Gladly, {name}. One moment."] = "Con gusto, {name}. Un momento."
L["Asked and answered, {name}. Next question?"] = "Pedido y respondido, {name}. ¿Siguiente pregunta?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Dime una palabra y es tuyo, {name}. Dijiste varias. Toma."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "¿Para ti, {name}? Con gusto. Esperaba que alguien lo pidiera."
L["Of course, {name}. Easiest yes I'll say all day."] = "Claro, {name}. El sí más fácil que diré hoy."
L["Right away, {name}. Finally, a question I know the answer to."] = "Enseguida, {name}. Por fin una pregunta que sé responder."
L["Of course, {name}. Nicely asked, gladly given."] = "Claro, {name}. Bien pedido, con gusto dado."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "No te muevas, {name}. Funciona mejor con quien no se mueve. O sea, con nadie."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "Aquí tienes, {name}. Haría una pausa dramática, pero serían malos modales."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "Sí, {name}. Y habría sido antes si lo hubieras pedido antes."
L["Say no more, {name}. Done before you finished asking."] = "No digas más, {name}. Hecho antes de que acabaras de pedirlo."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "Listo, {name}. La próxima, no pidas: quédate cerca con cara de ilusión."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "En camino, {name}. Es lo único de mi día que sale según el plan."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "Pedir por favor funciona, {name}. Corre la voz; al mundo le hace falta."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "Al instante, {name}. No te muevas, o le caerá a tu sombra."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Buen viaje, {name}. {buff} pesa menos que una espada."
L["A small blessing for the road, {name}."] = "Una pequeña bendición para el camino, {name}."
L["Go well, {name}, and come back in one piece."] = "Ve con cuidado, {name}, y vuelve de una pieza."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Sin motivo, {name}. Hoy me pareció un día de {buff}."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "No me hagas caso, {name}. Solo pasaba con {buff} de sobra."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "Considéralo un regalo, {name}. Lo envolvería, pero brilla a través del papel."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Toma, {name}. Pásalo cuando encuentres a alguien que lo necesite."
L["Whatever brings you here, {name}, may it go better than planned."] = "Te traiga lo que te traiga, {name}, que salga mejor de lo previsto."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Cosas de vecinos, {name}. Vecinos muy, muy temporales."
L["You looked about to do something brave, {name}. Here, for that."] = "Tienes cara de ir a hacer algo valiente, {name}. Toma, para eso."
L["No need to stop, {name}. It works while you walk."] = "No pares, {name}. Funciona sobre la marcha."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "Nada pedido, nada debido, {name}. Ahora solo toca lucirse."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "Llámalo apuesta, {name}: apuesto a que harás algo que valga la pena."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "Regalo de alguien de paso, {name}. Los mejores, dicen los viejos cuentos."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "Es de mala educación pasar sin saludar, {name}. Este es mi saludo."
L["Same road as me, {name}? Then take this for the journey."] = "¿Vas por mi mismo camino, {name}? Pues toma esto para el viaje."
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "Si hoy te va bien, {name}, acuérdate de mí. Si va mal, nunca estuve aquí."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "No te muevas, {name}. Ya. La persona mejor preparada a la vista."
L["Everyone ready? You are now, {name}."] = "¿Todos listos? Tú ya lo estás, {name}."
L["A little something for the party, {name}."] = "Un detallito para el grupo, {name}."
L["Stay close, {name}. We go further together."] = "No te alejes, {name}. Juntos llegamos más lejos."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Normas de la casa, {name}: nadie muere, nadie refunfuña y luego, a comer."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Listo, {name}. Si esto sale mal, no será culpa mía."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Todo listo, {name}. Daría un discurso, pero sería eterno."
L["Look after that, {name}. It's the only one I brought for you."] = "Cuídalo, {name}. Es el único que traje para ti."
L["Now we look the part, {name}. Let's go and be it."] = "Ya tenemos pinta de héroes, {name}. Ahora, a serlo."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff} para todos, {name}. Lo demás es suerte y codazos."
L["If anyone has a plan, {name}, now's the time. No? Wonderful. Onward."] = "Si alguien tiene un plan, {name}, es el momento. ¿No? Estupendo. Adelante."
L["One each, {name}. Don't swap; they're fitted."] = "Uno por cabeza, {name}. No los cambies: van a medida."
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "Quien empiece el combate, {name}, se encarga de contarlo luego."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "Buenos amigos, acero afilado, {buff}. ¿Qué más hace falta, {name}?"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "Quédate donde te vea, {name}. No puedo ayudar a quien no encuentro."
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "Si esto acaba en leyenda, {name}, quiero una frase. Con una me basta."
L["Brace yourselves, {name}. And each other, if it comes to that."] = "Agárrate fuerte, {name}. Y si hace falta, agarrémonos entre todos."
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "Ánimo, {name}. Lo que nos espera todavía no conoce a este grupo."
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "Procura seguir de una pieza, {name}. Solo hago arreglos pequeños."
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "Bueno, {name}, parecemos listos. Vámonos antes de ver que no."
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "Si nos perdemos, {name}, estamos explorando. Nadie regaña a un explorador."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Gracias, {name}. Te conjuraría un regalo, pero solo me saldría agua."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Te lo agradezco, {name}. Luego lo documento como es debido. Varias páginas."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Gracias, {name}. En Dalaran no enseñan gratitud. Soy autodidacta."
L["Kind of you, {name}. Everyone assumes mages need no help. We do."] = "Muy amable, {name}. Todos creen que los magos no necesitamos ayuda. Pues sí."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "Gracias, {name}. Casi te lanzo Contrahechizo por reflejo. Menos mal que no."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "Hasta un mago de escarcha se derretiría, {name}. Gracias."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "Gracias, {name}. Anotado en mi grimorio, entre Nova de Escarcha y la comida."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "Devuelto al instante, {name}, antes de ver una librería. Así perdí semanas."
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "Veinte años en la biblioteca, {name}, y ningún libro hablaba de gente como tú."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "La teoría arcana dice que nada es gratis, {name}. Se equivocaba. Gracias."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Claro, {name}. Y sí, supongo que también querrás agua."
L["As requested, {name}. I'll find my page again later."] = "Como pediste, {name}. Luego buscaré por qué página iba."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Al momento, {name}. Ojo: hoy Traslación ya me estampó en dos muros."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "Con gusto, {name}. El saber se comparte. Lo dice el Kirin Tor, a regañadientes."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "Desde luego, {name}. Lo lanzo despacio: los aspavientos son lo mejor."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "Claro, {name}. Es como si yo te hiciera la tarea."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "Claro, {name}. Esto me lo enseñó Antonidas. También a agacharme."
L["At once, {name}. Arcane, not fire. I did check."] = "Enseguida, {name}. Arcano, no fuego. Lo comprobé."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "Desde luego, {name}. Era esto o una charla sobre líneas Ley, y fuiste amable."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "Cosas de magos, {name}: el hechizo es instantáneo; la explicación, no."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "Lo lancé mil veces, {name}. Novecientas noventa salieron bien."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "Desde luego, {name}. No te muevas. A quien se mueve, a veces le sale lana."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Toma, {name}. Me sobraba una idea y no sabía dónde ponerla."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Toma, {name}. Añadiría pan, pero el pan conjurado no sabe a nada."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} para ti, {name}. Gratis, no como los portales."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Toma, {name}. Lo que señalo suele volverse oveja. Hoy estás de suerte."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Nada en llamas, nada congelado, {name}. Me estoy diversificando."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "Para ti, {name}. Estaba practicando y tu cabeza era la más cercana."
L["Here, {name}. Freshly cast, and hardly crackling at all."] = "Toma, {name}. Recién lanzado, y apenas chisporrotea."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "Los reyes pagaban a Dalaran por esto, {name}. A ti te sale gratis."
L["Take this, {name}. It wears off, unlike my last experiment."] = "Toma, {name}. Esto se pasa, no como mi último experimento."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "Para ti, {name}: todo lo que aprendí en Dalaran, sin los exámenes."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "Toma, {name}. La magia arcana se comparte antes de que tenga ideas propias."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "La Evocación tarda siglos, {name}; gasto el maná donde importa. Toma."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "Toma, {name}. Un mago que pasa sin ayudar es un sombrero con patas."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Ahora que te sobra ingenio, {name}, ponte entre las cosas furiosas y yo."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Que conste, {name}: solo uso Traslación cuando es tácticamente correcto."
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "Luego invito yo al agua, {name}. No me la pidas en pleno combate."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Mentes afiladas, {name}. Yo me encargo del fuego, la escarcha y el pánico."
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "Ojo, {name}: si digo 'Nova de Escarcha', corre. Si digo 'corre', también."
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "Piroexplosión tarda, {name}. Si algo la interrumpe, es personal."
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "Si uso Bloque de hielo, {name}, no es el miedo. Me congelo a propósito."
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "Los portales a casa los pongo yo, {name}. Llegar con vida, entre todos."
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "Lo que no quieras combatir, {name}, señálalo. Para la merienda será lana."
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "Les soltaré una Ventisca, {name}. Puedes mirar, pero desde fuera."
L["Keep them off me, {name}, and I'll keep them on fire."] = "Mantenlos lejos de mí, {name}, y yo los mantendré en llamas."
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "Si me callo, {name}, es Evocación, no un berrinche. Normalmente."
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "Si esto sale mal, {name}, tengo teletransporte a casa. No lo usaría. Creo."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Qué detalle, {name}. La Luz lleva las cuentas; yo saldo las mías pronto."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Gracias, {name}. Hablaré bien de ti a la Luz. Me debe varias."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Gracias, {name}. Un pequeño milagro, y sin tener que rezar."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Gracias, {name}. Recupero la fe en la gente. Solo estaba descansando."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "Gracias, {name}. Esta noche rezo por ti. Entre los primeros."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "A los sanadores rara vez nos toca recibir, {name}. Olvidé lo bonito que es."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "Gracias, {name}. Me ahorraste una plegaria, y siempre me falta una."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "Gracias, {name}. Daría un sermón sobre la generosidad, pero acabas de darlo tú."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "Gracias, {name}. Te encenderé una vela. Dos. Hoy me da por derrochar."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "Hasta mi lado sombrío sonríe, {name}. No tiene cara, así que créeme."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Claro, {name}. La Luz no tiene horario, y yo, por desgracia, tampoco."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Enseguida, {name}. Casi todas las plegarias tardan más; encontraste un atajo."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Desde luego, {name}. La Luz brilla sobre quien pide. Yo solo apunto."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "Un placer, {name}. La fe mueve montañas; yo empiezo por algo más pequeño."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "Claro, {name}. Las confesiones se cobran aparte, y prefiero no oírlas."
L["Of course, {name}. Nobody who asks goes without. The Light's rule, and mine."] = "Claro, {name}. Nadie que pida se queda sin nada. Es norma de la Luz, y mía."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "Desde luego, {name}. Si brilla cálido, es la Luz. Si brilla frío, avísame ya."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "Claro, {name}. Rezaré para que dure. Tengo contactos arriba."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "Desde luego, {name}. Sano, castigo y oficio funerales. Esta es la parte alegre."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "¡Salud, {name}! No, no estornudaste: es que yo la reparto."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Toma, {name}. Es una plegaria que llegó antes de tiempo."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "La Luz me pidió que te diera esto, {name}. Estoy parafraseando."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Toma, {name}. Así nos ahorramos una resurrección incómoda luego."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "Gratis, {name}. La fe no cuesta nada. La túnica, por desgracia, sí."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "Toma, {name}. Soy como un pequeño templo ambulante. Sin escalones que subir."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "Una bendición entre extraños, {name}. La Luz dice que no existen."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "Toma, {name}. No habrá colecta después. Mira: manos vacías."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "Toma, {name}. Te predicaría, pero se ve que tienes prisa."
L["Small mercies are my speciality, {name}. Here's one."] = "Los pequeños consuelos son mi especialidad, {name}. Aquí tienes uno."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "Toma, {name}. Vendría levitando, pero en público eso junta a mucha gente."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "Te toca, {name}. Y por favor, todos: que mi trabajo sea aburrido."
L["Everyone stay near me, {name}. The Light has a limited range."] = "Que nadie se aleje de mí, {name}. La Luz tiene un alcance limitado."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Hecho, {name}. Si alguien cae, me llevaré un disgusto. Y luego lo arreglo."
L["Done, {name}. I'll be at the back, praying loudly."] = "Hecho, {name}. Estaré detrás, rezando a gritos."
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "Si grito, {name}, es un hechizo y todo huye. Por favor, tú no te unas."
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "Si uso Desvanecerse, {name}, sigo aquí. Solo dejé de ser interesante."
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "Un escudo por cabeza, {name}. Luego el alma necesita siesta. Dosifícate."
L["Let's all come back from this the usual way, {name}: walking."] = "Volvamos todos como siempre, {name}: por nuestro propio pie."
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "Yo te mantengo con vida, {name}. Tú evita que tenga que decir 'te lo dije'."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "Recé por este grupo, {name}. La Luz dijo 'suerte'. Algo es algo."
L["Thank you, {name}. I'd offer you berries, but I ate them all."] = "Gracias, {name}. Te ofrecería bayas, pero me las comí todas."
L["Thanks, {name}. Like rain in a dry season."] = "Gracias, {name}. Como lluvia en tiempo de sequía."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Te lo agradezco, {name}. Mi forma felina quiere traerte un conejo. Le dije que no."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Gracias, {name}. Plantaré un árbol en tu honor. Dale un siglo."
L["Thank you, {name}. May your road stay green and your water sweet."] = "Gracias, {name}. Que tu camino siga verde y tu agua, dulce."
L["Kindly done, {name}. I felt that right down to my roots."] = "Qué amable, {name}. Lo noté hasta las raíces."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "La naturaleza todo lo devuelve tarde o temprano, {name}. Yo, temprano."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "Piel de corteza lo para casi todo, {name}. La bondad pasó directa. Gracias."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "Gracias, {name}. En forma de oso, esto sería un abrazo. Menos mal que no."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Desde luego, {name}. Dame un momento para recordar qué forma tiene manos."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Claro, {name}. No te muevas, como un roble. Se les da de maravilla."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "Con gusto, {name}. Lo salvaje lo comparte todo. Bueno, los osos no."
L["Right away, {name}. The wild's had a good season; it can spare this."] = "Enseguida, {name}. La naturaleza tuvo una buena temporada; puede permitirse esto."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "Claro, {name}. La naturaleza no acepta encargos, pero yo sí."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "Con gusto, {name}. Pídeselo a un árbol y espera un año. A un druida, y es ya."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "Claro, {name}. El equilibrio se inclina un poco hacia ti. No se lo digas."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "Habría venido corriendo, {name}, pero de guepardo, y habrías gritado. Toma."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "Claro, {name}. Lo salvaje es amable con quien pide. Salvo los mosquitos."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Vengo del Sueño Esmeralda, {name}. Perdona si bostezo."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Toma, {name}. La naturaleza provee, y hoy yo hago sus encargos."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "Lo salvaje te acepta, {name}. Viene bien, porque casi todo tiene dientes."
L["I'd have picked you flowers, {name}, but this keeps better."] = "Te habría traído flores, {name}, pero esto dura más."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Toma, {name}. Cenarius querría que lo tuvieras. Casi seguro."
L["Here, {name}. For cold nights, sharp claws and long roads."] = "Toma, {name}. Para noches frías, garras afiladas y caminos largos."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "Toma, {name}. Lo salvaje te estuvo observando y decidió que das la talla."
L["There, {name}. Walk lightly, and the forest will walk with you."] = "Listo, {name}. Pisa con suavidad y el bosque caminará contigo."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "Para ti, {name}. Recuerdos del Claro de la Luna. No manda muchos."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "La naturaleza es cruel, bella y húmeda, {name}. Esto ayuda con dos."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "Suelo atar a desconocidos con raíces, {name}. Esta es la parte bonita."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "¿Todo a punto, {name}? Pase lo que pase, que nadie asuste al oso."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Hecho, {name}. Seré el gato, el oso o, si toca nadar, la foca."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "Solo me queda un renacimiento, {name}. Que nadie me haga elegir."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Cerremos filas, {name}. El bosque nos mira, y nos apoya de raíz."
L["I'll heal or I'll maul, {name}. Tell me which before it's urgent."] = "Curaré o despedazaré, {name}. Dime cuál antes de que sea urgente."
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "Solo tengo un Estimular, {name}. Para quien ponga más cara de apuro. Sin teatro."
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "Si me pongo a brillar y ulular, {name}, es el lechúcico. Es una forma seria."
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "Si esto se llena, {name}, invoco un Huracán. Sujeta bien el sombrero."
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "Nos movemos en manada, {name}. Una manada variada. Uno a veces es un oso."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "¿Bondad, {name}? Mi virtud favorita. Por delante de sacar brillo."
L["For that, {name}, my best blessing. Not the second best. The best."] = "Por eso, {name}, mi mejor bendición. No la segunda mejor. La mejor."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "¡Virtud recompensada al instante, {name}! Me encanta cuando pasa."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Gracias, {name}. Mi juramento dice que devuelva la bondad. Lo haría igual."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "Te juzgaré con buenos ojos, {name}. Casi todo lo juzgo con dureza. Gracias."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "Gracias, {name}. Mi aura brilla más. Le pasa cuando me tocan la fibra."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "¡Qué detalle, {name}! Lo grabaré en mi escudo, junto a las abolladuras."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "Te lo agradezco, {name}. Mi corcel también, aunque es más reservado."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "Juré proteger el bien, {name}. Acabas de encabezar la lista."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "¡Por la Luz, {name}, claro! Llevaba todo el día esperando esto."
L["You have my blessing, {name}, in every sense."] = "Tienes mi bendición, {name}, en todos los sentidos."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Desde luego, {name}. Arrodíllate si quieres. No insisto. Pero me encantaría."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "Con gusto, {name}. Nunca me faltan bendiciones. El maná, a veces."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "Claro, {name}. No te muevas. Mi puntería es recta; mis guanteletes, torpes."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "Con gusto, {name}. Ayudar es mi juramento. Brillar, un extra."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "Claro, {name}. Firme, la barbilla alta y cara de merecerlo. Eso es. La tienes."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "Claro, {name}. Casi nadie le pide ayuda a la lata de conservas. Qué ilusión."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "Claro, {name}. Un momento, que elijo la bendición. Tengo mis favoritas."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "La Luz no pide nada a cambio, {name}. Yo, en cambio, acepto las gracias."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Ve con la Luz, {name}. Iré detrás; me oirás por el clanc clanc."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "La bendición es gratis, {name}. Y te ahorro el sermón. Por esta vez."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Hecho, {name}. No dura para siempre: haz heroicidades mientras tanto."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Con la cabeza alta, {name}. La Luz camina contigo, y tiene una postura impecable."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "Toma, {name}. Te daría mi martillo, pero me tiene mucho apego."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "Las bendiciones se reparten, {name}. Acapararlas está mal visto. Por mí."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "Justicia a los malvados y bendiciones al resto, {name}. Tú eres el resto."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "Toma, {name}. Mis escrituras dicen que comparta. Dicen mucho; esto me gusta."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "La caballerosidad no murió, {name}. Lleva armadura pesada y te trajo esto."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "Llévalo con orgullo, {name}. Es pecado, pero solo en grandes dosis."
L["You're blessed, {name}. Keep behind my shield and we'll do fine."] = "Bendición dada, {name}. Quédate tras mi escudo y nos irá bien."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Aguanta firme, {name}. Tenemos la Luz, y yo tengo un martillo enorme."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Una bendición para cada uno, {name}. La Luz es generosa, pero exige turnos."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Espléndido, {name}. Que nadie me mire directamente. Hoy estoy muy brillante."
L["Stay inside my aura, {name}. It's warmer than it looks."] = "Quédate en mi aura, {name}. Abriga más de lo que parece."
L["If I stun something, {name}, hit it while it's thinking things over."] = "Si aturdo algo, {name}, pégale mientras se lo piensa."
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "El suelo que brilla es mío, {name}. Písalo sin miedo; solo les muerde a ellos."
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "Yo dicto Sentencia, {name}, y tú la ejecutas. Un tribunal muy eficiente."
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "Si grito 'por la Luz', {name}, es a la carga. O a rezar. Casi siempre, ambas."
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "Armadura pulida, martillo bendito, {name}, y mi caballo ofendido. Listos."
L["I've called on Righteous Fury, {name}. Let them come to me."] = "Invoqué la Furia recta, {name}. Que vengan a mí."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Qué amable, {name}. Mi diablillo te da las gracias. Miente; yo no."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Gracias, {name}. Hacía siglos que nadie me daba algo sin maldición."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Gracias, {name}. Te lo pagaré con algo que no saqué de una cripta."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Muy amable, {name}. Le pedí al abisario que deje de acecharte."
L["Thank you, {name}. Most folk cross the road when they see me."] = "Gracias, {name}. Casi todo el mundo se cambia de acera al verme."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "¿Sin sangre, sin pacto, sin ataduras, {name}? Qué raro negocio. Gracias."
L["Thank you, {name}. Should anything haunt you, send it my way."] = "Gracias, {name}. Si algo te atormenta, mándamelo."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "Qué detalle, {name}. Todo lo que me dan, lo devuelvo. Menos las almas. Toma."
L["Of course, {name}. No soul required. This time."] = "Claro, {name}. No te pediré el alma. Esta vez."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "¿Pedirle ayuda a un brujo, {name}? Qué valor. Ya me caes bien."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Claro, {name}. El diablillo se ofreció; le dije que no, por el bien de todos."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Desde luego, {name}. De mis hechizos, es el único apto para fiestas."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "Con gusto, {name}. Una buena obra; al Consejo de la Sombra le daría algo."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "Claro, {name}. No leas el libro que tengo en la mano. Por tu bien."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "Claro, {name}. ¿Sientes que te vigilan? Solo es el Ojo de Kilrogg. No te muevas."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "Claro, {name}. Solo maldigo a quien no pide por favor. Tú estás a salvo."
L["Yes, {name}, it's the one without screaming. Hold still."] = "Sí, {name}, es el hechizo sin gritos. No te muevas."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "Claro, {name}. ¿Vas a mojarte? No pregunto. Los brujos nunca preguntan."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Toma, {name}. No preguntes de dónde salió. En serio."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Si algún día caes en un lago, {name}, te acordarás de mí con cariño."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Respira hondo, {name}. Odiaría perderte por algo tan soso como el agua."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Toma, {name}. También querrás una piedra de alma, pero eso es otra conversación."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Toma, {name}. Es el único hechizo mío que aprueban los sacerdotes."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "Toma, {name}. Mi madre aún cree que estudio en Dalaran. Que siga creyéndolo."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "Toma, {name}. No es verde, no susurra y no te seguirá a casa."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "Toma, {name}. Magia oscura para el bien. Cuéntaselo a mi maestro; lo odiará."
L["Here, {name}. I keep the darker spells for people who've earned them."] = "Toma, {name}. Los hechizos más oscuros los guardo para quien se los ha ganado."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "Toma, {name}. No soy solo maldiciones y miedo. Casi, pero no solo."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "Mi grimorio tiene un capítulo sobre la bondad, {name}. Es corto, pero lo leí."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "¿Todos listos, {name}? ¿Almas intactas? Bien. Que siga así."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "No te alejes, {name}. El abisario se lleva los golpes; yo, el mérito."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Nada todo lo que quieras, {name}. Si alguien se pierde, lo invoco de vuelta."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Acaricia al manáfago, {name}. Pero quítate los hechizos antes."
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "Si le meto Miedo a algo, {name}, no lo persigas. Vuelve con más rabia."
L["I trade blood for mana, {name}. It looks worse than it is."] = "Cambio sangre por maná, {name}. Parece peor de lo que es."
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "Piedras de salud luego, {name}. Son para emergencias, no golosinas."
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "Aléjate cuando lance Fuego infernal, {name}. Yo también me quemo. Es lo trágico."
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "Mi diablillo arde, {name}, y es de los nuestros. Deja de echarle agua."
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "Si cae algo verde del cielo, {name}, es mío. Aplaude."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "¡Gracias, {name}! Perdón, ¿fue muy alto? Solo tengo un volumen."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Gracias, {name}. No tengo hechizos que devolver, pero grito con sinceridad."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Gracias, {name}. Ahora tengo el doble de ira. De la buena."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Gracias, {name}. Te ganaste un lugar justo detrás de mí. El más seguro que hay."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "Gracias, {name}. La bondad me ablanda. Suerte que llevo mucha armadura."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "Gracias, {name}. Mi armero también te lo agradece. Le pagué la casa."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "Gracias, {name}. Te vendaría algo, pero no tienes ni un rasguño. Qué rabia."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "Gracias, {name}. Cambié a mi actitud agradecida para esto. Casi nunca la uso."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "Me diste magia, {name}. No sé dónde guardarla. Me la pondré. Gracias."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "Deber favores me inquieta, {name}, y la inquietud me hace cargar contra cosas."
L["You want a shout, {name}? I was going to shout anyway."] = "¿Quieres un grito, {name}? Iba a gritar de todos modos."
L["Of course, {name}. A fighter who asks for courage already has some."] = "Claro, {name}. Quien pide valor ya tiene un poco."
L["Right away, {name}. Square your shoulders. There, that's half of it."] = "Enseguida, {name}. Hombros rectos. Así; ya tienes la mitad."
L["Happily, {name}! Go hit something for me."] = "¡Con gusto, {name}! Ve a pegarle a algo por mí."
L["Right, {name}. Deep breath. Not you. Me."] = "Bien, {name}. Respira hondo. Tú no. Yo."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "Con gusto, {name}. Es lo primero que me piden hoy que no sea levantar algo."
L["Coming up, {name}. Plant your feet. This one has a kick to it."] = "Marchando, {name}. Planta bien los pies. Este pega fuerte."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "Claro, {name}. Casi todos solo me piden que me calle. Qué cambio tan bonito."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "Claro, {name}. Me costó años. Años gritando a árboles, sobre todo."
L["Consider yourself shouted at, {name}. Affectionately."] = "Te acabo de gritar, {name}. Con cariño."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Sin incienso ni plegarias, {name}. Solo yo, gritando ánimos."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "¡Ánimo, {name}! Si algo te molesta, cargo contra ello."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "¡Listo, {name}! Quien no se sienta más valiente ahora, no estaba escuchando."
L["Here, {name}, some courage. Spend it freely; I've plenty more."] = "Toma, {name}, algo de valor. Gástalo sin miedo; tengo de sobra."
L["Here, {name}. Something sharper than a whetstone: morale."] = "Toma, {name}. Afila más que una piedra de afilar: la moral."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "Toma, {name}. Los guerreros no tenemos magia; nos tenemos unos a otros."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "Toma, {name}. Parece que vas a meterte en algo gordo. Métete con ganas."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "Toma, {name}. Nada de magia. Solo fe guerrera en ti, muy muy firme."
L["Take this, {name}. It's loud, it's free, and I mean it."] = "Toma, {name}. Es ruidoso, es gratis y lo digo en serio."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "Toma, {name}. Dile a lo que combatas que respondo por ti. Con el escudo."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "Este grito era para ti, {name}. El próximo, para lo que se te cruce."
L["Listen up, {name}! That's it. That was the whole speech."] = "¡Atención, {name}! Ya está. Ese era todo el discurso."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "¿Dónde está el peligro, {name}? Da igual, ya lo encuentro. De cara."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "¡Bien, {name}! Yo voy delante, yo grito más, y nadie toca al sanador."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "¿Todos con más ira? Bien. Adelante, {name}, y cuidado con mi revés."
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "Tienen que pegarme para que sirva de algo, {name}. Que nadie se asuste."
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "Las vendas están en mi bolsa, {name}. Los nudos los hice yo: son muy seguros."
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "Bien, {name}: yo me llevo los golpes, tú el mérito, y las reparaciones a medias."
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "Si enrojezco y me callo, {name}, es Ira rabiosa. Si enrojezco y grito, todo bien."
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "Mi escudo vio cosas peores, {name}. Mi cara, también. Adelante."
L["The living rarely lend me much, {name}. I'll be prompt, in case it catches on."] = "Los vivos rara vez me prestan algo, {name}. Lo devuelvo ya, por si cunde el ejemplo."
L["Thank you, {name}. I owe you one fight at your side, on a day of your choosing."] = "Gracias, {name}. Te debo una batalla a tu lado, el día que tú elijas."
L["The skulls came with the armour, {name}. The gratitude is all my own."] = "Las calaveras venían con la armadura, {name}. La gratitud es toda mía."
L["My one healing spell only mends the dead, {name}. Do stay healthy. Thank you."] = "Mi único hechizo curativo solo sana a los muertos, {name}. Cuídate mucho. Gracias."
L["Your kindness is safe with me, {name}. Very little else is. Thank you."] = "Tu bondad está a salvo conmigo, {name}. Casi nada más lo está. Gracias."
L["I've stood at the runeforge all night for less than that, {name}. Thank you."] = "Pasé noches enteras en la forja de runas por mucho menos, {name}. Gracias."
L["The Ebon Blade answers courtesy in kind, {name}, and insults with the blade."] = "La Espada de Ébano devuelve cortesía con cortesía, {name}, e insultos con la espada."
L["Tonight's watch will pass quicker for that, {name}, and I keep a great many."] = "La guardia de esta noche se me hará más corta, {name}, y hago muchísimas."
L["Thank you, {name}. Ride with me a while, if your horse will stand next to mine."] = "Gracias, {name}. Cabalga conmigo un rato, si tu caballo se atreve a ponerse junto al mío."
L["Thank you, {name}. I'll have the dead salute you. Badly, but with feeling."] = "Gracias, {name}. Haré que los muertos te saluden. Mal, pero con sentimiento."
L["Very well, {name}. Stand fast; the horn is loud, and the cold follows it."] = "Muy bien, {name}. Aguanta firme: el cuerno suena fuerte y el frío viene detrás."
L["Of course, {name}. Most of what I do is quick or final. This is the quick kind."] = "Claro, {name}. Casi todo lo que hago es rápido o definitivo. Esto es de lo rápido."
L["You have my horn and my word, {name}. One is louder; the other lasts longer."] = "Tienes mi cuerno y mi palabra, {name}. Uno suena más; la otra dura más."
L["Of course, {name}. Mind the runeblade. It doesn't know you yet."] = "Claro, {name}. Cuidado con la hojarruna. Aún no te conoce."
L["Gladly, {name}. I'd far rather sound a horn for a friend than a dirge."] = "Con gusto, {name}. Mejor tocar el cuerno por un amigo que tocar a muerto por él."
L["At once, {name}. A knight who makes an ally wait isn't worth their runes."] = "Enseguida, {name}. Un caballero que hace esperar a un aliado no vale ni sus runas."
L["Yes, {name}. Step into view; this helm was made for glaring, not for looking."] = "Sí, {name}. Ponte donde te vea: este yelmo es para fulminar con la mirada, no para ver."
L["The Ebon Blade serves the living now, {name}. Even the impatient ones."] = "La Espada de Ébano ahora sirve a los vivos, {name}. Incluso a los impacientes."
L["Of course, {name}. Pay no mind to the frost on your boots. It brushes off."] = "Claro, {name}. No te preocupes por la escarcha en las botas. Se sacude enseguida."
L["The paladins at Light's Hope ask far more stiffly, {name}. They still get it."] = "En la Capilla de la Esperanza de la Luz lo piden más estirados, {name}. Y lo reciben."
L["Hear that, {name}? Winter, on your side for once."] = "¿Oyes eso, {name}? El invierno, de tu lado por una vez."
L["The horn sounds for you, {name}. It used to sound only for the Scourge."] = "El cuerno suena por ti, {name}. Antes solo sonaba para la Plaga."
L["Advice from a death knight, {name}: never fight fair, and never fight alone."] = "Consejo de caballero de la Muerte, {name}: nunca juegues limpio ni luches sin compañía."
L["Acherus floats over the Plaguelands, {name}. It's good to come down and help."] = "Acherus flota sobre las Tierras de la Peste, {name}. Da gusto bajar a echar una mano."
L["The road's dark, {name}. I should know; I'm usually the darkest thing on it."] = "El camino está oscuro, {name}. Lo sé bien: suelo ser lo más oscuro que hay en él."
L["You looked a little short of an army, {name}. A horn is the next best thing."] = "Parecía que te faltaba un ejército, {name}. Un cuerno es lo más parecido."
L["Here, {name}. My ghoul wanted to say hello. I've spared you that."] = "Toma, {name}. Mi necrófago quería saludarte. Te ahorré el mal trago."
L["Take this, {name}. Cold, loud and well meant, like most of my order."] = "Toma, {name}. Frío, ruidoso y bienintencionado, como casi toda mi orden."
L["Whatever waits out there, {name}, I've likely killed its cousin. Take this."] = "Sea lo que sea lo que te espera, {name}, seguro que ya maté a un primo suyo. Toma."
L["Take this and keep moving, {name}. Trouble tends to follow death knights about."] = "Toma y no te detengas, {name}. Los problemas suelen seguir a los caballeros de la Muerte."
L["If I raise an army, {name}, be civil to it. They didn't ask to be here either."] = "Si levanto un ejército, {name}, sé amable con él. Ellos tampoco pidieron estar aquí."
L["Walk where I walk, {name}. The frost will hold us up over any lake."] = "Pisa donde yo piso, {name}. La escarcha nos sostendrá sobre cualquier lago."
L["If I look hurt, {name}, let me hit something. That's how death knights mend."] = "Si sangro, {name}, déjame pegarle a algo. Así sanamos los caballeros de la Muerte."
L["My ghoul goes in first, {name}. He won't mind. He's long past minding."] = "Mi necrófago entra primero, {name}. No le importa. Ya nada le importa."
L["Keep up, {name}. The dead don't tire, and I forget the living do."] = "No te rezagues, {name}. Los muertos no se cansan, y olvido que los vivos sí."
L["Don't fall, {name}. I can bring you back, but it's an unsettling way to wake."] = "No caigas, {name}. Puedo traerte de vuelta, pero es una forma inquietante de despertar."
L["Leave the fevers to me, {name}. They spread on their own. I like to supervise."] = "Deja las fiebres en mis manos, {name}. Se contagian solas. A mí me gusta supervisar."
L["The horn has sounded, {name}. Whatever heard it knows we're coming."] = "El cuerno ya sonó, {name}. Todo lo que lo oyó sabe que vamos."
L["Whatever we kill today, {name}, stays dead. I'll see to that personally."] = "Lo que matemos hoy, {name}, seguirá muerto. Me encargo yo en persona."
L["Pick a target, {name}, and I'll pick the same one. It shortens the arguments."] = "Elige un objetivo, {name}, y yo elegiré el mismo. Así discutimos menos."
L["Take a gift with both hands, my master said, {name}. And return it with both."] = "Los regalos, con las dos manos, decía mi maestro, {name}. Al recibir y al devolver."
L["Thank you, {name}. I feel light enough to run up a waterfall. I may try."] = "Gracias, {name}. Con esta ligereza subiría corriendo una cascada. Igual lo intento."
L["I meditated on generosity for years, {name}. You skipped to the end. Thank you."] = "Medité años sobre la generosidad, {name}. Tú pasaste directamente al final. Gracias."
L["I came out into the world to find good people, {name}. That's one. Thank you."] = "Salí al mundo a buscar buenas personas, {name}. Ya encontré una. Gracias."
L["The masters at the Peak of Serenity would bow to that, {name}. So do I."] = "En el Pico de la Serenidad se inclinarían ante esto, {name}. Yo también."
L["Kindly done, {name}. The next brigand who jumps me gets one kick fewer."] = "Muy amable, {name}. El próximo bandido que me asalte se llevará una patada menos."
L["A kindness is like a strike, {name}: it's all in the timing. Yours was perfect."] = "Un favor es como un golpe, {name}: todo está en el momento. El tuyo fue perfecto."
L["Thank you, {name}. These hands were trained to strike. Today they get to give."] = "Gracias, {name}. Estas manos se entrenaron para golpear. Hoy les toca dar."
L["Thank you, {name}. Answered the monk's way: no wasted motion, no wasted words."] = "Gracias, {name}. Respondo como un monje: sin gestos de más ni palabras de más."
L["Gratitude makes even a monk clumsy, {name}. Forgive the elbows. Thank you."] = "La gratitud vuelve torpe hasta a un monje, {name}. Perdona los codazos. Gracias."
L["Of course, {name}. My master took a year to teach me this. I'll take a moment."] = "Claro, {name}. Mi maestro tardó un año en enseñarme esto. Yo tardaré un momento."
L["One of the old legacies, {name}, handed down to me and now to you."] = "Un legado antiguo, {name}, que me pasaron a mí y ahora paso a ti."
L["Nothing calms the mind like being useful, {name}. You've done me a favour."] = "Nada calma la mente como ser útil, {name}. Me hiciste un favor."
L["Of course, {name}. My hands know this one by heart. I just tell them who."] = "Claro, {name}. Mis manos se lo saben de memoria. Yo solo les digo para quién."
L["At once, {name}. The fist is for foes; the open palm is for friends."] = "Enseguida, {name}. Puño para el enemigo; palma abierta para el amigo."
L["A moment, {name}. I'm mid-form, and it's bad luck to stop on the left foot."] = "Un momento, {name}. Estoy a media forma, y parar sobre el pie izquierdo da mala suerte."
L["Gladly, {name}. I was only standing still to see what it felt like."] = "Con gusto, {name}. Solo me había quedado inmóvil para ver qué se sentía."
L["At once, {name}. If you blinked, you missed it. That's fine; it's on you now."] = "Enseguida, {name}. Si parpadeaste, te lo perdiste. No pasa nada: ya lo llevas puesto."
L["Of course, {name}. It costs me a breath and a moment, and I've plenty of both."] = "Claro, {name}. Me cuesta un respiro y un instante, y me sobran ambos."
L["Of course, {name}. Ask me every day, if you like. Monks love a routine."] = "Claro, {name}. Pídemelo cada día, si quieres. A los monjes nos encanta la rutina."
L["I passed you twice on my morning run, {name}. The third time, I stopped. Here."] = "Te pasé dos veces en mi carrera matutina, {name}. A la tercera, me detuve. Toma."
L["Your stance says you've had a long day, {name}. Monks notice these things."] = "Tu postura dice que tuviste un día largo, {name}. Los monjes nos fijamos en eso."
L["A monk gives before being asked, {name}. It saves us both the bowing."] = "Un monje da antes de que se lo pidan, {name}. Así nos ahorramos las reverencias."
L["Take this, {name}. My master said one kind act before every meal. I'm hungry."] = "Toma, {name}. Mi maestro decía: una buena obra antes de cada comida. Tengo hambre."
L["Kindness is the hardest stance to hold, {name}. I'm practising. Here."] = "La bondad es la postura más difícil, {name}. La estoy practicando. Toma."
L["I practised patience by not giving you this, {name}. I lasted three heartbeats."] = "Practiqué la paciencia no dándote esto, {name}. Aguanté tres latidos."
L["Be gentle out there, {name}. Unless a hozen starts it. Then be quick."] = "Sé amable por ahí, {name}. Salvo que empiece un hozen. Entonces, actúa rápido."
L["A calm mind finds the road, {name}. This should keep you steady on it."] = "Una mente en calma encuentra el camino, {name}. Esto te mantendrá firme en él."
L["The Last Emperor left Pandaria a legacy, {name}. I'm leaving you a small one."] = "El Último Emperador le dejó un legado a Pandaria, {name}. Yo te dejo uno pequeño."
L["For you, {name}. No lesson attached. My masters would be appalled."] = "Para ti, {name}. Sin lección incluida. Mis maestros se horrorizarían."
L["Stay light on your feet, {name}. A heavy step is an easy target."] = "Mantén los pies ligeros, {name}. Un paso pesado es un blanco fácil."
L["If they surround us, {name}, I'll spin. Stand back; I'm not tidy about it."] = "Si nos rodean, {name}, me pongo a girar. Apártate: no lo hago con mucho cuidado."
L["Fight from your centre, {name}. If you can't find yours, borrow mine."] = "Lucha desde tu centro, {name}. Si no encuentras el tuyo, toma prestado el mío."
L["If one of them freezes mid-swing, {name}, that's my doing. Leave it till last."] = "Si uno se queda paralizado a mitad de golpe, {name}, es cosa mía. Déjalo para el final."
L["You go high, {name}, and I'll go low. Nobody guards both at once."] = "Tú arriba, {name}, y yo abajo. Nadie para ambos golpes a la vez."
L["Ready, {name}? Loose shoulders, soft knees, firm intentions."] = "¿Vamos, {name}? Hombros sueltos, rodillas flexibles, intención firme."
L["Any weapon I take off them, {name}, stays taken. They held it badly."] = "Las armas que les quite, {name}, no las recuperan. Las sujetaban mal."
L["Leave the runners to me, {name}. Nothing outruns a monk with a grudge."] = "Deja para mí a los que huyan, {name}. Nada escapa de un monje con rencor."
L["If I end a fight with one touch, {name}, don't ask how. It took me years."] = "Si acabo una pelea con un solo toque, {name}, no preguntes cómo. Me llevó años."
L["Mind your temper, {name}. Anger opens a door, and the Sha walk in."] = "Controla tu genio, {name}. La ira abre una puerta, y entran los sha."
L["That was well cast, {name}. I would know. Thank you."] = "Bien lanzado, {name}. Y de eso entiendo. Gracias."
L["I have studied fire, time and the Dream, {name}. You still surprised me."] = "Estudié el fuego, el tiempo y el Sueño, {name}. Aun así, me sorprendiste."
L["Dragons give big gifts slowly, {name}. Yours was small and quick. I prefer it."] = "Los dragones regalan a lo grande y despacio, {name}. Tú, a lo pequeño y rápido. Mejor."
L["I'll dip a wing to you when I next fly over, {name}. Watch for it."] = "Cuando vuelva a pasar volando, te saludaré con un ala, {name}. Fíjate."
L["I've known dragons with worse manners, {name}, and some of them were Aspects."] = "Conocí dragones con peores modales, {name}, y algunos eran Aspectos."
L["Thank you, {name}. I answer in kind, with magic older than your kingdoms."] = "Gracias, {name}. Te correspondo con magia más antigua que los reinos mortales."
L["Thank you, {name}. I'm delighted. You can tell by the faint smoke."] = "Gracias, {name}. Qué alegría. Se nota por el hilito de humo."
L["Generous, {name}, and not a trace of showing off. I must learn that part."] = "Qué generosidad, {name}, y sin una pizca de presunción. Tengo que aprender esa parte."
L["Thank you, {name}. Returned at once. My aim is perfect; my patience is not."] = "Gracias, {name}. Te lo devuelvo al instante. Mi puntería es perfecta; mi paciencia, no."
L["Thank you, {name}. I shall cite you, should I ever write a treatise on manners."] = "Gracias, {name}. Te citaré si algún día escribo un tratado de buenos modales."
L["Gladly, {name}. Help from a dragon once took a quest. Things have improved."] = "Con gusto, {name}. La ayuda de un dragón antes costaba una gesta. Hemos mejorado."
L["Hold still, {name}. Or hover, if you are able. No? Standing will do."] = "No te muevas, {name}. O flota, si puedes. ¿No? Con estar de pie basta."
L["Watch closely, {name}. My casting is said to be a joy to watch. Mostly by me."] = "Mira bien, {name}. Dicen que verme lanzar hechizos es un placer. Lo digo sobre todo yo."
L["It would be my pleasure, {name}. Truly. I don't say 'truly' lightly."] = "Será un placer, {name}. De verdad. Y no digo 'de verdad' a la ligera."
L["Of course, {name}. Magic this old ought to be spent kindly, and you qualify."] = "Claro, {name}. Una magia tan antigua merece gastarse en algo bueno, y tú das la talla."
L["Of course, {name}. Ask again tomorrow; I'll have improved it overnight."] = "Claro, {name}. Pídemelo mañana; lo habré mejorado durante la noche."
L["You need only ask, {name}. I am curious how it will look on you."] = "Basta con pedirlo, {name}. Tengo curiosidad por ver cómo te queda."
L["Certainly, {name}. Think of something calm. Not dragons."] = "Desde luego, {name}. Piensa en algo tranquilo. Nada de dragones."
L["On the Forbidden Reach we practised on rocks, {name}. You are an improvement."] = "En el Confín Olvidado practicábamos con rocas, {name}. Tú eres una mejora."
L["Of course, {name}. You're standing exactly where I'd have put you. Well done."] = "Claro, {name}. Estás justo donde te habría puesto yo. Bien hecho."
L["Take this, {name}. I meant to explain the spell first. Too late now."] = "Toma, {name}. Pensaba explicarte el hechizo antes. Ya es tarde."
L["For you, {name}. Unasked, unearned and entirely deserved. Draconic logic."] = "Para ti, {name}. Sin pedirlo, sin ganártelo y totalmente merecido. Lógica dracónica."
L["I spotted you from afar, {name}. Evokers have sharp eyes and little restraint."] = "Te vi desde lejos, {name}. Los evocadores tenemos buena vista y poca contención."
L["Evokers study for years to cast this well, {name}. You need only stand there."] = "Los evocadores estudian años para lanzar esto bien, {name}. Tú solo tienes que estar ahí."
L["You'll be glad of this soon, {name}. Don't ask how I know. Bronze business."] = "Pronto te alegrarás de esto, {name}. No preguntes cómo lo sé. Cosas del Vuelo Bronce."
L["I could be flying right now, {name}, and instead I'm helping you. Do take note."] = "Podría estar volando ahora mismo, {name}, y en cambio te ayudo a ti. Que conste."
L["Here, {name}. Old magic, new caster. We're both doing rather well."] = "Toma, {name}. Magia antigua, manos nuevas. Ambas cumplen bastante bien."
L["Not my grandest spell, {name}, but the one I'd most like to be known for."] = "No es mi hechizo más grandioso, {name}, pero es el que querría que me diera fama."
L["I have read about heroes, {name}. You look like the early chapters."] = "Leí sobre héroes, {name}. Tú pareces de los primeros capítulos."
L["Magic can't stay up in the sky, {name}. Sooner or later it lands on somebody."] = "La magia no puede quedarse en el cielo, {name}. Tarde o temprano cae sobre alguien."
L["If I seize you and fly, {name}, it is a rescue, not an abduction. Hold on."] = "Si te agarro y echo a volar, {name}, es un rescate, no un secuestro. Agárrate."
L["I fight from a little way back, {name}. Not from caution. The view is better."] = "Lucho desde un poco más atrás, {name}. No por prudencia. La vista es mejor."
L["Leave their spellcasters to me, {name}. Their technique offends me."] = "Déjame a sus hechiceros, {name}. Su técnica me ofende."
L["Hold the line, {name}. I'll be the bright thing over your shoulder."] = "Mantén la posición, {name}. Yo seré el resplandor que asoma por tu hombro."
L["Dragons fight in three dimensions, {name}. Our enemies rarely think to look up."] = "Los dragones luchan en tres dimensiones, {name}. El enemigo rara vez mira arriba."
L["I've made you all a little more than you were, {name}. The rest is up to you."] = "Hice de cada uno algo más de lo que era, {name}. El resto depende de ti."
L["If I take a long breath, {name}, do not startle me. It is still growing."] = "Si tomo aire mucho rato, {name}, no me asustes. Aún está creciendo."
L["Fight well, {name}. I am taking notes on how mortals do it. So far: loudly."] = "Lucha bien, {name}. Tomo notas de cómo luchan los mortales. Por ahora: con mucho ruido."
L["Time is on our side, {name}. I have checked with it personally."] = "El tiempo está de nuestro lado, {name}. Se lo pregunté en persona."
L["Do try to keep up, {name}. I'm not showing off. Flying is simply quicker."] = "Intenta seguirme el ritmo, {name}. No es por presumir: volar es más rápido."
L["Rain, fire and a rockslide this week, {name}. That was the first gentle thing."] = "Esta semana, lluvia, fuego y un derrumbe, {name}. Es lo primero amable que me pasa."
L["The fifth element is spirit, {name}, and yours is a generous one. Thank you."] = "El quinto elemento es el espíritu, {name}, y el tuyo es generoso. Gracias."
L["Thank you, {name}. The rain can wash everything off me today but that."] = "Gracias, {name}. Hoy la lluvia puede quitarme todo de encima, menos eso."
L["Earth is patient and fire is not, {name}. My thanks takes after fire."] = "La tierra es paciente y el fuego no, {name}. Mi gratitud sale al fuego."
L["Most days I speak for the elements, {name}. Today's thanks are my own."] = "Casi siempre hablo por los elementos, {name}. Hoy las gracias son mías."
L["Thank you, {name}. The elements answer need, not rank. So, it seems, do you."] = "Gracias, {name}. Los elementos atienden a la necesidad, no al rango. Y tú, por lo visto."
L["The Earthen Ring mends the world a crack at a time, {name}. You've mended one."] = "El Anillo de la Tierra repara el mundo grieta a grieta, {name}. Tú acabas de reparar una."
L["Water carves canyons by never giving up, {name}. I'll repay you the same way."] = "El agua talla cañones porque nunca se rinde, {name}. Te lo pagaré igual: sin rendirme."
L["Lightning is quick, {name}, but never thoughtful. You were both. Thank you."] = "El rayo es rápido, {name}, pero nunca considerado. Tú fuiste ambas cosas. Gracias."
L["Thank you, {name}. The ground felt steadier under me for that."] = "Gracias, {name}. Con esto, el suelo parece más firme bajo mis pies."
L["Of course, {name}. I'll ask the sky. It rarely says no to me."] = "Claro, {name}. Se lo pediré al cielo. Rara vez me dice que no."
L["Feet on the earth, eyes on the sky, {name}. The rest is between them and me."] = "Pies en la tierra, ojos en el cielo, {name}. El resto queda entre ellos y yo."
L["Gladly, {name}. Thunder takes a moment to arrive. I don't."] = "Con gusto, {name}. El trueno tarda un momento en llegar. Yo no."
L["Gladly, {name}. A shaman who won't share the storm has no business calling it."] = "Con gusto, {name}. Un chamán que no comparte la tormenta no tiene derecho a invocarla."
L["Of course, {name}. Lightning can be gentle. It just prefers not to be."] = "Claro, {name}. El rayo puede ser suave. Solo que prefiere no serlo."
L["Of course, {name}. Let me apologise to the wind for borrowing it. There."] = "Claro, {name}. Deja que le pida perdón al viento por tomarlo prestado. Listo."
L["Gladly, {name}. Calling the wind is easy. Steering it is the trick."] = "Con gusto, {name}. Llamar al viento es fácil. Lo difícil es guiarlo."
L["We serve the elements and they serve the world, {name}. You're in it."] = "Servimos a los elementos y ellos sirven al mundo, {name}. Y tú estás en él."
L["Gladly, {name}. Mind your hair; the air gets lively."] = "Con gusto, {name}. Ojo con el pelo: el aire se alborota."
L["Of course, {name}. You'll smell of rain for an hour. Everyone I help does."] = "Claro, {name}. Olerás a lluvia durante una hora. Le pasa a todo el que ayudo."
L["The sky has a little fury to spare, {name}. Take some."] = "Al cielo le sobra un poco de furia, {name}. Toma un poco."
L["Take this, {name}. The storm doesn't know you yet, but I've introduced you."] = "Toma, {name}. La tormenta aún no te conoce, pero ya te presenté."
L["A storm at your back for once, {name}, instead of in your face."] = "Por una vez, la tormenta a tu espalda, {name}, y no de cara."
L["Here, {name}. I don't hand storms to just anyone. You've the shoulders for it."] = "Toma, {name}. No le doy tormentas a cualquiera. Tú tienes espalda para esto."
L["Rain for the crops, storm for the fight, {name}. You look more like a fight."] = "Lluvia para las cosechas, tormenta para la pelea, {name}. Tú tienes más pinta de pelea."
L["Here, {name}. If you hear thunder later, it isn't weather. It's encouragement."] = "Toma, {name}. Si luego oyes truenos, no es el tiempo. Son ánimos."
L["From four elements and one shaman, {name}. The shaman did the walking."] = "De parte de cuatro elementos y un chamán, {name}. El que caminó fue el chamán."
L["Walk well, {name}. The earth holds up everybody, but it likes you. I asked."] = "Buen camino, {name}. La tierra sostiene a todos, pero tú le caes bien. Se lo pregunté."
L["I'd give you fair weather, {name}, but the sky only lends me the stormy kind."] = "Te daría buen tiempo, {name}, pero el cielo solo me presta el tormentoso."
L["Here, {name}. Thank the next clean stream you drink from. It's listening."] = "Toma, {name}. Dale las gracias al próximo arroyo limpio del que bebas. Te escucha."
L["If I fall, {name}, wait a moment. The spirits sometimes send me back."] = "Si caigo, {name}, espera un momento. A veces los espíritus me devuelven."
L["Earth below, sky above, {name}, and us between. Let's keep that order."] = "Tierra abajo, cielo arriba, {name}, y nosotros en medio. Que siga así."
L["If I call up an elemental, {name}, be polite. They hold grudges for an age."] = "Si invoco a un elemental, {name}, trátalo con educación. Guardan rencor durante eras."
L["Let them bunch together, {name}. Lightning loves a crowd."] = "Deja que se amontonen, {name}. Al rayo le encanta el gentío."
L["When I call the storm into your blood, {name}, you'll know it. Make it count."] = "Cuando llame a la tormenta a tu sangre, {name}, lo notarás. Aprovéchalo."
L["The wind has picked our side today, {name}. It doesn't always."] = "Hoy el viento eligió nuestro bando, {name}. No siempre lo hace."
L["The elements favour the polite, {name}. Say something nice about the rain."] = "Los elementos favorecen a quien es educado, {name}. Di algo bonito de la lluvia."
L["We're a small storm, {name}. Small storms still knock down fences."] = "Somos una tormenta pequeña, {name}. Aun así, tumbamos vallas."
L["Don't kick the totems, {name}. They have feelings. Well, the fire one does."] = "No les des patadas a los tótems, {name}. Tienen sentimientos. Bueno, el de fuego sí."
L["A river in the way, {name}? Don't go round. I'll have us walking on it."] = "¿Un río en el camino, {name}? No lo rodees. Haré que caminemos sobre él."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Una mente más aguda para ti, {name}. La mía me costó una ceja en Dalaran."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "Cabeza despejada para ti, {name}. Con qué la llenes ya es cosa tuya."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "¿Te zumban las ideas, {name}? Es normal. Si te contestan, ven a buscarme."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Un poco de arcano por tus ideas, {name}. Quédate con el cambio."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Genio embotellado, {name}. El Kirin Tor te cobraría la botella."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Más ingenio, {name}. Gástalo en hechizos, cerraduras o acertijos; no juzgo."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "Préstamo de la Ciudadela Violeta, {name}. Los retrasos se multan en ovejas."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "Ya tienes ingenio para ver la trampa, {name}. Esquivarla es otro hechizo."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Hecho, {name}. Ya se nota el ingenio: mira qué lejos de mí te pusiste."
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "Mi único hechizo que nunca incendió nada, {name}. Disfrútalo."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "Ya entiendes las instrucciones de un gnomo, {name}. Aun así, no las sigas."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Entereza, {name}: el 'ponte delante' educado de un sacerdote."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Cada punto de aguante me ahorra una plegaria desesperada, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Ya aguantas más, {name}. Por favor, no te lo tomes como un reto."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Hay otras Palabras de poder, {name}: 'escudo' y, en emergencias, 'corre'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Más resistencia, {name}. Caídas, osos y malas decisiones duelen un poco menos."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Tantas palabras para decir 'aguanta'."
L["A little more of you to go round, {name}. Spend it slowly."] = "Un poco más de ti para repartir, {name}. Gástalo con calma."
L["Harder to knock down now, {name}. The ground will miss you."] = "Ahora cuesta más tumbarte, {name}. El suelo te echará de menos."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "En el fondo es tozudez, {name}. Los enanos nacen con ella; los demás rezamos."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "La única armadura que nunca hay que reparar, {name}. Los herreros la odian."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Espíritu por las nubes, {name}. Y divino, nada menos."
L["Like a good night's sleep, {name}, without all the lying down."] = "Como dormir ocho horas, {name}, pero sin tener que acostarte."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Una ración extra de espíritu, {name}. La Luz siempre insiste en repetir."
L["Keep your spirit where it is, {name}. Loose ones wander off."] = "Mantén tu espíritu donde está, {name}. Los que van sueltos se pierden."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "Anímate, {name}. Esta vez no es un consejo: es un hechizo."
L["Recover faster, {name}, from long fights and longer walks."] = "Recupérate antes, {name}, de combates largos y caminatas aún más largas."
L["A deep breath's worth of calm, {name}, without having to take one."] = "La calma de respirar hondo, {name}, sin tener que hacerlo."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "El segundo aliento de la Luz, {name}. No lo gastes en discusiones."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "Contra las sombras, {name}. Conozco sus trucos: tomé algunos prestados."
L["Should the Void call, {name}, you can now pretend you're out."] = "Si llama el Vacío, {name}, ahora puedes decir que no estás."
L["For when the dark gets personal, {name}. It usually does."] = "Para cuando la oscuridad se ensañe, {name}. Suele pasar."
L["The shadows will have to knock first now, {name}."] = "Las sombras tendrán que llamar antes, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "La oscuridad muerde, {name}, pero ahora tiene que masticar."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "Un forro contra la oscuridad, {name}. Como una capa, pero por dentro."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "Las maldiciones ya te resbalan, {name}. Los cultistas se van a ofender."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "Estudiamos las Sombras para defendernos, {name}. Casi siempre."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "Para criptas, cultos y Scholomance, {name}. Ahí la oscuridad habla por los codos."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "Contra las penas no sirve, {name}. Para eso, compañía. Aquí estoy."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Lo salvaje te marcó, {name}. Los ciervos te saludarán con la cornamenta."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "Puede que huelas un poco a musgo, {name}. Así sabes que funciona."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Marca de lo Salvaje, {name}. Los lobos morderán igual, pero con culpa."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "El sello de aprobación de lo salvaje, {name}. Se consultó a las ardillas."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Ahora llevas algo salvaje dentro, {name}. Resiste las ganas de aullar."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Piel, garra y abrigo, {name}. Lo salvaje viaja ligero, pero completo."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "Cenarius firma cada una de estas, {name}. Bueno, un árbol firma por él."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "La armadura del propio bosque, {name}. No chirría y huele a lluvia."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "Piel más dura en segundos, {name}. Los robles tardaron siglos y están furiosos."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "Es un préstamo de lo salvaje, {name}. Intenta no devolverlo mordisqueado."
L["Anything that bites you now gets a mouthful, {name}."] = "Quien te muerda se llevará un bocado de espinas, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Que cargue el jabalí, {name}. Se irá con remordimientos y astillas."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Como una rosa, {name}: bonita de ver, mala de agarrar."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Espinas, {name}. Las cultivé yo, así que trátalas con educación."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "Un seto para llevar puesto, {name}. Bien podado: aquí hay modales."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "La naturaleza nunca pone la otra mejilla, {name}. Le saca pinchos."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "Los raptores aprenden lento, {name}. Esto les enseña mordisco a mordisco."
L["Prickly on the outside, {name}. What's inside is your own business."] = "Espinas por fuera, {name}. Lo de dentro ya es cosa tuya."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "Ojo con la capa, {name}. La lana y las zarzas nunca se llevaron bien."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Bendición de reyes, {name}. Sin corona, sin trono y sin impuestos."
L["Long may you reign, {name}. For the next while, anyway."] = "Larga vida a tu reinado, {name}. Al menos durante un rato."
L["A little more of everything, {name}. Kings never did settle for less."] = "Un poco más de todo, {name}. Los reyes nunca se conformaron con menos."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Bendición de rey, {name}. La lucieron cabezas mejores que la mía, y peores."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Todo un poco más alto, {name}. Los reyes nunca apuestan a una sola carta."
L["Crown not included, {name}. Everything else is, a little."] = "Corona no incluida, {name}. Lo demás sí, un poquito."
L["All of you, only more so, {name}. Wear it well."] = "Tú, pero a lo grande, {name}. Llévalo con orgullo."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "Bendición digna de reyes, {name}. Saludar a la multitud es cosa tuya."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "Más fuerza, ingenio y aguante, {name}. Los reyes tenían consejeros; tú, a mí."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "Trato de la realeza, {name}, sin cortesanos ni vino envenenado."
L["Might doesn't make right, {name}, but it does help the argument."] = "El poderío no da la razón, {name}, pero ayuda a discutir."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Golpes más firmes para ti, {name}. La Luz adora un buen remate."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Brazos más fuertes, {name}. Apúntalos, por favor, a algo que se lo merezca."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Bendición de poderío, {name}. Te sorprenderá. A ellos, mucho más."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Tú dale, {name}. Si sale bien, la Luz se llevará el mérito."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Pega más fuerte, {name}. A ellos, digo. A mí no. Al paladín, nunca."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "Más peso en cada golpe, {name}. La Luz lo llama convicción."
L["Doors, crates and ogres will all give way easier now, {name}."] = "Puertas, cajas y ogros cederán más fácilmente ahora, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "Sentirás el arma más ligera, {name}. No lo es. Es que ahora llevas más Luz."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "Músculo bendito de la Luz, {name}. Úsalo para algo útil."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "Sabiduría para ti, {name}. Me guardé un poco. Muy poquito."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "Sabiduría para tu maná, {name}. La otra se sigue sacando de las malas decisiones."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Tu maná vuelve solo, {name}, como un gato que ya te perdonó."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Menos sorbos entre combates, {name}. Los posaderos quedarán destrozados."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Bebe menos y lanza más, {name}. Consejo de ahorro de la Luz."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Bendición de sabiduría, {name}: la única que se paga sola."
L["A steadier well to draw from, {name}. Draw deep."] = "Un pozo más constante del que beber, {name}. Bebe a fondo."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "La sabiduría suele venir con la edad, {name}. Esta, con un paladín. Más rápido."
L["May you know when to fight and when to sit down, {name}."] = "Que sepas cuándo luchar y cuándo sentarte, {name}."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "Bendición sabia para una decisión sabia, {name}: tener un paladín cerca."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Bendición de calma, {name}. Los monstruos olvidarán quién fue."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Bendición de salvación, {name}. Ahora eres problema de otro."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "Salvación, {name}. Del alma no, ojo. Del pellejo."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Pega fuerte, {name}. Si algo se gira, pon cara de inocente. La Luz lo hará."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "Para los monstruos ahora eres olvidable, {name}. Hoy, eso es un cumplido."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "Dale, {name}, pégale. Le echará la culpa a quien lleve más placas."
L["The art of being in the fight, {name}, and out of the argument."] = "El arte de estar en el combate, {name}, y no en la bronca."
L["The Light's kindest alibi, {name}. Use it often."] = "La coartada más amable de la Luz, {name}. Úsala mucho."
L["The Light will find you easier now, {name}. Try not to squint."] = "Ahora la Luz te ve mejor, {name}. No entrecierres los ojos."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "Luz Sagrada te cura más ahora, {name}. Por favor, no me obligues a demostrarlo."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Sanarás mejor, {name}. La Luz agradece a los pacientes dóciles."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Bendición de Luz, {name}. Salvarte será más fácil. No es que haga falta."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "La Luz ya sabe llegar hasta ti, {name}. Que sus visitas sean solo de cortesía."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "Una bendición que me facilita el trabajo, {name}. Generosidad y pereza a la vez."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "Luz Sagrada te sienta mejor ahora, {name}, como un tabardo a medida."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "Curarte ya sale más barato, {name}. No es que fuera a cobrarte."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Bloquea un golpe, {name}, y la Luz lo devuelve por ti. Es algo rencorosa."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Ahora cada golpe te llega más suave, {name}. Las quejas, a la Luz."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Todo el cobijo de un templo, {name}, y sin arreglar goteras."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Pide santuario, {name}. Es más fácil si lo traes de casa."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "Cada golpe es un poco menos grosero, {name}. La Luz enseña modales."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "Nadie puede desalojarte de este santuario, {name}. Revisé las escrituras."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "El garrote de un ogro ya es una almohada, {name}. Pesada y con mal genio."
L["Instructions, {name}: hit things harder. There is no page two."] = "Instrucciones, {name}: pega más fuerte. No hay página dos."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "Brazo de la espada, listo, {name}. Para lo demás, un sacerdote."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Grito de batalla, {name}. No es un hechizo. Es una sugerencia muy enérgica."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "¡RAAAGH! Ese era para ti, {name}. Los demás solo lo oyeron de rebote."
L["Priests pray, mages study, {name}. I clear my throat."] = "Los sacerdotes rezan, los magos estudian, {name}. Yo carraspeo."
L["Words matter, {name}. Mostly the loud ones."] = "Las palabras importan, {name}. Las gritadas, más."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "El grito dura unos minutos, {name}. El pitido en los oídos, bastante más."
L["There were words in that shout once, {name}. They slowed it down."] = "Antes ese grito tenía palabras, {name}. Lo hacían más lento."
L["A little breath from the damned, {name}. They weren't using it."] = "Un poco de aliento de los condenados, {name}. No lo estaban usando."
L["Unending Breath, {name}. The fish will have so many questions."] = "Aliento inagotable, {name}. Los peces tendrán muchas preguntas."
L["Stay down as long as you like, {name}. The air's on me."] = "Quédate abajo lo que quieras, {name}. El aire corre de mi cuenta."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Bucea hondo, {name}. Si un múrloc pregunta, estás de visita."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "Aire de un lugar donde el aire no es exactamente aire, {name}. Respíralo igual."
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "El Arrecife Vil te espera, {name}. Mejor no averigües por qué se llama así."
L["Dropped something in a lake, {name}? Now's your chance."] = "¿Se te cayó algo a un lago, {name}? Esta es tu oportunidad."
L["No gills, {name}. I read the small print; gills were extra."] = "Sin branquias, {name}. Lo pone la letra pequeña: se pagan aparte."
L["An order, {name}: stay standing. Your bones heard it, even if you didn't."] = "Una orden, {name}: sigue en pie. Tus huesos la oyeron, aunque tú no."
L["Grit is a habit, {name}. I've lent you a few years of mine."] = "El aguante es costumbre, {name}. Te presté unos años del mío."
L["I command, you endure, {name}. The shortest chain of command in any army."] = "Yo ordeno, tú aguantas, {name}. La cadena de mando más corta de cualquier ejército."
L["Officers give orders from the back, {name}. Mine come from the front, loudly."] = "Los oficiales dan órdenes desde atrás, {name}. Las mías llegan desde delante, y a gritos."
L["A good shout can hold a line together, {name}. A line of one is easy."] = "Un buen grito puede mantener unida una línea, {name}. Una línea de uno es fácil."
L["I learned this drilling recruits, {name}. They hated me, and they all lived."] = "Aprendí esto instruyendo reclutas, {name}. Me odiaban, y todos sobrevivieron."
L["One shout's for hitting, {name}. This one's for being hit and not minding."] = "Un grito es para golpear, {name}. Este es para recibir golpes sin que te importe."
L["Most fights go to whoever lasts longest, {name}. Today, that's you."] = "Casi todas las peleas las gana quien más aguanta, {name}. Hoy, eres tú."
L["This horn once sounded for a worse master, {name}. It much prefers you."] = "Este cuerno sonó una vez para un amo peor, {name}. Te prefiere con diferencia."
L["I can't runeforge your weapon, {name}, but the horn comes close."] = "No puedo grabarle runas a tu arma, {name}, pero el cuerno se le acerca."
L["All Northrend's cold in a single note, {name}. Swing while it's still ringing."] = "Todo el frío de Rasganorte en una sola nota, {name}. Golpea mientras resuena."
L["I'd play something cheerful, {name}, but this horn only knows the one note."] = "Tocaría algo alegre, {name}, pero este cuerno solo se sabe una nota."
L["Winter took me once, {name}. Now it comes when I call."] = "El invierno me llevó, {name}. Ahora acude cuando lo llamo."
L["The Ebon Blade charges when this sounds, {name}. Today you charge with us."] = "Cuando esto suena, la Espada de Ébano carga, {name}. Hoy cargas con nosotros."
L["Cold enough to wake the dead, {name}. I would know."] = "Un frío que despierta muertos, {name}. Doy fe."
L["No warm words from me, {name}. Cold ones carry further."] = "Nada de palabras cálidas, {name}. Las frías llegan más lejos."
L["Shaohao cast out his doubt and fear, {name}. What he kept, I pass to you."] = "Shaohao se libró de su duda y su miedo, {name}. Lo que conservó, te lo paso a ti."
L["Shoulders down and jaw loose, {name}. Now it can settle in properly."] = "Hombros abajo y mandíbula suelta, {name}. Ahora sí puede asentarse bien."
L["An open palm for friends, {name}. The fist is kept for everyone else."] = "La mano abierta, para los amigos, {name}. El puño queda para los demás."
L["I swept temple steps for a year to learn this, {name}. The steps stayed dusty."] = "Barrí las escaleras del templo un año para aprender esto, {name}. Siguieron con polvo."
L["Strength, grace and a clear head, {name}. Pandaria's emperors had all three."] = "Fuerza, gracia y mente clara, {name}. Los emperadores de Pandaria tenían las tres."
L["A gift from a land that hid in the mists, {name}. Use it out in the open."] = "Un regalo de una tierra oculta entre las brumas, {name}. Úsalo a cielo abierto."
L["Harmony is hard to find, {name}. Hold on to this bit of it."] = "Cuesta encontrar la armonía, {name}. No sueltes este pedacito."
L["Nothing in it you didn't have already, {name}. I've only woken it up."] = "No hay nada aquí que no tuvieras ya, {name}. Solo lo desperté."
L["Strength is better shown than talked about, {name}. So I'll say no more."] = "La fuerza se demuestra, no se cuenta, {name}. Así que no digo más."
L["Strike where the guard is thin, {name}. The Tiger's eyes will show you where."] = "Golpea donde la guardia flaquea, {name}. Los ojos del Tigre te mostrarán dónde."
L["Xuen never strikes by halves, {name}. Now neither do you."] = "Xuen nunca golpea a medias, {name}. Y ahora tú tampoco."
L["You don't get the stripes, {name}. Only the nerve that goes with them."] = "Las rayas no vienen incluidas, {name}. Solo el temple que las acompaña."
L["I trained in Kun-Lai's snow for this, {name}. Your feet stay warm, at least."] = "Entrené para esto en la nieve de la Cima Kun-Lai, {name}. Tus pies no pasarán frío."
L["The Tiger's blessing isn't gentle, {name}, but it's on your side."] = "La bendición del Tigre no es delicada, {name}, pero está de tu lado."
L["Fierce, not angry, {name}. Xuen taught me the difference. Now it's yours."] = "Fiereza, no ira, {name}. Xuen me enseñó la diferencia. Ahora es tuya."
L["Wait, watch, then pounce, {name}. Tigers rarely need a second try."] = "Espera, observa y salta, {name}. Al tigre rara vez le hace falta repetir."
L["Dark Intent, {name}. A grim name for a kind act. Warlocks name things badly."] = "Propósito oscuro, {name}. Nombre siniestro, gesto amable. Los brujos no sabemos bautizar."
L["Thank the demon who taught me this, {name}. On second thoughts, don't."] = "Dale las gracias al demonio que me lo enseñó, {name}. Mejor dicho, no."
L["You'll feel no different, {name}. Your enemies will. That's rather the point."] = "No notarás ninguna diferencia, {name}. Tus enemigos, sí. De eso se trata."
L["A little fel, well filtered, {name}. You'll barely smell the sulphur."] = "Un poco de energía vil, bien filtrada, {name}. Apenas olerás el azufre."
L["A spark of the Nether rides with you now, {name}. I've trained it to sit."] = "Una chispa del Vacío Abisal va contigo, {name}. Le enseñé a sentarse."
L["Don't feel guilty about the power, {name}. I've done the guilty part already."] = "No te sientas culpable por el poder, {name}. La parte de la culpa ya la puse yo."
L["Darkness suits you, {name}. I mean that kindly."] = "La oscuridad te sienta bien, {name}. Lo digo con cariño."
L["I'd wish you luck, {name}, but warlocks prefer to arrange it."] = "Te desearía suerte, {name}, pero los brujos preferimos amañarla."
L["The sky lends you its temper, {name}. Strike once, and the storm follows it in."] = "El cielo te presta su genio, {name}. Golpea una vez, y la tormenta entra detrás."
L["The earth keeps you steady, {name}. Now the sky wants a turn."] = "La tierra te mantiene firme, {name}. Ahora el cielo quiere su turno."
L["The storm rides with you now, {name}. Do warn it before you go indoors."] = "Ahora la tormenta viaja contigo, {name}. Avísale antes de entrar bajo techo."
L["If your hair stands on end, {name}, that's the storm agreeing with me."] = "Si se te eriza el pelo, {name}, es la tormenta dándome la razón."
L["I asked the sky to stand behind you, {name}. It's very tall and easily annoyed."] = "Le pedí al cielo que te cubra las espaldas, {name}. Es muy alto y de mal genio."
L["Lightning never strikes twice, they say, {name}. They've never met a shaman."] = "Dicen que un rayo nunca cae dos veces, {name}. No conocen a ningún chamán."
L["I listen to the wind, {name}. Today it only wanted to talk about you."] = "Escucho al viento, {name}. Hoy solo quería hablar de ti."
L["Thunder in your arms, {name}. Let the next fool who blocks your way hear it."] = "El trueno en tus brazos, {name}. Que lo oiga el próximo necio que se te cruce."
L["A few borrowed moments from the bronze, {name}. Nozdormu keeps careful count."] = "Unos instantes prestados por el Vuelo Bronce, {name}. Nozdormu lleva bien la cuenta."
L["Time won't wait for you, {name}, but for the next while it'll dawdle."] = "El tiempo no te esperará, {name}, pero durante un rato irá sin prisa."
L["Not all help arrives in time, {name}. This kind brings its own."] = "No toda ayuda llega a tiempo, {name}. Esta trae su propio tiempo."
L["Should you need to slip away, {name}, time will cover for you."] = "Si necesitas escabullirte, {name}, el tiempo te cubrirá."
L["Bronze magic, {name}. You'll arrive a breath before you're needed."] = "Magia bronce, {name}. Llegarás un suspiro antes de que te necesiten."
L["Time is a river, {name}. I've found you a quicker current."] = "El tiempo es un río, {name}. Te encontré una corriente más rápida."
L["Time heals all wounds, {name}. I'd rather it helped you dodge them."] = "El tiempo cura las heridas, {name}. Prefiero que te ayude a esquivarlas."
L["The bronze say I learned this tomorrow, {name}. I've stopped arguing with them."] = "Los dragones bronce dicen que esto lo aprendí mañana, {name}. Ya no discuto con ellos."
L["My spare magic is yours now, {name}. Every spell I overcharge spills your way."] = "Mi magia sobrante ahora es tuya, {name}. Cada hechizo que sobrecargo se derrama hacia ti."
L["Only one of you gets this, {name}. I chose. Try to look modest about it."] = "Esto solo puede llevarlo una persona, {name}. Elegí yo. Disimula el orgullo."
L["I'd give you my patience as well, {name}, but I've barely enough for me."] = "También te daría mi paciencia, {name}, pero apenas me alcanza para mí."
L["We're linked for the hour, {name}. Don't worry, it only runs one way."] = "Quedamos unidos una hora, {name}. Tranquilidad: solo fluye en un sentido."
L["I've seen how hard you work, {name}. Let me carry a little of it."] = "Vi lo mucho que trabajas, {name}. Déjame cargar con un poco."
L["My magic runs hot, {name}. By the time it reaches you, it's cooled nicely."] = "Mi magia sale muy caliente, {name}. Cuando te llega, ya se templó."
L["Cast freely, {name}. Your mana is partly my concern now."] = "Lanza sin miedo, {name}. Tu maná ahora también es asunto mío."
L["If you run dry, {name}, it means I've been idle. Do say so."] = "Si te falta maná, {name}, es que me dormí en los laureles. Avísame."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "Van a pensar que nos batimos en duelo, {name}. Gracias por {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} por {buff}. Sin comisión de subasta, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "¡Te me adelantaste, {name}! {gift} llegó antes que mis modales."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Entra {gift}, sale {buff}. La mejor economía de Azeroth."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "¿{gift} para mí? Solo tengo esto, {name}, pero es de corazón."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "Tu {gift} me sienta de maravilla, {name}. ¿Me tomaste medidas?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Un tratado mágico, {name}: {gift} por {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "¡{gift}! Ya me siento crecer. Toma, un poco de {buff}."
L["I was about to ask for {gift}, {name}. You read my mind."] = "Iba a pedirte {gift}, {name}. Me leíste la mente."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "Tu {gift} aún chisporrotea, {name}. Van chispas de vuelta."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "Qué {gift} tan amable, {name}. Lo contaré en la posada. Dos veces."
L["You cast {gift} first, {name}? My mother would despair of me."] = "¿Tú primero con {gift}, {name}? Mi madre se llevaría las manos a la cabeza."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "Recordaré tu {gift} con cariño, {name}. Hasta que se acabe."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} por {buff}, gratis. Algún goblin está llorando."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "Tu {gift}, mi {buff}. Ahora vamos a ser insoportables."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Gracias por {gift}, {name}. Haré méritos antes de que se acabe."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "Por {gift} te daría las dos lunas, {name}. Conténtate con esto."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Tú trajiste {gift}, yo traigo {buff}. Esto ya es una fiesta."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift} significa 'buena suerte'. {buff}, 'igualmente'."
L["Your {gift} came first; my {buff} tries twice as hard."] = "Tu {gift} llegó primero; mi {buff} se esfuerza el doble."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "Si preguntan, {buff} fue antes que {gift}. ¿Trato?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} me alegró el día; {buff} debería alegrarte la hora."
L["Saved my {buff} for someone worthy. Then came {gift}."] = "Guardaba mi {buff} para alguien digno. Y llegó {gift}."
L["Your {gift} went to my head; my {buff} goes to yours."] = "Tu {gift} se me subió a la cabeza; mi {buff}, a la tuya."
L["{gift} on me, {buff} on you. We wear each other's work."] = "{gift} en mí, {buff} en ti. Cada uno luce el trabajo del otro."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift} y {buff} pasan. La bondad queda. Bueno, algo más."
L["You shared {gift}; I share {buff}. Ale's next."] = "Compartiste {gift}; yo comparto {buff}. Luego, cerveza."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} me encontró con las manos vacías. Ya no: {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}, lo mejor del día. {buff} aspira al segundo puesto."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift} merece una estatua. No sé esculpir, así que: {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "¿{gift} por {buff}? Como sigamos así, se formará una cola."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift} fue un detalle. {buff} es otro, y va a superarlo."
L["{gift} came like good news. {buff}, by return post."] = "{gift} fue una buena noticia. {buff}, a vuelta de correo."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, te presento a {buff}. A ver si se llevan bien."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "¿Te cambio {buff} por {gift}? Ah, ya pagaste."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift} y {buff}. En la posada dirán que lo ensayamos."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "¡{gift}! Se me ocurrieron tres ideas geniales, {name}. Esta es una."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "Con {gift}, {name}, por fin entiendo mis propios apuntes. Gracias."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Ya pienso mejor, {name}. Lo bastante para saber que te debo una. Toma."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "Tu {gift} me dio la palabra justa, {name}: 'gracias'."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "¡{gift}! Entendí un contrato goblin, {name}. Qué espanto."
L["Thank you, {name}. My thoughts are lining up politely."] = "Gracias, {name}. Mis pensamientos se ponen en fila, muy educados."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "Usaré tu {gift} para algo más que discutir, {name}. Seguramente."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "Gracias, {name}. Mi próximo hechizo tendrá tres sílabas más, por presumir."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "¿{gift}, {name}? Por una vez me pondré delante. Un ratito."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Rodillas, codos y orgullo, {name}: todo reforzado. Gracias."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Pégame ahora, {name}. Bueno, mejor no. Pero gracias: lo aguantaría."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "Casi indestructible, {name}. Mejor no probemos el 'casi'. Gracias."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "¡{gift}! Mi sanador te debe una carta, {name}. Yo te debo esto."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "Cada chichón que hoy me ahorro, {name}, se lo debo a tu {gift}."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "Ahora podría perder una discusión con un ogro y sobrevivir, {name}. Gracias."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "Gracias, {name}. Me siento como una muralla. Una muy agradecida."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "Gracias, {name}. Al próximo jabalí que me embista le espera una tarde larga."
L["{gift}! I feel ten years younger, {name}. Thank you."] = "¡{gift}! Me siento diez años más joven, {name}. Gracias."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Tengo el doble de calma y la mitad de mal humor, {name}. Gracias."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "Tu {gift} casi me hace cantar, {name}. Mejor toma esto: duele menos."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "¿{gift}, {name}? Ya perdoné a tres personas. Gracias."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "Estaba en las últimas, {name}. Tu {gift} fue sopa caliente y lumbre."
L["I've stopped counting mana between fights, {name}. Thank you."] = "Ya no cuento el maná entre combates, {name}. Gracias."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "Espíritu recargado, {name}, y el resto de mí también lo agradece."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "A prueba de sombras gracias a ti, {name}. Los susurros, furiosos."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Ya no entra nada oscuro, {name}. Aquí va algo luminoso en sentido contrario."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "¡{gift}! Que Colmillo Oscuro se guarde su oscuridad, {name}. Gracias."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "La próxima Descarga de las Sombras se llevará un chasco, {name}. Gracias."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "Con tu {gift} esta noche cruzo el Bosque del Ocaso, {name}. O mañana."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "¡{gift}! Una ardilla me saludó, {name}. Aquí tienes lo tuyo."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Piel más dura, sentidos más finos, {name}. Qué ganas de buscar bayas."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Me noto salvaje y con brotes, {name}. Gracias. Perdona si suelto corteza."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "Piel más dura con tu {gift}, {name}. Para flechas y para insultos."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "¡{gift}! Un pájaro intentó anidar en mí, {name}. Gracias, creo."
L["Thanks for the {gift}, {name}. The woods feel like home now."] = "Gracias por tu {gift}, {name}. Ahora el bosque me parece mi hogar."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "Gracias, {name}. Me dan ganas de quedarme bajo la lluvia a crecer. Resistiré."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "Todas las zarzas de Los Baldíos se lo pensarán dos veces, {name}. Gracias."
L["Thank you, {name}. Rain, cold and wolves: let them all try."] = "Gracias, {name}. Lluvia, frío y lobos: que lo intenten."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "¡{gift}, {name}! Hoy nadie me va a abrazar. Toma esto a cambio."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "Ahora pincho gracias a ti, {name}. Más de lo normal, digo."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "¡Tu {gift}, {name}! A ver si ahora un kóbold me quita la vela."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "¡{gift}! Ahora soy un matorral con opiniones, {name}. Gracias."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "Gracias, {name}. Lo próximo que me muerda necesitará un momento para reflexionar."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "¿{gift} de tu parte, {name}? Intentaré no fundar una dinastía."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Un poco mejor en todo, {name}. ¿Así se sienten los reyes? Ahora lo entiendo."
L["Your {gift}! My first decree, {name}: thank you."] = "¡Tu {gift}! Mi primer decreto, {name}: gracias."
L["{gift} on a commoner, {name}? I'll try to look regal."] = "¿{gift} para la plebe, {name}? Intentaré tener porte regio."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "Con tu {gift} gobernaría un reino pequeño, {name}. Los Páramos de Poniente."
L["Thank you, {name}. Every bit of me is grateful, and they rarely agree."] = "Gracias, {name}. Cada parte de mí te lo agradece, y rara vez se ponen de acuerdo."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Brazos más fuertes, {name}. Intentaré no abrazar a nadie. Gracias."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "Con {gift} podría levantar un kodo, {name}. No lo haré, pero gracias."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "Con tu {gift} mis brazos se lo tienen creído, {name}. Gracias."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "¡{gift}! Abrí un frasco que se me resistía desde Tuercespina, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "Gracias, {name}. Mi próximo golpe va dedicado a ti. La abolladura también."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} de tu parte, {name}, y mi primer acto sabio es este."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Ya tengo más sabiduría, {name}. La suficiente para reconocer un buen gesto."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "Mi maná te agradece {gift}, {name}. Es el tímido de la familia."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "Tu {gift} me rellena más rápido de lo que gasto, {name}. Casi."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "Tu {gift}, {name}: maná de vuelta y ganas de dar consejos."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "¡{gift}! Los monstruos ya me olvidaron, {name}. Yo a ti, no."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Ya nada quiere pelear conmigo, {name}. Es precioso. Gracias."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "¡{gift}! Hace rato que nada me mira mal, {name}. Gracias."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "¡{gift}! Ratón en festín de dragón, {name}: nadie me ve y como bien."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "Gracias a {gift}, en combate soy solo un rumor, {name}."
L["The Light finds me easier now, {name}. I'll try to deserve it."] = "La Luz me encuentra mejor, {name}. Intentaré merecerlo."
L["Easier to heal now, {name}. Whoever patches me up thanks you too."] = "Ahora me curan más fácil, {name}. Quien me remiende también te lo agradece."
L["With your {gift}, {name}, mending feels like coming home."] = "Con tu {gift}, {name}, sanar es como volver a casa."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "¡{gift}! La Luz y yo ya nos tuteamos, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "Con {gift} la Luz me oye antes, {name}. No hace falta gritar."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "Ahora los golpes duelen menos, {name}. Mis chichones y yo te lo agradecemos."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Cada golpe, más suave gracias a ti, {name}. Me aseguraré de que lo noten."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "Tu {gift} amortigua cada golpe, {name}. Me tapizaste."
L["{gift}! Now the Light takes every hit personally, {name}."] = "¡{gift}! Ahora la Luz se toma cada golpe a pecho, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "Con tu {gift} soy mitad fortaleza, mitad capilla, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "Me gritaste, {name}, y nunca había tenido tanto ánimo. Toma."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "Me zumban los oídos, {name}, y mis brazos, el doble de fuertes. ¡Gracias!"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "¡{gift}, {name}! Lo noté en los dientes. Para bien."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "Respondo a tu {gift} en voz baja, {name}. Alguien debe."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "Con tu {gift} casi cargo contra una pared, {name}. Toma, con calma."
L["All Azeroth heard your {gift}, {name}. Thank you for my share."] = "Todo Azeroth oyó tu {gift}, {name}. Gracias por mi parte."
L["That shout put iron in my spine, {name}. Thank you."] = "Ese grito me templó como el hierro, {name}. Gracias."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "No entendí las palabras, {name}, pero mis brazos sí. ¡Gracias!"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "Gracias, {name}. Pegaré el doble de fuerte a lo próximo y te echaré la culpa."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "¡Puedo respirar bajo el agua, {name}! Quizá nunca lo necesite, pero gracias."
L["Lungs like a murloc, thanks to you, {name}. I'll try not to gurgle."] = "Pulmones de múrloc gracias a ti, {name}. Intentaré no hacer gárgaras."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "Con {gift} saquearé todo barco hundido, {name}. Mitad para ti."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "No preguntaré de dónde saca el aire {gift}, {name}. Solo: gracias."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "Con {gift} cruzaré el lago Lordamere, {name}. Por debajo."
L["If I fall, {name}, I'll be back to thank you properly."] = "Si caigo, {name}, volveré para darte las gracias como es debido."
L["A spare life in my pocket, {name}. I'll try not to spend it. Thank you."] = "Una vida de repuesto en el bolsillo, {name}. Intentaré no gastarla. Gracias."
L["Thank you, {name}. Death can knock now; I've a key to the back door."] = "Gracias, {name}. Que llame la muerte; tengo llave de la puerta de atrás."
L["Dying's only a delay with your {gift}, {name}. Thank you."] = "Con tu {gift}, morir es solo un retraso, {name}. Gracias."
L["Thank you, {name}. If the worst happens, I'll get up and say it twice."] = "Gracias, {name}. Si pasa lo peor, me levantaré y te lo diré dos veces."
L["Let the next thing roar at me, {name}. I'm not running this time. Thank you."] = "Que lo próximo me ruja, {name}. Esta vez no salgo corriendo. Gracias."
L["{gift}! One fright, already dealt with, {name}. Thank you."] = "¡{gift}! Un susto ya resuelto, {name}. Gracias."
L["Thank you, {name}. The next scream I hear won't be mine."] = "Gracias, {name}. El próximo grito que oiga no será mío."
L["No running in circles for me, {name}. Not the first time, anyway. Thank you."] = "Nada de correr en círculos, {name}. Al menos no la primera vez. Gracias."
L["Brave on credit, thanks to you, {name}. I'll spend it wisely."] = "Valor a crédito, gracias a ti, {name}. Lo gastaré con cabeza."
L["Thank you, {name}. Lakes, rivers, puddles: all floors now."] = "Gracias, {name}. Lagos, ríos, charcos: ahora todo es suelo."
L["{gift}! The short way across it is, {name}. Dry boots and all."] = "¡{gift}! Pues por el camino corto, {name}. Con las botas secas."
L["Walking on water, {name}. Folk will start a religion. Thank you."] = "Caminar sobre el agua, {name}. Alguien fundará una religión. Gracias."
L["The murlocs will be furious, {name}. Thank you for the shortcut."] = "Los múrlocs van a estar furiosos, {name}. Gracias por el atajo."
L["Thank you, {name}. I'll be across before it fades. Probably."] = "Gracias, {name}. Llegaré al otro lado antes de que se pase. Seguramente."
L["{gift}! Whatever hid round here, {name}, hides no more."] = "¡{gift}! Lo que se escondía por aquí, {name}, ya no se esconde."
L["I can see what's hiding now, {name}. Some of it should stay hidden. Thanks."] = "Ahora veo lo que se esconde, {name}. Algunas cosas deberían seguir ocultas. Gracias."
L["Thank you, {name}. Every lurker around just lost their only trick."] = "Gracias, {name}. Todos los que acechan acaban de perder su único truco."
L["Thank you, {name}. Now I can see what your imp gets up to."] = "Gracias, {name}. Ahora veo lo que trama tu diablillo."
L["My eyes see more than my wits can handle, {name}. Thank you."] = "Mis ojos ven más de lo que mi cabeza aguanta, {name}. Gracias."
L["I'll be the last one standing, {name}, just to hear you shout again."] = "Seré quien quede en pie al final, {name}, solo para oírte gritar otra vez."
L["You ordered me to live, {name}. I mean to follow it to the letter. Thanks."] = "Me ordenaste vivir, {name}. Pienso cumplirlo al pie de la letra. Gracias."
L["Thank you, {name}. Every sinew I have just closed ranks."] = "Gracias, {name}. Todos mis tendones acaban de cerrar filas."
L["Never been shouted into good health before, {name}. Thank you."] = "Nunca me habían devuelto la salud a gritos, {name}. Gracias."
L["Yes, Sergeant {name}! Your shout brings out the recruit in me. Thank you."] = "¡Sí, mi sargento {name}! Tu grito despierta al recluta que llevo dentro. Gracias."
L["{gift}! That voice could turn a stampede, {name}. Thanks."] = "¡{gift}! Esa voz podría desviar una estampida, {name}. Gracias."
L["That horn froze my breath and fired my arms, {name}. Thank you."] = "Ese cuerno me heló el aliento y me encendió los brazos, {name}. Gracias."
L["Most folk hear that horn from the wrong end of a battle, {name}. Thank you."] = "Casi todos oyen ese cuerno desde el bando equivocado, {name}. Gracias."
L["I heard your horn and swung harder, {name}. Nobody had to tell me twice."] = "Oí tu cuerno y golpeé más fuerte, {name}. No hizo falta decírmelo dos veces."
L["Thank you, {name}. I'll be humming that note for the rest of the day."] = "Gracias, {name}. Voy a tararear esa nota el resto del día."
L["Thanks to you, {name}, I'll never grumble about winter again."] = "Gracias a ti, {name}, nunca volveré a quejarme del invierno."
L["{gift}! I won't ask what the horn's made of, {name}. Thank you."] = "¡{gift}! No preguntaré de qué está hecho el cuerno, {name}. Gracias."
L["An emperor's legacy, {name}. I'll try to leave it no worse than I found it."] = "El legado de un emperador, {name}. Intentaré no estropearlo."
L["Like a month of training before breakfast, {name}. Thank you."] = "Como un mes de entrenamiento antes del desayuno, {name}. Gracias."
L["Thank you, {name}. I feel calm enough to brew tea in a thunderstorm."] = "Gracias, {name}. Tengo tanta calma que podría preparar té en plena tormenta."
L["Thank you, {name}. I bowed without thinking. Is that part of it?"] = "Gracias, {name}. Me incliné sin pensarlo. ¿Viene incluido?"
L["{gift}! Pandaria's finest, {name}. Don't tell the brewmasters."] = "¡{gift}! Lo mejor de Pandaria, {name}. Que no se enteren los cerveceros."
L["Stronger, quicker and steadier at once, {name}. My teachers never managed that."] = "Más fuerza, más rapidez y más aplomo a la vez, {name}. Mis maestros nunca lo lograron."
L["{gift}, {name}! Even my mistakes will look deliberate now."] = "¡{gift}, {name}! Ahora hasta mis errores parecerán intencionados."
L["I feel a tiger pacing in my chest, {name}. It wants to hunt. Thank you."] = "Siento un tigre dando vueltas en mi pecho, {name}. Quiere cazar. Gracias."
L["Thank you, {name}. I'll be very polite to cats from now on."] = "Gracias, {name}. Desde hoy trataré a los gatos con mucho respeto."
L["I could out-stare a tiger now, {name}. Not Xuen. A small one."] = "Ahora sostendría la mirada a un tigre, {name}. A Xuen no; a uno pequeño."
L["Every strike I throw now has claws in it, {name}. Thank you."] = "Ahora cada golpe que lanzo lleva garras, {name}. Gracias."
L["I'd thank Xuen as well, {name}, but he answers thanks with a sparring match."] = "También daría las gracias a Xuen, {name}, pero él las contesta con un combate."
L["{gift}! I feel sharper and slightly sinister, {name}. Thanks."] = "¡{gift}! Mente más afilada y un aire algo siniestro, {name}. Gracias."
L["Dark but generous, {name}, like a good stout. Thank you."] = "Oscuro pero generoso, {name}, como una buena cerveza negra. Gracias."
L["Thank you, {name}. If I start cackling in a fight, you'll know why."] = "Gracias, {name}. Si en combate me oyes reír con malicia, sabrás por qué."
L["Bound to a warlock for the hour, {name}. My family would faint. Thank you."] = "Una hora de pacto con un brujo, {name}. Mi familia se desmayaría. Gracias."
L["Like borrowing a sharp knife from a stranger in an alley, {name}. Thanks."] = "Como si un extraño me prestara un cuchillo afilado en un callejón, {name}. Gracias."
L["More dangerous today and worse sleep tonight, {name}. A fair trade. Thanks."] = "Más peligro hoy y peor sueño esta noche, {name}. Un trato justo. Gracias."
L["Thank you, {name}. Now I know why shamans always look so windswept."] = "Gracias, {name}. Ya sé por qué los chamanes van siempre tan despeinados."
L["{gift}! Swift as the wind, {name}, and as hard to argue with."] = "¡{gift}! Veloz como el viento, {name}, y tan difícil de rebatir."
L["Your {gift} has me crackling, {name}. Shake hands carefully."] = "Tu {gift} me tiene echando chispas, {name}. Dame la mano con cuidado."
L["My weapon keeps hitting things twice, {name}. Thank you, and thank the storm."] = "Mi arma no para de golpear dos veces, {name}. Gracias a ti, y a la tormenta."
L["The sky's on my side now, {name}. I'll try not to stand on any hilltops."] = "Ahora el cielo está de mi lado, {name}. Intentaré no subirme a ninguna colina."
L["I'm half thunderstorm now, {name}. Thank you, and sorry about the rain."] = "Ahora soy media tormenta, {name}. Gracias, y perdón por la lluvia."
L["{gift}! A step ahead of everything, {name}, myself included."] = "¡{gift}! Un paso por delante de todo, {name}, incluso de mí."
L["Thank you, {name}. I'll be out of trouble before trouble notices."] = "Gracias, {name}. Saldré de los líos antes de que los líos se den cuenta."
L["Thank you, {name}. I can feel the sands shifting in my favour."] = "Gracias, {name}. Siento que las arenas se mueven a mi favor."
L["Thank you, {name}. Even my running away will look dignified now."] = "Gracias, {name}. Ahora hasta mis huidas parecerán dignas."
L["Haven't I thanked you already, {name}? Time's gone odd. Thanks again."] = "¿No te di ya las gracias, {name}? El tiempo anda raro. Gracias otra vez."
L["Thank you, {name}. Nozdormu won't miss the moments; he has all of them."] = "Gracias, {name}. Nozdormu no echará de menos esos instantes; los tiene todos."
L["Thank you, {name}. Your magic and mine get on surprisingly well."] = "Gracias, {name}. Tu magia y la mía se llevan sorprendentemente bien."
L["Of everyone here, {name}, you chose me? I'm flattered and refreshed."] = "¿Entre todos los presentes, {name}, me elegiste a mí? Me halagas y me reanimas."
L["{gift}! I'll be the last one here to run dry, {name}. Thank you."] = "¡{gift}! Seré quien más tarde en quedarse sin maná, {name}. Gracias."
L["I could cast till sundown now, {name}. Please keep breathing fire."] = "Ya puedo lanzar hechizos hasta el ocaso, {name}. Tú sigue echando fuego."
L["Thank you, {name}. Everyone I help today owes you a little too."] = "Gracias, {name}. Todos a los que ayude hoy también te deben un poco."
L["Your leftovers beat my best, {name}. Most humbling. Thank you."] = "Tus sobras superan lo mejor de mí, {name}. Toda una lección. Gracias."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Tenemos que dejar de vernos así, {name}. Bueno, no, qué va."
L["Again, {name}? Splendid. I've been practising since last time."] = "¿Otra vez, {name}? Espléndido. Practiqué desde la última vez."
L["You again, {name}? People will start saying we're friends."] = "¿Tú otra vez, {name}? La gente dirá que somos uña y carne."
L["Same face, same spell, {name}. I do love a tradition."] = "Misma cara, mismo hechizo, {name}. Adoro las tradiciones."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "¿Otra ronda, {name}? Llevo el marcador, y vamos ganando tú y yo."
L["Ah, {name}! My favourite repeat customer."] = "¡Ah, {name}! Mi cliente más fiel."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Siempre nos cruzamos, {name}. El camino me está lanzando indirectas."
L["Once more, {name}. Do stop me if you've heard this one."] = "Otra vez, {name}. Si esta ya te la sabes, me paras."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "Te guardé un poco, {name}, por si volvías. Buen instinto el mío."
L["Back already, {name}? The day's improving."] = "¿Ya de vuelta, {name}? El día mejora."
L["Again, {name}? At this rate I'll have to learn your middle name."] = "¿Otra vez, {name}? A este paso me aprenderé hasta tus apellidos."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "Una vez es amabilidad; dos, costumbre, {name}. Y yo nunca rompo una costumbre."
L["An encore, {name}, for my most faithful audience."] = "Un bis, {name}, para mi público más fiel."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "Una más de estas, {name}, y habrá que firmar una cédula de hermandad."
L["I'll remember your face now, {name}, and I'm terrible with faces."] = "Ahora recordaré tu cara, {name}, y eso que con las caras soy un desastre."
L["Us again, {name}. The world must be running out of other people."] = "Tú y yo otra vez, {name}. Al mundo se le acaba la gente."
L["Last time went so well, {name}, I've changed nothing."] = "La última vez salió tan bien, {name}, que no cambié nada."
L["Good to see someone I know, {name}. They're rarer than you'd think."] = "Qué bien ver una cara conocida, {name}. Escasean más de lo que crees."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "Ah, eres tú, {name}. Menos mal. Odio darle esto a desconocidos."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, a estas alturas, compartamos bolsa de componentes."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "¿Mañana a la misma hora, {name}? Yo traigo {buff}. Tú te traes a ti."
L["I've lost count, {name}, and I've decided that's a compliment."] = "Perdí la cuenta, {name}, y decidí que eso es un cumplido."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Si seguimos así, {name}, los bardos nos escribirán una canción muy aburrida."
L["I could do this one in my sleep by now, {name}. I may have."] = "Ya podría hacerlo en sueños, {name}. Puede que lo haya hecho."
L["The usual, {name}? Of course the usual."] = "¿Lo de siempre, {name}? Claro, lo de siempre."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Ya deberíamos tener un saludo secreto, {name}. Quizá la próxima vez."
L["By now, {name}, I think we've built a small economy between us."] = "A estas alturas, {name}, tú y yo ya somos una pequeña economía."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "Amistad de toda la vida, {name}. Bueno, de un rato, pero muy bien sincronizada."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Que conste en acta: {name} y yo, imbatibles en preparación."
L["My spellbook opens to your page on its own now, {name}."] = "Mi libro de hechizos ya se abre solo por tu página, {name}."
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "Si dejaras de venir, {name}, denunciaría tu desaparición a la guardia."
L["We keep this up, {name}, and one of us owes the other a drink."] = "Si seguimos así, {name}, uno de los dos le deberá una copa al otro."
L["We're a local landmark now, {name}. Travellers give directions by us."] = "Ya somos parte del paisaje, {name}. Los viajeros nos usan de referencia."
L["Regular as the tides, {name}, and twice as welcome."] = "Como las mareas, {name}, siempre vuelves. Y se agradece el doble."
L["I'd trust you with my last potion, {name}. That's saying something."] = "Te confiaría mi última poción, {name}. Y eso es mucho decir."
L["Next time, {name}, we share a fire and you tell me where you're bound."] = "La próxima vez, {name}, compartimos hoguera y me cuentas adónde vas."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "Si esto acabara, lo echaría de menos, {name}. No paremos."
L["There's nobody I'd rather keep running into, {name}."] = "No hay nadie con quien prefiera seguir cruzándome, {name}."
L["You always turn up at the right moment, {name}."] = "Siempre apareces en el momento justo, {name}."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Murallas, camas calientes y ahora {buff}. Qué vida de lujo, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Hay guardias, {name}, pero toda precaución es poca."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Cuidado, {name}. Con esa pinta de capaz, en la ciudad te pedirán favores."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "Ni un monstruo a la redonda, {name}. Pero con la comida de aquí, nunca se sabe."
L["For the crowds, {name}. In town, they're the real danger."] = "Por el gentío, {name}. En la ciudad, el peligro de verdad."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Descansa, {name}. Buena obra del día hecha; me voy a tomar algo."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Hasta en la ciudad, {name}, alguna vez aterrizó un dragón. Más vale prevenir."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Mejor aquí dentro, {name}. Ahí fuera nadie se está quieto lo suficiente."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "Cuidado con los carteristas, {name}. Esto es lo único que no te pueden robar."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "Ley de la ciudad, {name}: ni armas en mano ni hechizos. Este sí se permite."
L["Nothing to fight here but stray cats, {name}. Take this anyway."] = "Aquí no hay más enemigos que los gatos callejeros, {name}. Toma igualmente."
L["For the walk to the bank, {name}. It's always further than it looks."] = "Para ir al banco, {name}. Siempre está más lejos de lo que parece."
L["Enjoy a warm hearth while you can, {name}. The road's never far."] = "Disfruta del calor del hogar mientras puedas, {name}. El camino nunca está lejos."
L["The watch has the walls, {name}. I'll see to you."] = "La guardia vigila las murallas, {name}. Yo me ocupo de ti."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "Para las escaleras, {name}. Quien construyó esto no conocía los atajos."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "Todo en la ciudad tiene precio, {name}. Esto se les escapó a los mercaderes."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "No le compres nada a quien te jure amistad, {name}. Salvo a mí."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Aquí fuera todo quiere comerte, {name}. Ahora necesitará un tenedor más grande."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Ni un guardia a la redonda, {name}, y los jabalíes lo saben. Toma."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Aquí solo estamos nosotros y la fauna, {name}. Seamos la mitad más dura."
L["If a bear asks, {name}, you were like this when I found you."] = "Si un oso pregunta, {name}, ya estabas así cuando te encontré."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "Los lobos te echaron el ojo, {name}. Con esto se lo pensarán."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Tierras salvajes, {name}. Mejor no enfrentarlas solo con buenas intenciones."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Mapa, cantimplora, {buff}. Ya puedes perderte bien, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "El campamento queda lejos, {name}. Considera esto un techo portátil."
L["Out past the last farm, {name}, you're on your own. Nearly."] = "Pasada la última granja, {name}, vas por tu cuenta. Casi."
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "La posada está a un día de camino, {name}. Lo que tiene dientes, más cerca."
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "Dos colinas y un pantano hasta el próximo pueblo, {name}. El pantano opina."
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "Acampa con cuidado, {name}. Cada claro bonito tiene dueño, y con garras."
L["Fresh air, open sky, {name}. Enjoy it while nothing's chasing you."] = "Aire fresco, cielo abierto, {name}. Disfrútalo mientras nada te persiga."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "Algo te sigue, {name}. Seguramente un jabalí. Esto es por si no lo es."
L["Stay on the road, {name}. The road has guards. Some of the time."] = "No te salgas del camino, {name}. El camino tiene guardias. A ratos."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "Viene lluvia, {name}, y vienen lobos. Paraguas no tengo; esto sí."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Aquí dentro un villano ensaya su discurso, {name}. Vamos a interrumpirlo."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Lo que nos espere al final, {name}, que se arrepienta."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "Dicen que nadie sale vivo de aquí, {name}. Seamos maleducados y desmintámoslo."
L["Our host had years to prepare, {name}. We have {buff}."] = "El jefe tuvo años para prepararse, {name}. Nosotros, {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Ninguna mazmorra tiene puerta trasera, {name}. Toma esto a cambio."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Salas oscuras, trampas viejas, peor genio. Al menos tú vas a punto, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Mejor darte esto ahora, {name}, que un elogio fúnebre después."
L["There's treasure in here, {name}, and something very large sat on it."] = "Aquí hay un tesoro, {name}, y algo enorme sentado encima."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "Si una puerta se cierra de golpe tras nosotros, {name}, es tradición. Toma."
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "Ojo con las patrullas, {name}. Siempre la misma ronda, y ya están hartas."
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "Quien construyó esto, {name}, gastó todo en calaveras y ni un cobre en lámparas."
L["The last lot through here were never seen again, {name}. They lacked this."] = "A los últimos que entraron no se les volvió a ver, {name}. No llevaban esto."
L["Check the ceiling, {name}. In places like this, something always drops in."] = "Mira arriba, {name}. En sitios como este, siempre cae alguien de visita."
L["If we meet a talking skull, {name}, let me do the talking."] = "Si una calavera se pone a hablar, {name}, hablo yo."
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "Aquí las paredes oyen, {name}. Si además susurran, no contestes: se crecen."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "No toques lo que brilla, no tires de lo que hace clic, {name}. Ponte esto."
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "Juntos aquí dentro, {name}. El eco llega lejos, y el rencor, más."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Banderas, torres, cementerios, {name}. Sea por lo que sea, toma esto."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Ganes o pierdas, {name}, nadie dirá que entraste sin prepararte."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "El cementerio está ahí mismo, {name}. Mejor no lo visitemos."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "Está en juego el honor, {name}. Y la bandera. Sobre todo la bandera."
L["Stay with the group, {name}. Lone heroes make short songs."] = "Quédate con el grupo, {name}. Los héroes solitarios tienen canciones cortas."
L["Our banner looks better with you under it, {name}. Stand tall."] = "Nuestro estandarte luce más contigo debajo, {name}. Frente alta."
L["Keep your head down and your colours up, {name}."] = "La cabeza gacha y los colores en alto, {name}."
L["Hold the line, {name}. The songs are always about the ones who stood."] = "Aguanta, {name}. Nadie le canta a quien sale corriendo."
L["Come back in one piece, {name}. That's all I ask."] = "Vuelve de una pieza, {name}. Es lo único que pido."
L["Drums are for courage, {name}. This is for everything else."] = "Los tambores dan valor, {name}. Esto, todo lo demás."
L["Some fight for glory, {name}. I fight for whoever's beside me."] = "Hay quien lucha por la gloria, {name}. Yo lucho por quien tengo al lado."
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "Lucha por el estandarte, {name}, y vuelve para cantar. Yo canto fatal."
L["Early bird, {name}? Here's something better than a worm."] = "¿Madrugando, {name}? A quien madruga, yo le ayudo."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Buenos días, {name}. Considera esto tu primera taza de algo bien cargado."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Qué temprano, {name}. El día aún no tuvo tiempo de torcerse."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Ni siquiera es la hora de comer, {name}, y ya te preparaste mejor que yo."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "Buenos días, {name}. En algún lugar, los monstruos aún bostezan."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Día nuevo y {buff} de estreno, {name}. No desperdiciemos ninguno."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "¿En pie con el sol, {name}? Te luces. Toma; al sol no le doy."
L["Rise and shine, {name}. The shining can wait till after breakfast."] = "¡Arriba, {name}! Lo de brillar, después del desayuno."
L["Everything's golden and nobody's shouted yet, {name}. Let's enjoy it."] = "Todo está dorado y nadie gritó todavía, {name}. Disfrutémoslo."
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "¿Temprano para hazañas, {name}? Qué va. Las mejores se hacen en ayunas."
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "Los pájaros cantan, {name}. Aún no vieron lo que hay ahí fuera."
L["First good deed of the day, {name}. It's all downhill from here."] = "Primera buena obra del día, {name}. De aquí en adelante, todo cuesta abajo."
L["Still yawning, {name}? This works faster than tea."] = "¿Aún bostezas, {name}? Esto despeja más que un café."
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "Madrugamos, {name}. La patrulla del alba cree que nos falta un tornillo."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "¿Por ahí a estas horas, {name}? La noche tiene más hambre que el día. Toma."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Hora de dormir, {name}. La gente sensata duerme; quedamos tú y yo."
L["Can't sleep either, {name}? Then we may as well be useful."] = "¿Tampoco puedes dormir, {name}? Pues al menos seamos útiles."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Cuidado con la oscuridad, {name}. No todo ahí fuera es tan amable como yo."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "Es tarde, {name}. Con esto aguantarás hasta que el sol se acuerde de nosotros."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Solo velamos tú, yo y los búhos, {name}. Y los búhos, sin {buff}."
L["The inns have locked up, {name}. This is the only thing still being served."] = "Las posadas cerraron, {name}. Solo se sirve esto, e invita la casa."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "Hora de historias de fantasmas, {name}. Toma, por si alguna es verdad."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "Velas bajas, estrellas altas, {name}. Hora de pequeños detalles."
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "Todo en calma, {name}. Cada crujido suena a emboscada. Casi ninguno lo es."
L["This late, {name}, even the guards are talking to themselves."] = "A estas horas, {name}, hasta los guardias hablan solos."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "Es la hora en que las cosas salen de sus tumbas, {name}. Toma, y aprieta el paso."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "Mañana te preguntarás por qué trasnochaste, {name}. Aquí va un buen motivo."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Hay que ser del gremio para verlo, {name}. Y para hacerlo bien."
L["From one of our trade to another, {name}. No need to check my work."] = "De profesional a profesional, {name}. No hace falta revisarlo."
L["Professional courtesy, {name}. We don't charge each other."] = "Cortesía profesional, {name}. Entre colegas no nos cobramos."
L["Two of a kind, {name}. Between us we could write the manual."] = "Tal para cual, {name}. Entre tú y yo podríamos escribir el manual."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "¿Sorpresa, {name}? Seguro que tuvimos el mismo instructor."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Criticaría tu técnica, {name}, pero la mía es idéntica."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "No se lo digas a los demás, {name}, pero la nuestra es la mejor vocación."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Míranos, {name}: dos profesionales haciendo que parezca fácil. No lo es, ¿eh?"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "Entre colegas, {name}: yo tampoco sé cómo funciona la mitad de esto."
L["We walked the same road to get here, {name}. Good to meet another on it."] = "Recorrimos el mismo camino hasta aquí, {name}. Da gusto cruzarse con otro."
L["If anyone asks, {name}, we trained each other."] = "Si preguntan, {name}, nos entrenamos mutuamente."
L["Calling to calling, {name}. We should compare notes some time."] = "De vocación a vocación, {name}: algún día compararemos apuntes."
L["Colleague, {name}. We look after our own."] = "Colega, {name}. Cuidamos de los nuestros."
L["Good to see the old craft in steady hands, {name}."] = "Da gusto ver el viejo oficio en manos firmes, {name}."
L["I'd shout some encouragement, {name}, but you do that far better."] = "Te gritaría ánimos, {name}, pero eso tú lo haces mucho mejor."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Carga como siempre, {name}. Ahora, al menos, lo veré con más calma."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Para quien entra primero, {name}. Alguien tiene que hacerlo, y nunca soy yo."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Te llevas los golpes por los demás, {name}. Es lo mínimo que puedo hacer."
L["Go on, {name}, charge. I'll be right behind you."] = "Vamos, {name}, a la carga. Voy justo detrás."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "Para quien lo arregla todo a golpes, {name}. Y casi siempre funciona."
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "Te daría la mano, {name}, pero tienes las dos ocupadas con algo afilado."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "Una ayudita para tanta armadura, {name}. Ojalá quepa ahí debajo."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "Pronto cargarás contra algo enorme, {name}. Yo solo ayudo a que pierda."
L["Save your Light for later, {name}. This one's from me."] = "Guárdate tu Luz para luego, {name}. Esto va de mi parte."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Te pasas el día bendiciendo a todos, {name}. Aquí va una en sentido contrario."
L["The Light already favours you, {name}. Here's a little more of it."] = "La Luz ya te favorece, {name}. Aquí tienes un poco más."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Hasta quien lucha por la Luz necesita ayuda a veces, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Te pediría una bendición, {name}, pero no acabaríamos nunca."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "Para quien carga con un martillo y una conciencia, {name}. Menuda carga."
L["Don't thank the Light for this one, {name}. This was me."] = "Esto no se lo agradezcas a la Luz, {name}. Fui yo."
L["No need to kneel, {name}. I know it's a habit."] = "No te arrodilles, {name}. Ya sé: la costumbre."
L["One for you, {name}, and a pat on the head for your companion."] = "Esto para ti, {name}, y una caricia para tu mascota."
L["You watch everyone's back from range, {name}. I've got yours."] = "Cubres a todos desde lejos, {name}. Yo te cubro a ti."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Marca del cazador para ellos, {buff} para ti, {name}. Mucho mejor."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Apunta bien, {name}. Y si aun así te embiste, corre hacia nosotros."
L["Keen eye, steady hand, {name}. Here's something for the long hunt."] = "Vista aguda, pulso firme, {name}. Aquí tienes algo para la larga cacería."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "Nada para la mascota esta vez, {name}. Ya se comió tres de mis sándwiches."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "Te habría traído flechas, {name}, pero nunca sé cuáles te gustan."
L["You can track anything, {name}, but you never saw this one coming."] = "Rastreas lo que sea, {name}, pero esto no lo viste venir."
L["Quick hands, quiet feet, {name}. Here's luck to go with them."] = "Manos rápidas, pies sigilosos, {name}. Y suerte para acompañarlos."
L["Quick, {name}, before you vanish again."] = "Rápido, {name}, antes de que te esfumes."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Veneno en las hojas y {buff} en ti. No se te escapa nada, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Te lo metería en el bolsillo, {name}, pero lo notarías. Siempre lo notas."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Para quien abre todas las cajas cerradas, {name}. Esta viene abierta."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "Nadie te ve venir, {name}. Ahora, cuando te vean, será aún peor noticia."
L["Take this, {name}. Very discreet. It even walks quietly."] = "Toma, {name}. Muy discreto. Hasta camina de puntillas."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "Te lo envolvería, {name}, pero le meterías ganzúa al nudo."
L["Keep this one, {name}. You don't even have to steal it."] = "Quédatelo, {name}. Ni siquiera tienes que robarlo."
L["For once, {name}, somebody's looking after the priest."] = "Por una vez, {name}, alguien cuida de quien cura."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Guarda tus plegarias para los demás, {name}. Esta ya está respondida."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Luz o Sombra, {name}, no pregunto. Esto sirve para las dos."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "Siéntate tras este combate, {name}. Es una orden de tus pacientes."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Nos mantienes en pie a todos, {name}. Aquí te devuelvo un poco."
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "Te arrodillaste por todos, {name}. Ponte en pie un rato."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "Algo sin plegaria de por medio, {name}. Hoy ya rezaste bastante."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "Esto no viene con ninguna voz en tu cabeza, {name}. Qué alivio, ¿verdad?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "La Espada de Ébano no pide favores, {name}. Yo te hago uno igual."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Un poco de calor, {name}. Sé que no sientes el frío. Es el detalle."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Volviste de entre los muertos, {name}. Lo mínimo es ayudarte a no volver allí."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Runas, peste y escarcha, {name}. Toma esto también; completa la colección."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "Un caballo esquelético y una espada respondona, {name}. Toma algo normal."
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "No me arrastres con cadenas, {name}. Ya iba para allá."
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "De vuelta al mundo de los vivos, {name}. Bueno, a sus afueras."
L["The elements look after you, {name}, but they don't make house calls."] = "Los elementos te cuidan, {name}, pero no hacen visitas a domicilio."
L["Tell the spirits I said hello, {name}. They never write back."] = "Saluda a los espíritus de mi parte, {name}. Nunca me contestan."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Planta un tótem en mi honor, {name}. Uno pequeñito. Soy humilde."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Tierra, fuego, agua, aire y yo, {name}. Lo reconozco: yo soy lo de menos."
L["Totems up already, {name}? Then this goes with them."] = "¿Ya pusiste los tótems, {name}? Pues esto los acompaña."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "El viento te lo habría traído, {name}, pero es muy veleta. Yo soy de fiar."
L["You speak for the land, {name}. I hope it speaks kindly of me."] = "Tú hablas por la tierra, {name}. Ojalá ella hable bien de mí."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "Según los espíritus, te lo ganaste, {name}. No pregunté; se ofrecieron."
L["A gift for a mage, {name}. Hard to find one you can't conjure."] = "Un regalo para quien hace magia, {name}. Lo difícil es que no puedas conjurarlo."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Casi todo lo arreglas con ovejas, {name}. Esto cubre el resto."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Podrías teletransportarte fuera de cualquier lío, {name}. Esto es para antes."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Para la mente brillante, {name}. No me lo agradezcas volviéndome oveja."
L["Blink wherever you like, {name}. This comes too."] = "Trasládate adonde quieras, {name}. Esto va contigo."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "Apártate un poco del fuego que estás por desatar, {name}. Toma."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "Nos das agua y comida a todos, {name}. Ahora te toca que te cuiden."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "Los portales salen caros, {name}. Tómalo como adelanto por el próximo."
L["Entirely demon-free, {name}. I checked."] = "Sin demonios, {name}. Lo comprobé."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Puede que tu diablillo tenga celos, {name}. Dile que hay para todos."
L["No contract, no fine print, {name}. Just a gift."] = "Sin contrato ni letra pequeña, {name}. Solo un regalo."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Para quien reparte piedras de salud, {name}. Nadie te da nunca las gracias."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Toma, {name}. Luego nos invocas a los demás y estamos en paz."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "Tu abisario puede dejar de acecharme, {name}. Vengo en paz."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "Tu manáfago come magia, {name}. Que no toque esto; es para ti."
L["For the one who reads what nobody else dares, {name}."] = "Para quien lee lo que nadie más se atreve, {name}."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "¿Todo el día cargando almas, {name}? Tus hombros lo piden."
L["Roll wherever you like, {name}. This rolls with you."] = "Rueda adonde quieras, {name}. Esto rueda contigo."
L["Brew first or fight first, {name}? Either way, take this."] = "¿Primero cerveza o pelea, {name}? Sea como sea, toma."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "Paz interior para ti, {name}, y exterior también, mientras dure esto."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "El chi fluye mejor con un poco de ayuda, {name}. O eso me dijo un monje."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Patada, voltereta, rueda, {name}. Yo me quedo aquí y hago esta parte."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "Enséñame a dar volteretas sin tirar la cerveza, {name}, y en paz."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "Té, meditación y esto, {name}. Los tres pilares de un buen día."
L["Tell the bear this is for them too, {name}."] = "Dile al oso que esto también es para él, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "No te muevas, {name}. Nunca consigo alcanzarte cuando eres guepardo."
L["Nature looks after you already, {name}. Today she sent me to help."] = "La naturaleza ya te cuida, {name}. Hoy me mandó a echar una mano."
L["Whatever shape you're in next, {name}, this goes with you."] = "Tengas la forma que tengas después, {name}, esto va contigo."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Para quien cuida del bosque, {name}. Saluda a los árboles."
L["Cenarion work is never done, {name}. Here's a little help."] = "La labor del Círculo Cenarion no acaba nunca, {name}. Una ayudita."
L["I'd give it to the cat, {name}, but the cat would pretend not to care."] = "Se lo daría al gato, {name}, pero el gato fingiría que le da igual."
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "Saluda a tu lechúcico de mi parte, {name}. Siempre pone cara de susto."
L["You were not prepared, {name}. Now you are."] = "Nadie estaba preparado, {name}. Ahora tú sí."
L["Years in a Warden's cell, {name}. You've earned a small kindness."] = "Años en una celda de las Celadoras, {name}. Te mereces un pequeño detalle."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Diste tanto por luchar contra la Legión, {name}. Aquí te devuelvo algo."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Para quien salta primero, {name}. Intenta aterrizar en terreno amigo."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Energía vil y furia, {name}, y ahora un poco de bondad. Ya se compensará."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "Te preguntaría si lo viste venir, {name}, pero lo ves todo. Sin mirar."
L["You can see souls, {name}. Mine's the one being generous."] = "Tú ves las almas, {name}. La generosa es la mía."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "Illidan nunca dejó que nadie lo ayudara, {name}. Tú superas al maestro."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "Un demonio dentro, la Legión fuera, {name}, y esto de tu lado."
L["For you, {name}. Please don't breathe on it."] = "Para ti, {name}. Y no le eches el aliento."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Una ayudita para un dragón, {name}. Se lo contaré a mis nietos."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Los Aspectos te enviaron al mundo, {name}. Yo lo hago un poco más amable."
L["Take to the skies after this, {name}. I'll wave from down here."] = "Alza el vuelo después, {name}. Yo te saludo desde abajo."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Un dragón de nuestro lado, {name}. Nunca dar fue tan buena inversión."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "Regalo para un dragón, {name}. Lo normal es traer oro y rezar por salir con vida."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "Para quien podría llevarme volando al próximo pueblo, {name}. No pido; insinúo."
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "Conocí a varios dragones, {name}. Contigo, por fin, no salí corriendo."
L["For the world's youngest ancient, {name}."] = "Al ser ancestral más joven del mundo, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} entre magos, {name}: como llevar libros a una biblioteca."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "Entre magos, {name}: yo no te pido agua si tú no me la pides."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Dos magos, {name}: portales a todas partes y aun así llegamos tarde."
L["A mage for a mage, {name}. Our old masters would approve."] = "De mago a mago, {name}. Nuestros viejos maestros lo aprobarían."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "Hechizo entre magos, {name}. Finjamos los dos que hacía falta."
L["Neither of us will admit which spells we still read off the page, {name}."] = "Ni tú ni yo diremos qué hechizos seguimos leyendo del libro, {name}."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "Un mago es un erudito, {name}. Dos, una discusión. Este es mi primer argumento."
L["We both know this spell by heart, {name}. Humour me."] = "Los dos nos sabemos este hechizo de memoria, {name}. Dame el gusto."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Más maná para ti, {name}. No te lo gastes todo en una bola de fuego."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "Entre sacerdotes, {name}: ¿quién bendice a los que bendicen? Hoy, yo."
L["Between us, {name}, we'll pretend the warriors listen."] = "Entre nosotros, {name}, fingiremos que los guerreros escuchan."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Cuidar de quien cuida, {name}. Casi parece prohibido."
L["Two priests, {name}. Twice the praying and half the panic."] = "Dos sacerdotes, {name}: doble de plegarias, mitad de pánico."
L["If it all goes wrong, {name}, we two are the last ones standing."] = "Si todo sale mal, {name}, los dos seremos los últimos en pie."
L["Rest your prayers a while, {name}. Mine can keep watch."] = "Deja descansar tus plegarias un rato, {name}. Las mías montan guardia."
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "Te daría un sermón, {name}, pero ya lo oíste. Seguramente lo diste tú."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "Mismos votos y mismas rodillas doloridas, {name}. Algo para las tuyas."
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "Si caigo, {name}, te sabes las palabras. Si caes, yo también. Mejor ninguno."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Dos druidas, {name}. El Círculo Cenarion lo llamaría quórum."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "De druida a druida, {name}: oso o gato, te reconocería por las hojas del pelo."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "De cambiaformas a cambiaformas, {name}: esto sirve para todas las formas."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Nada de apretón de manos, {name}: dos druidas y ni una forma con manos."
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "Entre los dos, {name}, hay forma para cada problema. Sobre todo, osos."
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "¿Colega druida, {name}? Sabrás que los árboles me avisaron de que venías."
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "Si luego me ves de gato, {name}, haz como que no me conoces. Dignidad."
L["Paladin to paladin, {name}: heavy hammer, light heart."] = "Entre paladines, {name}: martillo pesado, corazón ligero."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Bendición para quien bendice, {name}. Ahora brillamos sin piedad."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Dos paladines, {name}. Algún sacerdote respira aliviado."
L["One of us should be humble about this, {name}. Neither of us will be."] = "Alguien debería mostrar humildad aquí, {name}. Y no seremos ni tú ni yo."
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "Mismo juramento, distinto pulido, {name}. El tuyo brilla más; me fijé."
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "Entre los dos, {name}, iluminaríamos una catedral. O un cuartito muy sagrado."
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "Dos armaduras de placas, {name}. Nadie nos oirá llegar. Como siempre."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "Tu libro sagrado y el mío coinciden en esto, {name}. Cosa rara."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "Entre brujos, {name}: aleja tu diablillo del mío. Son unos chismosos."
L["Fellow warlock, {name}? Then you'll know this one's harmless."] = "¿Colega de brujería, {name}? Entonces sabrás que esto es inofensivo."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Dos brujos, {name}. No comparemos fragmentos de alma en público."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Entre tú y yo, {name}, los demonios hacen todo el trabajo. Esto lo hago yo."
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "Brujería por partida doble, {name}. Seré amable: ya vi lo que invocas."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "Un hechizo entre brujos, {name}. Revísalo por si trae maldición. Yo lo haría."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "Colega de brujería, {name}. Tú no preguntarás de dónde salió esto."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "Dos brujos, una buena obra, {name}. La Legión Ardiente estará furiosa."
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "Te invocaría algo de beber, {name}, pero ya sabemos cómo acaba eso."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Dos guerreros, {name}. Algún sanador acaba de suspirar."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "Entre guerreros, {name}: quien entre primero paga la ronda. Invito yo."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Grito a grito, {name}. Dejaremos sordo a todo el lugar."
L["No plan, {name}? Perfect. We'll get along."] = "¿Sin plan, {name}? Perfecto. Nos llevaremos bien."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "Guerreros, {name}: los únicos que creen que gritar es un hechizo. Y acertamos."
L["One warrior to another, {name}: keep your shield up and your temper hot."] = "De guerrero a guerrero, {name}: el escudo en alto y la sangre caliente."
L["You know this one, {name}. You've probably shouted it at me already."] = "Este ya te lo sabes, {name}. Seguro que ya me lo gritaste."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "Nuestro instructor, {name}, estaría orgulloso. A gritos, pero orgulloso."
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "¿Colega de armas, {name}? Entonces el herrero también te tutea."
L["We both served the Scourge, {name}. I won't ask what you did. Don't ask me."] = "Los dos servimos a la Plaga, {name}. No te preguntaré qué hiciste. Tú tampoco."
L["Two death knights, {name}. We've died twice between us. Let's stop there."] = "Dos caballeros de la Muerte, {name}. Entre los dos, dos muertes. Ahí lo dejamos."
L["Between us, {name}, we can drop the echoing voice. Nobody's here to frighten."] = "Entre nosotros, {name}, sobra la voz de ultratumba. Aquí no hay nadie a quien asustar."
L["Mograine would approve, {name}. Grimly; he approves of everything grimly."] = "Mograine lo aprobaría, {name}. Lúgubremente; todo lo aprueba lúgubremente."
L["Two horns and one winter, {name}. Mine sounds today; yours can have tomorrow."] = "Dos cuernos y un solo invierno, {name}. Hoy suena el mío; el tuyo, mañana."
L["The living keep their distance from us, {name}. We needn't keep ours."] = "Los vivos guardan las distancias, {name}. Nosotros no tenemos por qué."
L["We both broke free at Light's Hope, {name}. Every choice since is our own."] = "Nos liberamos en la Capilla de la Esperanza de la Luz, {name}. Ahora decidimos nosotros."
L["Do you still dream, {name}? I only ask our own kind. The living would worry."] = "¿Aún sueñas, {name}? Solo se lo pregunto a los nuestros. Los vivos se preocuparían."
L["Walk with me after dark, {name}. With eyes like ours, we won't need a lantern."] = "Ven conmigo de noche, {name}. Con ojos como los nuestros, no hace falta farol."
L["Fellow monk, {name}? Then we'll spar later and both pretend we held back."] = "¿También eres monje, {name}? Luego peleamos y fingimos que nos contuvimos."
L["Two monks and one teapot, {name}. Whoever pours is the humbler, so I'll pour."] = "Dos monjes y una tetera, {name}. Quien sirve es el más humilde, así que sirvo yo."
L["We should compare masters, {name}. Mine was the hardest. Everyone's was."] = "Deberíamos comparar maestros, {name}. El mío era el más duro. Como el de todos."
L["Meditate beside me later, {name}. If one of us snores, it was the other."] = "Luego medita a mi lado, {name}. Si alguien ronca, habrá sido el otro."
L["Monk to monk, {name}: I won't tell you to breathe. You'd only tell me back."] = "Entre monjes, {name}: no te diré que respires. Me lo dirías tú a mí."
L["Two monks, {name}. Xuen would see a contest, Yu'lon a lesson. I see a friend."] = "Dos monjes, {name}. Xuen vería un duelo; Yu'lon, una lección. Yo, una amistad."
L["Why is every monastery on a mountaintop, {name}? Someone should try a valley."] = "¿Por qué todo monasterio está en una cima, {name}? Alguien debería probar un valle."
L["Do the forms with me at dawn, {name}. Two monks in step is nearly music."] = "Haz las formas conmigo al alba, {name}. Dos monjes acompasados son casi música."
L["Strangers ask you for wisdom too, {name}? I tell them to eat something."] = "¿También te piden sabiduría los desconocidos, {name}? Yo les digo que coman algo."
L["Some of our own followed Sarkareth into the dark, {name}. We chose the sky."] = "Parte de los nuestros siguió a Sarkareth a la oscuridad, {name}. Nosotros, al cielo."
L["Shall we speak Draconic, {name}? The mortals always think we're quarrelling."] = "¿Hablamos en dracónico, {name}? Los mortales siempre creen que discutimos."
L["Between us, {name}, not even the Aspects knew quite what to make of us."] = "Entre nosotros, {name}: ni los Aspectos sabían qué pensar de nosotros."
L["Do you also hold a spell a moment too long, {name}, just to feel it gather?"] = "¿Tú también retienes un hechizo un instante de más, {name}, por sentir cómo crece?"
L["Our people are still choosing their customs, {name}. I'd like this one kept."] = "Nuestro pueblo aún elige sus costumbres, {name}. Esta me gustaría conservarla."
L["Valdrakken was built for grown dragons, {name}. I feel like a hatchling there."] = "Valdrakken se construyó para dragones adultos, {name}. Allí me siento como una cría."
L["Our magic hums when two of us stand close, {name}. I've never learned why."] = "Nuestra magia vibra cuando dos de nosotros están cerca, {name}. Nunca supe por qué."
L["Scalecommanders drilled us both, {name}. Any shout still straightens my back."] = "A los dos nos adiestraron escamandantes, {name}. Aún me cuadro con cualquier grito."
L["Whichever side you took, {name}, we were kin before there were sides to take."] = "Fuera cual fuera tu bando, {name}, éramos familia antes de que hubiera bandos."
L["You heard the earth grumble just now, {name}? Good. I thought it was only me."] = "¿Has oído gruñir a la tierra, {name}? Menos mal. Creía que eran cosas mías."
L["Race you to the next town as wolves, {name}? No lightning. Fair's fair."] = "¿Una carrera de lobos hasta el próximo pueblo, {name}? Sin rayos: juego limpio."
L["My ancestors and yours have surely met by now, {name}. I hope they got along."] = "Seguro que tus ancestros y los míos ya se conocen, {name}. Espero que se lleven bien."
L["Two shamans, one sky, {name}. I asked first, so this storm is mine to give."] = "Dos chamanes, un cielo, {name}. Lo pedí yo primero: esta tormenta la regalo yo."
L["Folk stare when we talk to rocks, {name}. Let them. The rocks answer us."] = "Nos miran raro por hablar con piedras, {name}. Que miren: a nosotros nos contestan."
L["Between two shamans, {name}, a storm is just a conversation. Here's my half."] = "Entre dos chamanes, {name}, una tormenta es solo una charla. Aquí va mi parte."
L["The elements could go quiet any day, {name}. Every day they answer is a gift."] = "Los elementos podrían callar cualquier día, {name}. Cada respuesta suya es un regalo."
L["Ever tried to stop listening, {name}? I did, for a day. Everything got louder."] = "¿Has probado a dejar de escuchar, {name}? Yo, un día. Todo sonaba más fuerte."
L["People want storms stopped or started, {name}. Nobody asks how the sky feels."] = "Todos piden parar o desatar tormentas, {name}. Nadie pregunta cómo está el cielo."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "Sin maná que llenar, {name}, se quedará de adorno, pensando. Como yo."
L["My spell on a warrior, {name}. Call it a small experiment."] = "Mi hechizo en un guerrero, {name}. Llámalo un pequeño experimento."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "Solo sé un hechizo para amigos, {name}. Ira o maná, te lo llevas igual."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "Tu ira no necesita esto, {name}, pero pasar de largo sería descortés."
L["No mana, I know, {name}. A sharp mind never hurt a sharp blade."] = "Sin maná, lo sé, {name}. Una mente aguda nunca estorbó a una hoja afilada."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "Es para el maná, {name}. Ya le darás uso: los pícaros siempre se lo dan."
L["Not your kind of magic, {name}. Call it a very clever lockpick."] = "No es tu tipo de magia, {name}. Tómalo como una ganzúa muy lista."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "¡Pues claro, {name}, bastaba con pedirlo! ¡No te menees!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Aquí tienes, {name}, algo para que no flaquees."
L["My thanks, {name}. Allow me to return the kindness."] = "Te lo agradezco, {name}. Permíteme devolverte la cortesía."
L["Of course, {name}. Stand fast a moment."] = "Por supuesto, {name}. Aguanta un momento."
L["The road ahead is long, {name}. Take this with you."] = "Te espera un largo camino, {name}. Llévate esto."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Te devuelvo tu bondad."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Camina con sigilo bajo las estrellas."
L["The Light rewards kindness, {name}, and so shall I."] = "La Luz recompensa la bondad, {name}, y yo también."
L["Of course, {name}. May the Naaru guide your steps."] = "Por supuesto, {name}. Que los naaru guíen tus pasos."
L["The Light is with you, {name}. Go in peace."] = "La Luz está contigo, {name}. Ve en paz."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Mil gracias, {name}. Gilneas nunca olvida un favor."
L["Lok'tar ogar, {name}! Take this into battle."] = "¡Lok'tar ogar, {name}! Llévate esto a la batalla."
L["The Earth Mother sees your kindness, {name}. I return it."] = "La Madre Tierra ve tu bondad, {name}. Te la devuelvo."
L["Of course, {name}. Stand tall and be at peace."] = "Por supuesto, {name}. Alza la cabeza y ve en paz."
L["Walk with the Earth Mother, {name}."] = "Camina con la Madre Tierra, {name}."
L["Ya be too kind, {name}! Dis one be from me."] = "¡Eres muy amable, {name}! Esta va de mi parte."
L["Sure ting, {name}. Hold still now."] = "Claro que sí, {name}. No te muevas ahora."
L["Da loa be watchin' over ya, {name}."] = "Los loa velan por ti, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tanta cortesía te honra, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Que el sol te guíe."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Tomo nota de tu generosidad, {name}. Suramar recuerda a sus amigos."
L["Thank you, {name}! The caravan always repays a kindness."] = "¡Gracias, {name}! La caravana siempre devuelve un favor."
L["Every traveller needs something for the road, {name}."] = "Todo viajero necesita algo para el camino, {name}."
L["Of course, {name}. Patience, and it is done."] = "Por supuesto, {name}. Un poco de paciencia y listo."
L["Take this, {name}. Even a dragon needs allies."] = "Toma, {name}. Hasta un dragón necesita aliados."
L["Thank you, {name}. The Alliance looks after its own."] = "Gracias, {name}. La Alianza cuida de los suyos."
L["Of course, {name}. Allies help each other."] = "Por supuesto, {name}. Los aliados se ayudan."
L["For the Alliance, {name}! Stay strong out there."] = "¡Por la Alianza, {name}! Mantente fuerte ahí fuera."
L["Strength and honour, {name}. Your kindness is repaid."] = "Fuerza y honor, {name}. Tu bondad queda pagada."
L["Consider it done, {name}. For the Horde."] = "Considéralo hecho, {name}. Por la Horda."
L["For the Horde, {name}! Go with strength."] = "¡Por la Horda, {name}! Ve con fuerza."
L["Thank you, {name}. Good hearts are found everywhere."] = "Gracias, {name}. Hay buenos corazones en todas partes."
L["Gladly, {name}, whatever banner you fly."] = "Con gusto, {name}, sea cual sea tu estandarte."
L["Friends can come from any side, {name}."] = "Hay amigos en todos los bandos, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "Buen viaje, {name}. Llévate {buff} contigo."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Bwonsamdi se va a llevar un buen chasco, {name}. Gracias, mon."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Claro, {name}. No te muevas: el mojo odia los blancos móviles."
L["No worries, {name}. Da loa got ya covered."] = "Tranqui, {name}. Los loa te protegen."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Aléjate del vudú, {name}. ...Menos de este vudú. Este está bien."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "Los loa velan por ti, {name}. Son muy fisgones, mon."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Ojo avizor ahí afuera, {name}. Llévate esto, mon."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Toma, {name}. Anda como si la selva fuera tuya. Como yo."
L["Hey, {name}! Always good to see family, mon."] = "¡Eh, {name}! Siempre es bueno ver a la familia, mon."
L["Dis crew got style, {name}. Now it got mojo too."] = "Este grupo tiene estilo, {name}. Y ahora también mojo."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "Entramos juntos, {name}, salimos juntos. Ese es todo el plan, mon."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "La noche es la mejor hora para el mojo, {name}. Nadie ve de dónde sale."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "El botín a partes iguales, {name}. Yo hago las cuentas. Confía en mí."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "Magni se volvió diamante por la causa, {name}. Esto sale más barato."
