L["Opens Options > Keybindings > Manners, the game's own key bindings."] = "Abre Opciones > Asignación de teclas > Manners, la asignación de teclas del propio juego."
L["Make a macro"] = "Crear una macro"
L["Adds a macro named Manners; put it on an action bar and pressing it clicks the prompt."] = "Añade una macro llamada Manners; ponla en una barra de acción y, al pulsarla, hace clic en el aviso."
L["Ready: %s buffs whoever the prompt shows."] = "Listo: %s da el beneficio a quien muestre el aviso."
L["Your Manners macro is made: open the macro window (/macro) and drag it onto an action bar."] = "Tu macro de Manners está creada: abre la ventana de macros (/macro) y arrástrala a una barra de acción."
L["No key yet: pick one above, make the macro, or just click the prompt."] = "Aún no hay tecla: elige una arriba, crea la macro o simplemente haz clic en el aviso."
L["3. See it"] = "3. Verlo"
L["Stop preview"] = "Parar la vista previa"
L["Show me the prompt"] = "Mostrarme el aviso"
L["Shows a sample prompt so you can see it and put it where you want."] = "Muestra un aviso de ejemplo para que lo veas y lo coloques donde quieras."
L["4. Say thanks (optional)"] = "4. Dar las gracias (opcional)"
L["When I buff someone"] = "Al dar un beneficio"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100En pausa hasta las %s.|r En combate, el aviso se queda como estaba al empezar el combate, y sigue la pausa cuando este termine."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100En pausa hasta las %s.|r El aviso está desbloqueado, así que sigue en pantalla para que lo arrastres, sin lanzar nada, hasta que lo bloquees."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100En pausa hasta las %s.|r No habrá aviso hasta entonces, aunque se sigue detectando quién te da un beneficio."
L["Hide the prompt for a while without turning Manners off."] = "Oculta el aviso un rato sin desactivar Manners."
L["Snooze %s"] = "Pausar %s"
L["Who buffed you, whether you returned it, and who you buffed first."] = "Quién te dio un beneficio, si se lo devolviste y a quién se lo diste tú primero."
L["Minimap and chat"] = "Minimapa y chat"
L["Show minimap button"] = "Mostrar botón del minimapa"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners sigue en el compartimento de accesorios bajo el minimapa de todos modos."
L["Without it, open these settings with %s or Options > AddOns."] = "Sin él, abre estas opciones con %s o en Opciones > Accesorios."
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Una línea cuando alguien te da un beneficio, cuando un favor se da por devuelto, y cuando un clic falla, se salta a alguien o deja un favor pendiente."
L["Only you see these; they show whether a buff was missed or someone could not be reached."] = "Solo tú las ves; indican si se pasó por alto un beneficio o si no se pudo llegar a alguien."
L["Automatic (whatever they are missing)"] = "Automático (lo que le falte)"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(sin aprender)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(solo usuarios de maná)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(solo tu grupo)|r"
L["This character has nothing it can cast on another player."] = "Este personaje no tiene nada que pueda lanzar sobre otro jugador."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Aún no aprendiste ninguno de estos, así que no se ofrecerá nada a nadie."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "Automático nunca ofrece %s -- en una ciudad no le sirve a nadie -- así que no se ofrecerá nada a nadie."
L["Pick it in Buff to offer if you want it given out anyway."] = "Elige ese hechizo en Beneficio que ofrecer si quieres ofrecerlo igualmente."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Todos los hechizos que conoces están desactivados, así que no se ofrece nada hasta que vuelvas a activar uno o aprendas alguno de los demás."
L["Every spell below is switched off, so the prompt will never appear."] = "Todos los hechizos de abajo están desactivados, así que el aviso nunca aparecerá."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. |cffffd100Always offer|r does not check what they carry, so it can replace one of yours."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. |cffffd100Ofrecer siempre|r no comprueba lo que lleva, así que puede reemplazar una de las tuyas."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Where the game hides which blessing somebody carries, it can replace one of yours."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. Donde el juego oculta qué bendición lleva alguien, puede reemplazar una de las tuyas."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Anybody already carrying one of yours is left alone."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. A quien ya lleva una tuya no se le ofrece otra."
L["Automatic may offer, in this order: %s. Each person gets the first one they are missing."] = "Automático puede ofrecer, en este orden: %s. Cada persona recibe el primero que le falte."
L["When the game hides what someone has, it tries the next one each time."] = "Cuando el juego oculta lo que alguien tiene, prueba con el siguiente cada vez."
L["Only |cffffffff%s|r is offered, to everybody, whatever else they are missing. The per-spell switches come back with Automatic."] = "Solo se ofrece |cffffffff%s|r, a todo el mundo, le falte lo que le falte. Las casillas de cada hechizo vuelven a aplicarse con Automático."
L["You picked %s in Buff to offer, but have not learned it, so nothing is offered."] = "Elegiste %s en Beneficio que ofrecer, pero no aprendiste ese hechizo, así que no se ofrece nada."
L["Learn it or set Buff to offer back to Automatic."] = "Aprende ese hechizo o vuelve a poner Beneficio que ofrecer en Automático."
L["Untick to never offer this buff."] = "Desmarca para no ofrecer nunca este beneficio."
L["Automatic (only while I'm the tank)"] = "Automático (solo si soy tanque)"
L["Automatic"] = "Automático"
L["Automatic (%s, the one you had up last)"] = "Automático (%s, el último que tuviste activo)"
L["Automatic (%s, in a dungeon or raid)"] = "Automático (%s, en una mazmorra o banda)"
L["Automatic (%s, outside dungeons and raids)"] = "Automático (%s, fuera de mazmorras y bandas)"
L["Automatic (%s, the best you can use now)"] = "Automático (%s, el mejor que puedes usar ahora)"
L["Automatic (%s, until you have put one up)"] = "Automático (%s, hasta que actives uno)"
L["Automatic reminds you only while your group role is tank; Always reminds you whenever it is not up."] = "Automático te avisa solo si tu rol en el grupo es tanque; Siempre te avisa cada vez que no lo tienes activo."
L["Reminds you when nothing is on the weapon in your main hand and a scroll in your bags fits it. Automatic takes the one you used last, else the best you can use."] = "Te avisa cuando el arma de tu mano derecha no lleva nada y tienes en las bolsas un pergamino que le sirve. Automático elige el último que usaste o, si no, el mejor que puedes usar."
L["Reminds you when no familiar is with you and a scroll for one is in your bags. Automatic takes the one you used last, else the best your level allows."] = "Te avisa cuando no te acompaña ningún familiar y tienes en las bolsas un pergamino para uno. Automático elige el último que usaste o, si no, el mejor que permite tu nivel."
L["Reminds you when none of these is up. Automatic takes the one you had up last."] = "Te avisa cuando no tienes activo ninguno de estos. Automático elige el último que tuviste activo."
L["Until you have had one up: %s in a dungeon or raid, %s elsewhere."] = "Hasta que tengas uno activo: %s en una mazmorra o banda, %s en otros lugares."
L["Don't remind me"] = "No avisarme"
L["Always"] = "Siempre"
L["Reminds you when it is not up."] = "Te avisa cuando no lo tienes activo."
L["%s: the game does not say how many you carry."] = "%s: el juego no dice cuántas unidades llevas."
L["%s: %d in your bags"] = "%s: %d en tus bolsas"
L["%s: none needed -- the game lets you cast without it."] = "%s: no hace falta -- el juego te deja lanzarlo sin componente."
L["You have not learned a group version of your buffs yet."] = "Aún no aprendiste ninguna versión de grupo de tus beneficios."
L["What to cast"] = "Qué lanzar"
L["Buff to offer"] = "Beneficio que ofrecer"
L["You offer %s."] = "Ofreces %s."
L["%s is not offered to players without mana, such as warriors and rogues."] = "%s no se ofrece a jugadores sin maná, como guerreros y pícaros."
L["%s are not offered to players without mana, such as warriors and rogues."] = "%s no se ofrecen a jugadores sin maná, como guerreros y pícaros."
L["Nothing is ticked here, so the prompt will never appear."] = "No hay nada marcado aquí, así que el aviso nunca aparecerá."
L["People who buff me"] = "Quienes me dan un beneficio"
L["Offer a buff back to anyone who buffs you. Yours reaches only your own party (in a raid, your subgroup), so someone outside it is offered once they join."] = "Ofrece devolver el beneficio a quien te dé uno. El tuyo solo llega a tu propio grupo (en una banda, tu subgrupo), así que a alguien de fuera se le ofrece en cuanto se una."
L["Offer a buff back to anyone who buffs you. Yours reaches only your group, so someone outside it is offered once they join."] = "Ofrece devolver el beneficio a quien te dé uno. El tuyo solo llega a tu grupo, así que a alguien de fuera se le ofrece en cuanto se una."
L["Offer a buff back to anyone who buffs you, in your group or not."] = "Ofrece devolver el beneficio a quien te dé uno, esté en tu grupo o no."
L["My party and raid"] = "Mi grupo y banda"
L["Passers-by (players near me, not in my group)"] = "Transeúntes (jugadores cerca de mí, fuera de mi grupo)"
L["Seen through nameplates, your target, focus and mouseover."] = "Se detectan por las placas de nombre, tu objetivo, tu foco y lo que tengas bajo el cursor."
L["Everything you can offer is cast on yourself and reaches only your party, so there is nothing for passers-by."] = "Todo lo que puedes ofrecer se lanza sobre ti y solo llega a tu grupo, así que no hay nada para los transeúntes."
L["Passers-by within"] = "Distancia de los transeúntes"
L["Only passers-by are measured, and only roughly: the game gives no exact distance."] = "Solo se mide a los transeúntes, y solo de forma aproximada: el juego no da la distancia exacta."
L["Only in cities and inns"] = "Solo en ciudades y posadas"
L["Out in the world, passers-by are left alone; your group and people who buff you are offered anywhere."] = "En el mundo abierto no se ofrece nada a los transeúntes; a tu grupo y a quienes te dan un beneficio se les ofrece en cualquier sitio."
L["For a minute, offer your buff to someone who asks for it (\"fort pls\"); off by default because chat is guesswork."] = "Durante un minuto, ofrece tu beneficio a quien lo pida (\"fort pls\"); viene desactivado porque leer el chat es adivinar."
L["Offer your own buffs to you when one is not up: the ones below. They are cast on you, your target is handed back, and nothing is said."] = "Te ofrece tus propios beneficios cuando te falta alguno: los de abajo. Se lanzan sobre ti, se recupera tu objetivo y no se dice nada."
L["Offer your own buffs to you too, when one is not up: the ones below, and the buff you give others. They are cast on you, your target is handed back, and nothing is said."] = "Te ofrece también tus propios beneficios cuando te falta alguno: los de abajo y el que das a los demás. Se lanzan sobre ti, se recupera tu objetivo y no se dice nada."
L["Offer your own buff to you too, when you are missing it or, with top-ups on, it is running low. It is cast on you, your target is handed back, and nothing is said."] = "Te ofrece también tu propio beneficio cuando te falta o, con las renovaciones activadas, cuando se está acabando. Se lanza sobre ti, se recupera tu objetivo y no se dice nada."
L["Off: nothing is offered to you while the game calls you resting, in a city or an inn."] = "Desactivado: no se te ofrece nada mientras el juego te muestra descansando, en una ciudad o una posada."
L["My group and raid"] = "Grupo y banda"
L["Use group buffs"] = "Usar beneficios de grupo"
L["When this many need it"] = "Mínimo de jugadores que lo necesitan"
L["Raid groups I buff"] = "Grupos de banda a los que ofrezco"
L["In a raid, only these groups are offered your buff; people who buff you or ask are offered anyway."] = "En una banda, solo se ofrece tu beneficio a estos grupos; a quien te dé un beneficio o lo pida se le ofrece de todos modos."
L["Who comes first"] = "Quién va primero"
L["My target first"] = "Mi objetivo primero"
L["Your target goes ahead of everyone when the game can see they lack the buff."] = "Tu objetivo pasa por delante de todos cuando el juego puede ver que no tiene el beneficio."
L["Greyed out while |cffffd100Always offer|r is chosen on %s: nothing is read then."] = "En gris mientras esté elegido |cffffd100Ofrecer siempre|r en la pestaña %s: en ese modo no se comprueba nada."
L["Friends and guildmates first"] = "Amigos y compañeros de hermandad primero"
L["Only changes the order; nobody is added or left out."] = "Solo cambia el orden; no se añade ni se deja fuera a nadie."
L["My group first at a ready check"] = "Mi grupo primero en una comprobación de disponibilidad"
L["From a ready check until the pull, group members missing your buff go first."] = "Desde una comprobación de disponibilidad hasta que empieza el combate, van primero los miembros del grupo sin tu beneficio."
L["Group members just revived first"] = "Miembros del grupo recién revividos primero"
L["For two minutes after someone is brought back, they go first if they lack your buff."] = "Durante dos minutos después de que alguien reviva, va primero si no tiene tu beneficio."
L["Skip players below level"] = "Omitir jugadores por debajo del nivel"
L["Someone known only by name is offered anyway."] = "A alguien de quien solo se sabe el nombre se le ofrece de todos modos."
L["Skip players out of range"] = "Omitir jugadores fuera de alcance"
L["If the game cannot tell the range they are still offered."] = "Si el juego no puede saber la distancia, se le sigue ofreciendo."
L["Skip players flagged for PvP"] = "Omitir jugadores con el JcJ activado"
L["Buffing somebody flagged for PvP flags you too. Ignored while you are flagged yourself, as in a battleground, but not while your own flag is running out."] = "Darle un beneficio a alguien con el JcJ activado también activa el tuyo. No se aplica mientras tengas el JcJ activado, como en un campo de batalla, pero sí mientras el tuyo se esté desactivando."
L["Skip my own class when they can cast it too"] = "Omitir mi propia clase si también puede lanzarlo"
L["Somebody of your class can give themselves your buff, so they are left out -- unless they are too low a level for the rank you cast, and then they still get yours. People who buffed you, asked or you targeted are always offered."] = "Alguien de tu clase puede darse tu beneficio a sí mismo, así que se omite, salvo que su nivel sea demasiado bajo para el rango que lanzas: entonces recibe el tuyo. A quien te dio un beneficio, te lo pidió o tienes en el objetivo se le ofrece siempre."
L["Nobody is on the list. Shift-right-click the prompt to add the person it shows, or type a name below."] = "No hay nadie en la lista. Haz Mayús + clic derecho en el aviso para añadir a quien muestre, o escribe un nombre abajo."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Hay una persona en la lista. Nunca se le ofrece nada, ni como transeúnte ni como miembro de tu grupo."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "Hay %d personas en la lista. Nunca se les ofrece nada, ni como transeúntes ni como miembros de tu grupo."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Si alguien de la lista te da un beneficio, se te sigue ofreciendo devolverle el favor. Haz Mayús + clic derecho sobre esa persona en el aviso para descartar ese favor."
L["Add a name"] = "Añadir un nombre"
L["Type it as the prompt shows it and press Enter."] = "Escríbelo como lo muestra el aviso y pulsa Intro."
L["Pick a name"] = "Elegir un nombre"
L["Remove from list"] = "Quitar de la lista"
L["Clear the list"] = "Vaciar la lista"
L["Take everybody off the never-offer list?"] = "¿Quitar a todos de la lista de excluidos?"
L["Already buffed"] = "Ya tiene el beneficio"
L["If they already have it"] = "Si ya lo tiene"
L["Your own buffs are offered when none is up; with Offer a top-up when it runs low, also when one is running out (never an aura or an aspect)."] = "Tus propios beneficios se ofrecen cuando no tienes ninguno activo; con Ofrecer renovarlo cuando se esté acabando, también cuando a alguno le queda poco (nunca un aura ni un aspecto)."
L["Someone who buffed you is always offered a buff back; Diagnostics shows which buffs Manners can see on others."] = "A quien te dio un beneficio siempre se le ofrece devolvérselo; la pestaña Diagnóstico muestra qué beneficios puede ver Manners en los demás."
L["Skip them (default)"] = "Omitir (predeterminado)"
L["Offer a top-up when it runs low"] = "Ofrecer renovarlo cuando se esté acabando"
L["Always offer (costs a lot of mana)"] = "Ofrecer siempre (gasta mucho maná)"
L["Top up when less than this is left (minutes)"] = "Renovar cuando queden menos de (minutos)"
L["Someone whose time left cannot be read is not offered a top-up, unless they buffed you."] = "A alguien cuyo tiempo restante no se puede leer no se le ofrece renovarlo, salvo si te dio un beneficio."
L["Everyone you offer to is offered again and again, even with a fresh buff."] = "Se ofrece una y otra vez a todos a quienes ofreces, aunque acaben de recibir el beneficio."
L["%s does nothing in this mode."] = "%s no hace nada en este modo."
L["Hold back"] = "Cuándo no ofrecer"
L["Casting would dismount you; it is always hidden while dead, on a flight path or in a vehicle."] = "Lanzar te haría desmontar; el aviso siempre se oculta cuando mueres, vas en una ruta de vuelo o estás en un vehículo."
L["Below this, only your own buff and people who buffed you or asked are offered."] = "Por debajo de esto, solo se ofrece a ti y a quienes te dieron un beneficio o lo pidieron."
L["Below this, only people who buffed you or asked are offered."] = "Por debajo de esto, solo se ofrece a quienes te dieron un beneficio o lo pidieron."
L["Off: buffs are offered at any mana."] = "Desactivado: se ofrecen beneficios con cualquier cantidad de maná."
L["Below %d%% only favours, requests and your own buff are offered; the rest come back at %d%%."] = "Por debajo del %d%% solo se ofrecen favores, peticiones y tu propio beneficio; lo demás vuelve al %d%%."
L["Below %d%% only favours and requests are offered; the rest come back at %d%%."] = "Por debajo del %d%% solo se ofrecen favores y peticiones; lo demás vuelve al %d%%."
L["Azeroth (general)"] = "Azeroth (general)"
L["loaded the %s lines."] = "se cargaron las frases de %s."
L["In combat: changes here apply once the fight ends."] = "En combate: los cambios de aquí se aplican cuando termine el combate."
L["Thanks and speech"] = "Agradecimientos y frases"
L["Everyone near you sees it; never in combat or instances, and at most once per person every five minutes."] = "Lo ven todos los que estén cerca; nunca en combate ni en instancias, y como máximo una vez por persona cada cinco minutos."
L["Say a line when I buff someone"] = "Decir una frase al dar un beneficio"
L["Where to say it"] = "Dónde decirlo"
L["Whisper them sends it only to the person you buff."] = "Susurrarle envía la frase solo a la persona a la que das el beneficio."
L["Say"] = "Decir"
L["Whisper them"] = "Susurrarle"
L["Emote"] = "Emoción"
L["Party"] = "Grupo"
L["Raid"] = "Banda"
L["Yell"] = "Gritar"
L["Only when I buff someone back"] = "Solo al devolver un beneficio"
L["Off, you also speak when you buff someone first."] = "Si lo desactivas, también hablas cuando das un beneficio a alguien primero."
L["Turn on friendly nameplates so Manners can tell when strangers are in range to hear you."] = "Activa las placas de nombre amistosas para que Manners sepa cuándo hay desconocidos lo bastante cerca para oírte."
L["The game's own setting, under Nameplates in its options, where you can turn it off again."] = "Es una opción del propio juego, en Placas de nombre dentro de sus opciones, donde puedes volver a desactivarla."
L["Tick Say a line to choose what you say."] = "Marca Decir una frase para elegir qué dices."
L["Lines"] = "Frases"
L["Line set"] = "Juego de frases"
L["Replaces the lines below."] = "Reemplaza las frases de abajo."
L["Replace everything in the box below with the %s lines?"] = "¿Reemplazar todo lo del cuadro de abajo por las frases de %s?"
L["One line is picked at random. Placeholders: {name} their name, {buff} the spell."] = "Se elige una frase al azar. Comodines: {name} su nombre, {buff} el hechizo."
L["A line too long for a macro is skipped; Try a few shows what would go out."] = "Una frase demasiado larga para una macro se deja fuera; Probar unas frases muestra lo que saldría."
L["In character picks one of its %d lines when you click, to fit your race, faction, class and the moment. The box below shows only a few examples; editing it turns In character off."] = "El juego En rol elige una de sus %d frases al hacer clic, según tu raza, facción, clase y el momento. La casilla de abajo solo muestra unos ejemplos; editarla lo desactiva."
L["Your lines (one per line)"] = "Tus frases (una por línea)"
L["Editing these turns In character off and uses only your lines. Continue?"] = "Editarlas desactiva En rol y usa solo tus frases. ¿Continuar?"
L["Go back to In character"] = "Volver a En rol"
L["Try a few lines"] = "Probar unas frases"
L["Prints sample lines in your chat; only you see them."] = "Muestra frases de ejemplo en tu chat; solo tú las ves."
L["Somebody"] = "Alguien"
L["A line goes out only with a buff that can land: in range, ready to cast, and with the mana for it. When Manners cannot tell, the buff goes out without it. Line of sight cannot be checked."] = "La frase solo sale con un beneficio que puede llegar: dentro de alcance, listo para lanzar y con el maná para ello. Si Manners no puede saberlo, el beneficio sale sin ella. La línea de visión no se puede comprobar."
L["In combat: changes here show once the fight ends."] = "En combate: los cambios de aquí se verán cuando termine el combate."
L["Lock position"] = "Bloquear posición"
L["Unlock to drag the prompt; it will not cast until you lock it again."] = "Desbloquea para arrastrar el aviso; no lanzará nada hasta que lo vuelvas a bloquear."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "desbloqueado, pero el accesorio está |cffff8080desactivado|r, así que no hay aviso que arrastrar -- actívalo primero."
L["Where it sits"] = "Posición"
L["Pick Above the action bars to put it back where it started."] = "Elige Sobre las barras de acción para devolverlo a su posición inicial."
L["Dragging the prompt afterwards sets this to Where I dragged it."] = "Si luego arrastras el aviso, esto pasa a Donde lo arrastré."
L["Above the action bars (default)"] = "Sobre las barras de acción (predeterminado)"
L["Where I dragged it"] = "Donde lo arrastré"
L["Size"] = "Tamaño"
L["Scale"] = "Escala"
L["Opacity"] = "Opacidad"
L["Width"] = "Ancho"
L["Height"] = "Alto"
L["Style"] = "Estilo"
L["Panel style"] = "Estilo del panel"
L["Panel colour"] = "Color del panel"
L["Colour marker by reason"] = "Colorear el marcador según el motivo"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Amarillo claro para tu propio objetivo, naranja para un favor pendiente, rosa intenso para quien lo pidió, azul cielo para tu grupo, violeta para los transeúntes -- el orden en que se ofrecen."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Azul claro para tu propio objetivo, ámbar para un favor pendiente, rosa para quien lo pidió, azul más intenso para tu grupo, gris para los transeúntes -- el orden en que se ofrecen."
L["A colour that shows why this person is on the prompt."] = "Un color que indica por qué esta persona está en el aviso."
L["Reason colours"] = "Colores de los motivos"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "La paleta para daltónicos mantiene distinguibles los motivos con daltonismo rojo-verde, con colores que también difieren en luminosidad."
L["Standard"] = "Estándar"
L["Colour-blind friendly"] = "Para daltónicos"
L["Marker colour"] = "Color del marcador"
L["Used when Colour marker by reason is off."] = "Se usa cuando Colorear el marcador según el motivo está desactivado."
L["Colour marker"] = "Marcador de color"
L["Framed panels have no stripe."] = "El panel Enmarcado no tiene franja."
L["Ring around the icon"] = "Anillo alrededor del icono"
L["Stripe on the left edge"] = "Franja en el borde izquierdo"
L["Both"] = "Ambos"
L["None"] = "Ninguno"
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "No queda nada que colorear: el anillo se dibuja detrás del icono, que está desactivado, y el aspecto Enmarcado no tiene franja."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "No queda nada que colorear: redondear el icono sustituye el anillo por una máscara, y el aspecto Enmarcado no tiene franja."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "No queda nada que colorear: el anillo se dibuja detrás del icono, que está desactivado."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "No queda nada que colorear: redondear el icono sustituye el anillo por una máscara."
L["There is nothing left to colour: the framed look has no stripe."] = "No queda nada que colorear: el aspecto Enmarcado no tiene franja."
L["Getting my attention"] = "Llamar mi atención"
L["Flash when someone buffs me"] = "Destellar cuando alguien me da un beneficio"
L["Needs the icon, the stripe or Full animations."] = "Necesita el icono, la franja o las animaciones en Completo."
L["Pulse until I buff them back"] = "Palpitar hasta que se lo devuelva"
L["Flash once"] = "Destellar una vez"
L["Animations"] = "Animaciones"
L["Calm drops the light sweep, the shake and the fade-out."] = "Tranquilo quita el barrido de luz, el temblor y el desvanecimiento."
L["Calm (less movement)"] = "Tranquilo (menos movimiento)"
L["It stays on screen in combat because your key binding would still cast; this only stops the flashes that say what a click did, red if it failed."] = "Sigue en pantalla en combate porque tu tecla asignada seguiría lanzando; esto solo quita los destellos que indican qué hizo un clic, en rojo si falló."
L["When a new person appears on the prompt."] = "Cuando aparece una persona nueva en el aviso."
L["Sound"] = "Sonido"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(no cargado)|r"
L["Only for people who buff me"] = "Solo con quienes me dan un beneficio"
L["Off, every new person makes a sound, passers-by included."] = "Si lo desactivas, suena con cada persona nueva, transeúntes incluidos."
L["%s is silent. Pick a sound above."] = "%s no tiene sonido. Elige un sonido arriba."
L["Text"] = "Texto"
L["Font"] = "Fuente"
L["Font size"] = "Tamaño de fuente"
L["Text colour"] = "Color del texto"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while this is on:"] = "En blanco, el texto se oscurece solo sobre un panel claro. Los demás colores se usan tal como los elijas, salvo en los nombres mientras esto esté activado:"
L["Colour names by class"] = "Colorear nombres según la clase"
L["Show a second line"] = "Mostrar una segunda línea"
L["Needs a prompt at least %d pixels tall."] = "Necesita un aviso de al menos %d píxeles de alto."
L["Icon and waiting list"] = "Icono y lista de espera"
L["Show spell icon"] = "Mostrar icono del hechizo"
L["Icon size"] = "Tamaño del icono"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Se mantiene dentro del aviso -- para un icono más grande, hazlo antes más alto o más ancho."
L["This look sizes the icon from the prompt's height: %d at %d high. Make the prompt taller for a bigger icon."] = "Este aspecto ajusta el icono a la altura del aviso: %d con %d de alto. Haz el aviso más alto para tener un icono más grande."
L["The icon is held at %d to fit a prompt %d wide."] = "El icono se limita a %d para caber en un aviso de %d de ancho."
L["The icon is held at %d to fit a prompt %d high."] = "El icono se limita a %d para caber en un aviso de %d de alto."
L["Round the icon off"] = "Redondear el icono"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Recorta el icono en un círculo. Parece más un retrato que un hechizo, así que viene desactivado de forma predeterminada."
L["Show the global cooldown on the icon"] = "Mostrar el tiempo de reutilización global en el icono"
L["Sweeps the spell icon while the global cooldown runs, like your action bars, so you can see when the next press will go through."] = "Hace un barrido sobre el icono del hechizo mientras corre el tiempo de reutilización global, como en tus barras de acción, para que veas cuándo funcionará la siguiente pulsación."
L["Not in a fight while this is on:"] = "No se muestra en combate si está activado:"
L["Show how many are waiting"] = "Mostrar cuántos esperan"
L["List the next few below"] = "Mostrar los siguientes debajo"
L["How many to list"] = "Cuántos mostrar"
L["Advanced"] = "Avanzado"
L["The defaults suit most players; change these only if something bothers you."] = "Los valores predeterminados sirven a casi todos; cámbialos solo si algo te molesta."
L["In combat: targeting changes apply once the fight ends."] = "En combate: los cambios de selección de objetivo se aplican cuando termine el combate."
L["Put these back to default"] = "Restablecer estos valores"
L["Put every setting on this page back to its default? Where the prompt sits, the lines you wrote and the never-offer list are kept."] = "¿Restablecer todas las opciones de esta página a sus valores predeterminados? La posición del aviso, las frases que escribiste y la lista de excluidos se mantienen."
L["Ignore shields, heals and trinket procs"] = "Ignorar escudos, sanaciones y efectos de abalorios"
L["Only class buffs such as Fortitude count as a favour to return."] = "Solo los beneficios de clase como Entereza cuentan como un favor que devolver."
L["The same goes for /thank people who buff me."] = "Lo mismo vale para \"/thank a quienes me dan un beneficio\"."
L["Offer a buff back for (seconds)"] = "Ofrecer devolver el favor durante (segundos)"
L["How long someone who buffed you stays on offer."] = "Cuánto tiempo se le sigue ofreciendo a quien te dio un beneficio."
L["Stop sooner if they are probably gone"] = "Dejar de ofrecer antes si seguramente se fue"
L["Someone who buffed you rarely can be range-checked, so they are let go after the time below."] = "Rara vez se puede comprobar la distancia de quien te dio un beneficio, así que se le descarta tras el tiempo de abajo."
L["Let them go after (seconds)"] = "Descartarlos tras (segundos)"
L["Counted from their buff, not from when they walked off."] = "Se cuenta desde su beneficio, no desde que se alejó."
L["Turning it off forgets what is already kept."] = "Al desactivarlo se olvida lo que ya estaba guardado."
L["Timing"] = "Tiempos"
L["Don't repeat a spell on someone for (seconds)"] = "No repetir un hechizo sobre alguien durante (segundos)"
L["In case the cast failed; right-clicking the prompt skips the person for this long."] = "Por si falló el lanzamiento; con clic derecho en el aviso se salta a esa persona durante este tiempo."
L["Check for people every (seconds)"] = "Buscar jugadores cada (segundos)"
L["Lower reacts faster and uses a little more CPU."] = "Un valor más bajo reacciona antes y usa un poco más de CPU."
L["Targeting"] = "Selección de objetivo"
L["Hand my target back afterwards"] = "Recuperar mi objetivo después"
L["The prompt has to target someone to buff them; this puts your old target back."] = "El aviso tiene que seleccionar a alguien como objetivo para darle el beneficio; esto recupera tu objetivo anterior."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Todo lo que puedes ofrecer se lanza sobre ti y lo oye tu grupo, así que el aviso nunca cambia tu objetivo y no hay nada que recuperar."
