L["Left / right"] = "Izquierda / derecha"
L["Up / down"] = "Arriba / abajo"
L["Prompt wording"] = "Texto del aviso"
L["Placeholders: {name} their name, {reason} why, {count} how many others are waiting, {class} their class, {buff} the spell, {time} time left on their buff (top-ups only)."] = "Comodines: {name} su nombre, {reason} el motivo, {count} cuántos más esperan, {class} su clase, {buff} el hechizo, {time} lo que le queda a su beneficio (solo renovaciones)."
